prompt --application/shared_components/user_interface/lovs/comp_grp_component_types
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(5087092943835745.4004)
,p_lov_name=>'COMP_GRP_COMPONENT_TYPES'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select case when type_name = ''PAGE'' then',
'           wwv_flow_lang_dev.builder_message(''PAGE_PATTERN'')',
'       else',
'           wwv_flow_lang_dev.builder_message(''COMPONENT_TYPE.''||type_name)',
'       end display_val,',
'       type_name return_val',
'  from wwv_flow_appl_component_types app_comp',
' where app_comp.type_name in ( ''APP_ITEM'',',
'                               ''APP_PROCESS'',',
'                               ''APP_COMPUTATION'',',
'                               ''APP_SETTING'',',
'                               ''BUILD_OPTION'',',
'                               ''LIST'',',
'                               ''SEARCH_CONFIG'',',
'                               ''DATA_LOAD'',',
'                               ''WEB_SOURCE'',',
'                               ''AUTHENTICATION'',',
'                               ''AUTHORIZATION'',',
'                               ''APP_ACL'',',
'                               ''EMAIL_TEMPLATE'',',
'                               ''LOV'',',
'                               ''PLUGIN'',',
'                               ''DUALITY_VIEW'',',
'                               ''JSON_SOURCE'',',
'                               ''AI_CONFIG'',',
'                               ''PLUGIN_SETTINGS'',',
'                               ''SHORTCUT'',',
'                               ''MAP_BACKGROUND'',',
'                               ''REPORT_LAYOUT'',',
'                               ''MESSAGE'' )',
'     or ( app_comp.type_name = ''PAGE'' ',
'          and ( select wwv_flow_platform.get_preference(''ENABLE_PAGE_PATTERNS'') ',
'                  from sys.dual ) = ''Y'' )',
'order by 1'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_return_column_name=>'RETURN_VAL'
