unistr('<p>Per ulteriori informazioni su questo processo, \00E8 possibile visitare la sezione relativa alle guide sulla migrazione dell''<a rel="noopener noreferrer" href="https://apex.oracle.com/ut" target="_blank">applicazione con tema universale</a>.</p>')))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
