,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>'Includi nell''esportazione:'
,p_source=>'select include_in_export_yn from wwv_flow_install where flow_id = :fb_flow_id'
,p_source_type=>'QUERY'
,p_display_as=>'NATIVE_DISPLAY_ONLY'
,p_tag_css_classes=>'fielddatabold'
,p_begin_on_new_line=>'N'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Se necessario, le definizioni degli oggetti di supporto possono essere esportate con l''applicazione. Le definizioni includono tutte le opzioni e tutti gli script di configurazione.</p>',
'<ul>',
'<li>',
unistr('<strong>S\00EC</strong>: include le definizioni degli oggetti di supporto nell''esportazione dell''applicazione. Non carica in modo automatico gli oggetti di supporto quando viene richiamato da una riga di comando.'),
'</li>',
'<li>',
'<strong>No</strong>: non include le definizioni degli oggetti di supporto nell''esportazione.',
'</li>',
'<li>',
unistr('<strong>S\00EC e installa automaticamente all''importazione</strong>: include le definizioni degli oggetti di supporto e una chiamata per installare gli oggetti di supporto nell''esportazione dell''applicazione. Questa opzione \00E8 valida solo per le installaz')
||'ioni dalla riga di comando. Quando viene importata dalla riga di comando, l''applicazione esegue l''installazione o l''upgrade automatico degli oggetti di supporto.',
'</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'based_on', 'PLSQL',
  'format', 'PLAIN',
  'pl_sql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'sys.htp.p( ''<a title="'' || wwv_flow_escape.html( wwv_flow_lang.system_message( p_name => ''F4000.P2.UPDATE_EXPORT_SETTINGS'' ) ) ||',
    '           ''" href="'' ||',
    '           wwv_flow_utilities.prepare_url( ''f?p=&APP_ID.:633:'' || :APP_SESSION ) ||',
    '           ''">'' || wwv_flow_escape.html( wwv_flow_item.text_from_lov( p_value => :P2_INCLUDE_IN_EXPORT,',
    '                                                                      p_lov   => ''EXPORT_SUP_OBJ_OPTIONS'' ) ) ||',
    '           ''</a>'' );')),
  'send_on_page_submit', 'N',
  'show_line_breaks', 'N')).to_clob
);
