wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(4904919441807747.4004)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Delete Checked'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'   for i in 1 .. wwv_flow.g_f01.count loop',
'      wwv_flow_file_editor_dev.delete_file (',
'          p_id     => wwv_flow.g_f01(i),',
'          p_scope  => ''APP'',',
'          p_app_id => :FB_FLOW_ID );',
'    end loop;',
'',
'    if :P40_FILE_STORAGE = ''OBJECT_STORE'' ',
'       and wwv_flow_collection.collection_exists (p_collection_name => ''F4000_OB_FILES'' ) then',
'           wwv_flow_collection.delete_collection (p_collection_name => ''F4000_OB_FILES'' );',
'   end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(4904572338807743.4004)
,p_process_success_message=>'File eliminati'
,p_internal_uid=>4904919441807747.4004
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(29770407854160432.4004)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Delete All'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    if :P40_FILE_STORAGE = ''OBJECT_STORE'' then',
'        for c1 in (select file_name',
'                     from wwv_flow_static_files',
'                    where flow_id           = :FB_FLOW_ID',
'                      and security_group_id = :WORKSPACE_ID ) loop',
'            begin',
'                wwv_flow_object_store.delete_file (',
'                    p_app_id => :FB_FLOW_ID,',
'                    p_path   => c1.file_name );',
'            exception when others then --In case files out of sync, don''t stop deletes',
'                null;',
'            end;',
'        end loop;',
'        if wwv_flow_collection.collection_exists (p_collection_name => ''F4000_OB_FILES'' ) then',
'            wwv_flow_collection.delete_collection (p_collection_name => ''F4000_OB_FILES'' );',
'        end if;',
' ',
'    end if;',
'',
'    delete wwv_flow_static_files',
'     where flow_id           = :FB_FLOW_ID',
'       and security_group_id = :WORKSPACE_ID;',
'  ',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(29769008715122829.4004)
,p_process_success_message=>'File eliminati'
,p_internal_uid=>29770407854160432.4004
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(30816415335489937.4004)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_DOWNLOAD'
,p_process_name=>'Download as Zip'
,p_attribute_01=>'Y'
,p_attribute_02=>'f&FB_FLOW_ID._static_application_files.zip'
,p_attribute_04=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select file_content,',
