,p_validation_name=>'valid import file'
,p_validation_sequence=>20
,p_validation=>'(:P67_IMP_COMPANY is not null) and (:P67_IMP_FLOW_ID is not null) and (:P67_IMP_PAGE_ID is not null)'
,p_validation2=>'PLSQL'
,p_validation_type=>'EXPRESSION'
,p_error_message=>unistr('Il file non \00E8 un file di importazione di &PRODUCT_NAME. valido.')
,p_when_button_pressed=>wwv_flow_imp.id(77701419437857029.4004)
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1596644594608873.4004)
,p_process_sequence=>30
,p_process_point=>'AFTER_FOOTER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Unset flow IDs'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
