wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1104687824864514420.4004)
,p_plug_name=>'Creazione di aree, elementi e pulsanti mediante trascinamento'
,p_parent_plug_id=>wwv_flow_imp.id(1477171307612322861.4004)
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--simple'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4004)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Per trascinare i nuovi componenti, procedere come riportato di seguito.</p>',
'<ol>',
'  <li>Selezionare la scheda Layout nel riquadro centrale.</li>',
'  <li>All''interno della sezione Galleria, in fondo al riquadro, selezionare Area, Elemento o Pulsante.</li>',
'  <li>Fare clic e tenere premuto il pulsante del mouse sul componente da creare, quindi trascinarlo nella scheda Layout.</li>',
'  <li>Spostare il componente nella posizione desiderata all''interno della pagina, quindi rilasciare il mouse.</li>',
unistr('  <li>Immettere i dettagli adeguati nell''editor delle propriet\00E0.</li>'),
'  <li>Fare clic su <strong>Salva</strong> o su <strong>Salva ed esegui pagina</strong>.</li>',
'</ol>      ',
'<p><em>Nota: i componenti possono essere rilasciati solo nelle zone adeguate, indicate in giallo, a seconda del tipo di componente.',
'  Dopo essere passati con il puntatore del mouse sopra una zona di rilascio esistente, l''area visualizzata in giallo cambia mostrando una casella nera nella zona di rilascio.<br/>',
'  Se si desidera posizionare il nuovo componente accanto a un componente esistente, trascinare il nuovo componente a destra e alla stessa altezza del componente esistente, quindi attendere alcuni secondi fino alla visualizzazione di una nuova zona di'
||' rilascio.</em></p>',
'<p>La scheda Layout include anche menu contestuali. Selezionare un componente e fare clic su di esso con il pulsante destro del mouse per eliminare, spostare o copiare il componente in altre aree o in nuove aree nella pagina.</p>',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">Ulteriori informazioni...</a></p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1104687995506514421.4004)
,p_plug_name=>'Creazione di diramazioni, calcoli e processi precedenti al rendering'
,p_parent_plug_id=>wwv_flow_imp.id(1477171307612322861.4004)
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--simple'
