,p_plug_display_sequence=>40
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Per creare diramazioni, calcoli e processi da eseguire prima della visualizzazione della pagina, procedere come segue.</p>',
'<ol>',
'  <li>Selezionare la scheda Rendering nel riquadro sinistro.</li>',
'  <li>Espandere il nodo <strong>Precedente al rendering</strong> all''inizio della struttura Rendering.</li>',
'  <li>Fare clic con il pulsante destro del mouse su Prima dell''intestazione, Dopo l''intestazione o Prima delle aree per visualizzare il menu contestuale del rispettivo punto di elaborazione.</li>',
'  <li>Selezionare <strong>Crea diramazione</strong>, <strong>Crea calcolo</strong> o <strong>Crea processo</strong>.</li>',
unistr('  <li>Immettere i dettagli adeguati nell''editor delle propriet\00E0.</li>'),
'  <li>Fare clic su <strong>Salva</strong> o <strong>Salva ed esegui pagina</strong>.</li>',
'</ol>',
unistr('<p><em>Nota: se la visualizzazione predefinita \00E8 stata modificata in modo da raggruppare i componenti per tipo, \00E8 necessario accedere alla scheda Elaborazione per gestire i componenti precedenti al rendering.</em></p>'),
unistr('<p>\00C8 possibile utilizzare i menu contestuali anche per duplicare, eliminare e copiare un componente in altre pagine.</p>')))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
