 p_id=>wwv_flow_imp.id(18861717044687109.4004)
,p_name=>'P122_REFERENCE_ID'
,p_item_sequence=>28
,p_item_plug_id=>wwv_flow_imp.id(18886415062746206.4004)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Fare riferimento al modello di etichetta principale da'
,p_source=>'REFERENCE_ID'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_named_lov=>'FLOW_SUBSCRIBE_FROM_CAL_TEMPLATES'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ''- '' || lower(wwv_flow_lang.system_message(''NO_TEMPLATE'')) || '' -'' d, 0 r ',
'  from sys.dual ',
' union all',
'select flow_id ||'' : ''|| nvl2( theme_id, '' ('' || theme_id || '')'', '''' ) d, id r',
'  from wwv_flow_cal_templates',
' where flow_id          != :FB_FLOW_ID',
'   and security_group_id = :WORKSPACE_ID',
'   and flow_id in ( select f.id',
'                      from wwv_main_apps_dev f',
'                     where security_group_id = :WORKSPACE_ID ',
'                       and build_status not in (''RUN_ONLY'',''RUN_AND_HIDDEN'') ',
'                       and exists ( select 1 ',
'                                      from wwv_flow_developers',
'                                     where userid            = :FLOW_USER ',
'                                       and ( flow_id is null or flow_id = f.id ) ',
'                                       and security_group_id = :WORKSPACE_ID)',
'    )'))
,p_cSize=>30
,p_cMaxlength=>255
,p_cHeight=>1
,p_tag_attributes=>'onchange="htmldb_item_change(this)"'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<div class="htmldbInfoBodyP">\00C8 possibile selezionare un modello esistente in questa area di lavoro oppure un modello diverso nello schema dell''area di lavoro. Se si seleziona un modello esistente, si diventa sottoscrittori di tale modello.</div>'),
'<div class="htmldbInfoBodyP">Per caricare una nuova copia del modello primario, fare clic su <span class="fielddatabold">Aggiorna</span>.</div>'))
,p_encrypt_session_state_yn=>'N'
