wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(185260418354820054.4004)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Copy Shortcut'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_shortcut_id number;',
'begin',
'    for i in 1..wwv_flow.g_f03.count loop',
'        if wwv_flow.g_f02(i) in (''Y'',''SUBSCRIBE'') then',
'            l_shortcut_id := wwv_flow_copy_metadata.copy_component (',
'                                 p_component_type       => wwv_flow_shared_component_api.c_shortcut,',
'                                 p_from_id              => wwv_flow.g_f03(i),',
'                                 p_from_app_id          => :F4000_P132_COPY_FROM_FLOW_ID,',
'                                 p_to_app_id            => :FB_FLOW_ID,',
'                                 p_new_name             => nvl(wwv_flow.g_f01(i),''Copy of ''||i),',
'                                 p_subscribe            => wwv_flow.g_f02(i) = ''SUBSCRIBE'' );',
'        end if;',
'    end loop;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Errore durante la copia della scorciatoia o delle scorciatoie.'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(185258008310820016.4004)
,p_process_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_fnd boolean := false;',
'begin',
'  for i in 1.. wwv_flow.g_f02.count loop',
'    if wwv_flow.g_f02(i) != ''N'' then',
'      l_fnd := true;',
'      exit;',
'    end if;',
'  end loop;',
'  return l_fnd;',
'end;'))
,p_process_when_type=>'FUNCTION_BODY'
,p_process_when2=>'PLSQL'
,p_process_success_message=>'La scorciatoia o le scorciatoie sono state copiate.'
