,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(770240542605907344.4004)
,p_plug_display_sequence=>100
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Impossibile installare l''applicazione poich\00E9 esiste gi\00E0 in un''altra area di lavoro. Per installare l''applicazione, effettuare le seguenti operazioni:</p>'),
'<ol>',
'<li>Rimuovere l''applicazione esistente dall''area di lavoro in cui si trova.</li>',
'</ol>',
'OPPURE',
'<ol>',
unistr('<li>Modificare l''ID applicazione del file di esportazione. Un ID applicazione attualmente disponibile \00E8 &P154_FLOW_ID..</li>'),
'<li>Caricare il file di esportazione modificato nel repository e reinstallare l''applicazione.</li>',
'</ol>'))
,p_plug_display_condition_type=>'FUNCTION_BODY'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_security_group_id number := null;',
'begin',
'  for c1 in (select security_group_id',
'             from wwv_flows',
'             where id = :P49_NEW_FLOW_ID)',
'  loop',
'    l_security_group_id := c1.security_group_id;',
'  end loop;',
'  if l_security_group_id is not null then',
'    if l_security_group_id != :P49_LOGGED_IN_COMPANY then',
'       return true;    ',
'    end if;',
'  end if;',
'  return false;',
'end;'))
,p_plug_display_when_cond2=>'PLSQL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
