'                               p_file_name => file_name )',
'                       from wwv_flow_static_files',
'                      where security_group_id = :WORKSPACE_ID',
'                        and flow_id           = :FB_FLOW_ID',
'                        and file_name         = ''icons/app-icon-32.png'' ), wwv_flow_lang.system_message(''UI.APP.ICON.NOT_FOUND'') ) reference,',
'        wwv_flow_lang.system_message(''UI.APP.ICON.FAVICON'') purpose,',
'        ( select ''<img class="app-icon-favicon"'' ||',
'                 wwv_flow_plugin_util.get_html_attr(',
'                     p_name  => ''aria-label'',',
'                     p_value => wwv_flow_lang.system_message( ''UI.APP.ICON.FAVICON'' ) ) ||',
'                 '' src="wwv_flow_file_mgr.get_file?p_security_group_id=&WORKSPACE_ID.&p_flow_id=&FB_FLOW_ID.&p_fname=''||file_name||''">''',
'            from wwv_flow_static_files',
'           where security_group_id = :WORKSPACE_ID',
'             and flow_id           = :FB_FLOW_ID',
'             and file_name         = ''icons/app-icon-32.png'' ) preview',
'  from sys.dual',
'union all',
'select  ''icons/app-icon-144-rounded.png'' file_name,',
'        ''144x144'' file_size,',
'        coalesce ( ( select wwv_flow_file_editor_dev.get_file_reference (',
