wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1407141969590715.4004)
,p_name=>'P197_AUTO_DISMISS_SUCCESS_MSG'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(72766345492681456.4004)
,p_item_source_plug_id=>wwv_flow_imp.id(28154408216362812.4004)
,p_item_default=>'N'
,p_prompt=>'Chiudi automaticamente i messaggi di operazione riuscita'
,p_source=>'AUTO_DISMISS_SUCCESS_MSG'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_YES_NO'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Quando l''impostazione \00E8 <strong>Attivo</strong>, tutti i messaggi di operazione riuscita in questa applicazione vengono chiusi automaticamente dopo 5 secondi. Se un utente interagisce con un messaggio prima che venga chiuso, il periodo di tempo vi')
||'ene reimpostato e saranno disponibili altri 5 secondi prima della chiusura del messaggio.</p>',
unistr('<p>Quando l''impostazione \00E8 <strong>Non attivo</strong>, i messaggi di operazione riuscita rimarranno visibili finch\00E9 l''utente dell''applicazione non li chiude manualmente.</p>'),
unistr('<p>\00C8 importante prendere in considerazione l''impatto in termini di accesso facilitato che la chiusura automatica potrebbe avere sugli utenti. Alcuni potrebbero non vedere n\00E9 leggere un messaggio di operazione riuscita prima che venga chiuso e probabi')
||unistr('lmente perdere le informazioni incluse nel messaggio. Se si attiva la chiusura automatica, valutare la possibilit\00E0 di fornire agli utenti impostazioni che consentano loro di decidere se attivare o meno la chiusura automatica utilizzando l''interfaccia')
||' API JavaScript apex.message <code>setDismissPreferences</code>.</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
