,p_field_template=>wwv_flow_imp.id(561549716994252345.4004)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<div class="htmldbInfoBodyP">Definisce il modello di pulsante che viene visualizzato se il tipo di pulsante \00E8 ''Normale''. \00C8 possibile includere stringhe di sostituzione dell''applicazione standard. Ad esempio, i valori di &amp;ITEM_NAME possono essere ')
||'sostituiti in fase di rendering.</div>',
'<div class="htmldbInfoBodyP">I modelli di pulsanti supportano le seguenti stringhe di sostituzione:',
'<ul class="noIndent">',
'<li><code>#LABEL#</code> viene sostituita con un''etichetta di pulsante.</li>',
unistr('<li><code>#LINK#</code> viene sostituita con il codice JavaScript generato, utilizzato per controllare il funzionamento del pulsante. In base all''azione del pulsante, questo codice pu\00F2 essere una chiamata ad <code>apex.submit</code> per sottomettere ')
||'la pagina, un <code>reindirizzamento</code> a una pagina, un <code>reindirizzamento</code> a qualche altro URL fornito, l''esecuzione di codice JavaScript personalizzato o di <code>void(0)</code> per non effettuare nulla (nei casi in cui il funzioname'
||unistr('nto pu\00F2 essere definito separatamente con le azioni dinamiche). Nota: <code>#LINK#</code> applica il prefisso ''javascript:'' al codice JavaScript generato, pertanto \00E8 necessario utilizzarla in un attributo <code>href</code>.</li>'),
unistr('<li><code>#JAVASCRIPT#</code> viene sostituita con il codice JavaScript generato, utilizzato per controllare il funzionamento del pulsante. In base all''azione del pulsante, questo codice pu\00F2 essere una chiamata ad <code>apex.submit</code> per sottome')
||'ttere la pagina, un <code>reindirizzamento</code> a una pagina, un <code>reindirizzamento</code> a qualche altro URL fornito, l''esecuzione di codice JavaScript personalizzato o di <code>void(0)</code> per non effettuare nulla (nei casi in cui il funz'
||unistr('ionamento pu\00F2 essere definito separatamente con le azioni dinamiche). '),
unistr('<p><strong>Nota</strong>: <code>#JAVASCRIPT#</code> non applica il prefisso ''javascript:'' al codice JavaScript generato, pertanto \00E8 necessario utilizzarla in un attributo <code>onclick</code>.</li>'),
unistr('<li><code>#ONCLICK#</code> indica che il pulsante include un evento onclick con il codice JavaScript, che verr\00E0 inserito in una tag di script nella parte inferiore della pagina.</li>'),
unistr('<li><code>#BUTTON_ID#</code> viene sostituita con l''ID del pulsante, che pu\00F2 essere l''ID statico del pulsante se definito oppure, in caso contrario, un ID generato internamente nel formato <pre>''B'' || [ID interno del pulsante]</pre></li>'),
unistr('<li><code>#BUTTON_CSS_CLASSES#</code> viene sostituita con la propriet\00E0 delle classi CSS del pulsante riportata nella definizione di pulsante.</li>'),
unistr('<li><code>#BUTTON_ATTRIBUTES#</code> viene sostituita con la propriet\00E0 degli attributi del pulsante riportata nella definizione di pulsante.</li>'),
unistr('<li><code>#ICON_CSS_CLASSES#</code> viene sostituita con la propriet\00E0 delle classi CSS dell''icona riportata nella definizione di pulsante.</li>'),
'<li><code>#BUTTON_NAME#</code> viene sostituita con il nome del pulsante riportato nella definizione di pulsante.</li>',
'</ul>',
'</div>',
'<div class="htmldbInfoBodyP">Tutte le stringhe di sostituzione devono essere in maiuscolo.</div>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
,p_item_comment=>'Generated 17-JUL-2002 17:42:24'
);
