,p_process_name=>'Create UT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_latest_ut_app_id   number;',
'    l_latest_ut_theme_id number;',
'begin',
'    select flow_id,',
'           theme_id',
'      into l_latest_ut_app_id,',
'           l_latest_ut_theme_id',
'      from wwv_flow_themes',
'     where theme_internal_name =  ''UNIVERSAL_THEME''',
'       and security_group_id   =  12',
'       and flow_id             !=  8842',
'    order by flow_id desc',
'    fetch first row only;',
'',
'    wwv_flow_theme_manager.copy_theme(',
'        p_from_application_id => l_latest_ut_app_id,',
'        p_from_theme_id       => l_latest_ut_theme_id,',
'        p_to_application_id   => :FB_FLOW_ID,',
'        p_to_theme_id         => l_latest_ut_theme_id,',
'        p_subscribe_theme     => true );',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(73940412712235913.4004)
,p_process_success_message=>'Tema universale copiato.'
,p_internal_uid=>73940397607235912.4004
);
