'           wwv_flow_theme_manager.get_central_workspace_id( :F4000_P219_COPY_FROM_FLOW_ID, :P413_COPY_FROM_THEME )   as workspace_id',
'      from sys.dual',
')',
'',
'select bt.id,',
'       case',
'           when bt.security_group_id in ( 11, 12 ) then m.theme_repository',
'           else to_char( bt.flow_id )',
'       end flow_id,',
'       bt.template_name from_name,',
'       wwv_flow_lang.system_message(''F4000.P158.COPY_OF'',bt.template_name) to_name,',
