'       ( select wwv_flow_lang_dev.builder_message( ''SUBSCRIBED_FROM.THEME_REPOSITORY'' ) theme_repository',
'           from sys.dual ) m,',
'       central_theme ct',
' where ( bt.flow_id, bt.theme_id, bt.security_group_id ) in',
'       (',
'        ( :F4000_P219_COPY_FROM_FLOW_ID, :P413_COPY_FROM_THEME, :WORKSPACE_ID ),',
