,p_field_template=>wwv_flow_imp.id(561549638722251517.4004)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<div class="htmldbInfoBodyP">Definisce il modello di colonna. \00C8 possibile utilizzare le seguenti stringhe di sostituzione:'),
'<ul class="noIndent">',
unistr('<li>#COLUMN_VALUE#: verr\00E0 sostituita dal valore di una colonna</li>'),
'<li>#ALIGNMENT#: specificata dall''utente, determina l''allineamento di una colonna</li>',
'<li>#COLNUM#: numero della colonna corrente</li>',
'<li>#COLUMN_HEADER#: intestazione della colonna</li>',
'<li>#COLCOUNT#: numero di colonne</li>',
'<li>#ROWNUM#: numero della riga corrente</li>',
'<li>#ACCESSIBLE_HEADERS#: aggiunge le intestazioni di righe e colonne per la cella</li>',
'</ul>',
'</div>',
'<div class="htmldbInfoBodyP">Un esempio tipico potrebbe essere il seguente:</div>',
'<pre>&lt;td #ALIGNMENT#&gt;#COLUMN_VALUE#&lt;/td&gt;</pre>',
'',
unistr('<div class="instructiontext">\00C8 possibile specificare fino a quattro modelli di colonna, ognuno dei quali pu\00F2 essere condizionale. Ad esempio, si possono stabilire colori dello sfondo diversi per le righe pari e quelle dispari o anche evidenziare le r')
||'ighe che rispettano una determinata condizione PL/SQL.</div>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
