wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2346393976043681.4004)
,p_name=>'F4000_P258_ROW_TEMPLATE_BEFORE_ROWS'
,p_item_sequence=>90
,p_item_plug_id=>wwv_flow_imp.id(28562360017818729.4004)
,p_use_cache_before_default=>'NO'
,p_item_default=>'<table>'
,p_prompt=>'Prima delle righe'
,p_source=>'ROW_TEMPLATE_BEFORE_ROWS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>90
,p_cMaxlength=>32767
,p_cHeight=>3
,p_tag_attributes=>'onchange="htmldb_item_change(this)"'
,p_field_template=>wwv_flow_imp.id(561549638722251517.4004)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Immettere il codice HTML che verr\00E0 visualizzato una volta all''inizio di un modello di report.</p>'),
unistr('<p>L''uso pi\00F9 comune di questo attributo \00E8 l''apertura di una tabella HTML:</p>'),
'<pre>&lt;table&gt;</pre>',
'<p>Se si desidera visualizzare l''impaginazione sopra i report, il modello deve specificare la stringa di sostituzione seguente:</p>',
'<pre>#TOP_PAGINATION#</pre>',
unistr('<p>La stringa di sostituzione #TOP_PAGINATION# generer\00E0 il codice HTML che inizia con una tag di apertura &lt;tr&gt; e finisce con una tag di chiusura &lt;/tr&gt;. Idealmente, \00E8 preferibile includere una tag di apertura di tabella e la stringa di sos')
||'tituzione #TOP_PAGINATION#, come mostra il seguente esempio:</p>',
'<pre>&lt;table&gt;#TOP_PAGINATION#</pre>',
unistr('<p>\00C8 possibile utilizzare la stringa di sostituzione #CSV_LINK# se si desidera supportare l''esportazione del report in formato CSV per l''uso nei fogli di calcolo.</p>'),
unistr('<p>\00C8 inoltre possibile utilizzare la stringa #REPORT_ATTRIBUTES#. Questa stringa di sostituzione viene impostata per singola area di report nella pagina degli attributi di report.</p>'),
unistr('<p>Infine, \00E8 possibile utilizzare anche la stringa di sostituzione #COMPONENT_CSS_CLASSES#. Questa stringa di sostituzione viene impostata nella pagina di modifica dell''area.</p>')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
