wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(545420131479257324.4004)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(543179732397973700.4004)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Seed Translatable Text'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for lang_map in (',
'    select translation_flow_language_code',
'      from wwv_flow_language_map',
'     where id = :ID',
'       and security_group_id = :WORKSPACE_ID )',
'loop',
'    ',
'    wwv_flow_translation_utilities.seed_translations (',
'        p_flow_id     => :FB_FLOW_ID,',
'        p_language    => lang_map.translation_flow_language_code,',
'        p_insert_only => ''NO'');',
'',
'    exit;',
'',
'end loop;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Errore durante il popolamento del testo traducibile.'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'(:APEX$ROW_SELECTOR = ''X'' and :REQUEST in (''SEED'',''SEED_HOT''))'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_exec_cond_for_each_row=>'Y'
,p_only_for_changed_rows=>'N'
,p_process_success_message=>'Popolamento del testo traducibile riuscito.'
,p_internal_uid=>545420131479257324.4004
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(546982023944586238.4004)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(543179732397973700.4004)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Publish Translated Versions'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for lang_map in (',
'    select translation_flow_id,',
'           security_group_id',
'      from wwv_flow_language_map',
'     where id = :ID',
'       and security_group_id = :WORKSPACE_ID )',
'loop',
'',
'    wwv_flow_translation_utilities.publish_application (',
'        p_from_flow_id       => :FB_FLOW_ID,',
'        p_translated_flow_id => lang_map.translation_flow_id,',
'        p_security_group_id  => lang_map.security_group_id );',
'',
'    exit;',
'',
'end loop;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Errore durante la pubblicazione dell''applicazione o delle applicazioni.'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'(:APEX$ROW_SELECTOR = ''X'' and :REQUEST in (''PUBLISH'',''PUBLISH_HOT''))'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_exec_cond_for_each_row=>'Y'
,p_only_for_changed_rows=>'N'
,p_process_success_message=>'Pubblicazione dell''applicazione o delle applicazioni riuscita.'
,p_internal_uid=>546982023944586238.4004
);
end;
