wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(107055010603385644.4004)
,p_name=>'P506_FLOW_LANGUAGE_DERIVED_FROM'
,p_item_sequence=>419
,p_item_plug_id=>wwv_flow_imp.id(107024218396385528.4004)
,p_use_cache_before_default=>'NO'
,p_item_default=>'0'
,p_prompt=>'Lingua dell''applicazione derivata da'
,p_source=>'FLOW_LANGUAGE_DERIVED_FROM'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'LANGUAGE_DERIVED_FROM'
,p_lov=>'.'||wwv_flow_imp.id(73566910745435962)||'.'
,p_cSize=>32
,p_cMaxlength=>2000
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Specifica in che modo &PRODUCT_NAME. deriva la lingua tradotta dell''applicazione. La lingua primaria dell''applicazione pu\00F2 essere statica, derivata dalla lingua del browser Web o determinata da una preferenza utente o un elemento. Di seguito vengono ')
||'indicate le opzioni disponibili.',
'<ul>',
unistr('<li><strong>Nessun NLS (applicazione non tradotta)</strong>: selezionare questa opzione se l''applicazione non verr\00E0 tradotta.</li>'),
'<li><strong>Lingua primaria dell''applicazione</strong>: la lingua tradotta dell''applicazione viene determinata in base all''attributo Lingua primaria dell''applicazione.</li>',
'<li><strong>Browser (utilizza preferenza lingua del browser)</strong>: la lingua tradotta dell''applicazione viene determinata in base alla lingua del browser Web dell''utente.</li>',
'<li><strong>Preferenza applicazione (utilizza FSP_LANGUAGE_PREFERENCE)</strong>: la lingua tradotta dell''applicazione viene determinata in base al valore definito mediante l''API <code>APEX_UTIL.SET_PREFERENCE</code>. Utilizzare questa opzione per man'
||unistr('tenere la preferenza della lingua selezionata per pi\00F9 login.</li>'),
'<li><strong>Preferenza elemento (utilizza elemento contenente preferenza)</strong>: la lingua tradotta dell''applicazione viene determinata in base all''elemento a livello di applicazione denominato <code>FSP_LANGUAGE_PREFERENCE</code>. L''utilizzo di q'
||'uesta opzione richiede &PRODUCT_NAME. per determinare la preferenza della lingua appropriata ogni volta che l''utente esegue il login. </li>',
unistr('<li><strong>Sessione</strong>: la lingua tradotta dell''applicazione viene determinata in base all''impostazione della sessione. La lingua della sessione di &PRODUCT_NAME. si pu\00F2 impostare mediante la procedura <code>APEX_UTIL.SET_SESSION_LANG</code> o')
||' il parametro <code>P_LANG</code> della procedura <code>F</code> nell''URL.</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
