wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(2202389608388915.4004)
,p_name=>'Report screenshot'
,p_region_name=>'ScreenshotsReport'
,p_parent_plug_id=>wwv_flow_imp.id(2200905572388901.4004)
,p_template=>wwv_flow_imp.id(208928010704475743.4004)
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:a-Report--inline:a-Report--horizontalBorders:a-Report--stretch'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ps.id,',
'       ps.label,',
'       wwv_flow_file_editor_dev.get_file_reference (',
'                               p_scope     => ''APP'',',
'                               p_app_id    => :FB_FLOW_ID,',
'                               p_file_name => ps.screenshot_url ) screenshot_url,',
'       ps.display_sequence as display_sequence_screenshot,',
'       ( select ''<img class="a-PWAScreenshot-preview" aria-hidden="true" src="''||wwv_flow_escape.html_attribute(''wwv_flow_file_mgr.get_file?p_security_group_id=''||:WORKSPACE_ID||''&p_flow_id=''||:FB_FLOW_ID||''&p_fname=''||a.file_name||''&v=''||wwv_flows_r'
||'elease||f.shared_components_scn)||''" alt="''||wwv_flow_escape.html_attribute(ps.label)||''"/><br/><span class="a-PWAScreenshot-preview--ratio a-Alert--warning"></span>''',
'            from wwv_flow_static_files a',
'           where a.security_group_id = :WORKSPACE_ID',
'             and a.flow_id           = :FB_FLOW_ID',
'             and a.file_name         = ps.screenshot_url ) preview',
'  from wwv_flow_pwa_screenshots ps,',
'       wwv_flows f',
' where ps.flow_id           = :FB_FLOW_ID',
'   and ps.security_group_id = :WORKSPACE_ID',
'   and f.id                = ps.flow_id',
'   and f.security_group_id = ps.security_group_id',
' order by ps.display_sequence'))
,p_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1',
'  from wwv_flow_pwa_screenshots',
' where flow_id           = :FB_FLOW_ID',
'   and security_group_id = :WORKSPACE_ID'))
,p_display_condition_type=>'EXISTS'
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(123728124628276646.4004)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_plug_query_strip_html=>'N'
);
