,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_css_classes=>'apex-button-group'
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>I service worker sono file JavaScript che possono eseguire il codice anche quando l''applicazione non \00E8 in uso.</p>'),
'<p>Possono ascoltare eventi come il recupero delle risorse o la gestione delle notifiche.</p>',
unistr('<p>Selezionare la strategia di service worker pi\00F9 appropriata per le esigenze dell''applicazione.</p>'),
'<ul>',
unistr('    <li><span>Valore predefinito: il motore &PRODUCT_NAME. generer\00E0 un service worker se si segue la strategia riportata di seguito.</span>'),
'        <ul>',
'            <li>Installare e attivare il service worker.</li>',
'            <li>Utilizzare le risorse della cache, se esistente.</li>',
'            <li>Altrimenti, utilizzare le risorse della rete, quindi inserirle nella cache.</li>',
'            <li>Utilizzare una pagina non in linea in caso di problemi di rete.</li>',
'        </ul>',
'    </li>',
'    <li>Configura hook: inserire dei segnaposto nel codice del service worker per aggiungere hook personali. Le posizioni degli hook vengono fornite da &PRODUCT_NAME.</li>',
unistr('    <li>URL file: fornire un riferimento URL a un file contenente l''interfaccia degli hook del service worker. Ci\00F2 \00E8 utile per condividere gli hook del service worker in pi\00F9 applicazioni. Se si utilizza il riferimento al file, assicurarsi di seguire ')
||unistr('l''architettura dell''interfaccia in modo appropriato; altrimenti, il service worker non riuscir\00E0 in runtime.</li>'),
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'number_of_columns', '3',
  'page_action_on_selection', 'NONE')).to_clob
);
