wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(11363569550866137.4004)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Delete file'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_file_id number;',
'begin',
'    select id ',
'      into l_file_id',
'      from wwv_flow_static_files ',
'     where security_group_id = :workspace_id ',
'       and flow_id           = :fb_flow_id',
'       and file_name         = :p508_icon_url;',
'',
'    wwv_flow_file_editor_dev.delete_file (',
'       p_id     => l_file_id,',
'       p_scope  => ''APP'',',
'       p_app_id => :fb_flow_id );',
'exception when others then ',
