wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1875072844167005.4004)
,p_name=>'P509_AUTH_CONFIG_PROCEDURE'
,p_item_sequence=>110
,p_item_plug_id=>wwv_flow_imp.id(107178726415706930.4004)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Procedura di configurazione'
,p_source=>'AUTH_CONFIG_PROCEDURE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>32
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Immettere il nome di una procedura che configuri l''autenticazione in runtime.',
unistr('Il codice riportato di seguito \00E8 per un''applicazione che implementa la'),
'multi-tenancy e supporta variazioni differenti di <em>Connessione Social</em> per i tenant.',
'Il nome dominio nell''URL viene utilizzato per recuperare i dati di configurazione (esempi di URL: ',
'https://cust-01.example.com, https://cust-02.example.com, ...):',
'</p><pre><code>',
'procedure my_auth_config (',
'    p_conf in out nocopy apex_authentication.t_configuration )',
'is',
'    l_host varchar2(32767) := sys.owa_util.get_cgi_env(''HTTP_HOST'');',
'begin',
'    for i in ( select discovery_url,',
'                      auth_scheme_name,',
'                      credential,',
'                      tenant_id',
'                 from customer_tenants',
'                where hostname = l_host )',
'    loop',
'        p_conf.authentication_name := i.auth_scheme_name;',
'        p_conf.substitutions := apex_t_varchar2 (',
'                                    ''DISCOVERY_URL''       , i.discovery_url,',
'                                    ''CREDENTIAL_STATIC_ID'', i.credential );',
'        p_conf.tenant_id := i.tenant_id;',
'    end loop;',
'end my_auth_config;',
'</code></pre><p>',
unistr('La procedura pu\00F2 modificare 3 attributi del parametro IN/OUT <code>p_conf</code>,'),
'tutti facoltativi.',
'<ul>',
'    <li><code>authentication_name</code>:',
'    consente di assegnare il nome di uno schema di autenticazione nell''applicazione.',
unistr(' Il nome assegnato verr\00E0 utilizzato al posto dello schema predefinito.'),
'    Tenere presente che l''opzione <em>Passa durante la sessione</em> deve essere abilitata per lo schema interessato.',
'    </li><li><code>substitutions</code>:',
'    consente di assegnare le coppie nome/valore utilizzando <code>apex_t_varchar2</code>.',
'    &PRODUCT_NAME. sostituisce ogni istanza di <code>#NAME#</code> negli attributi dello schema ',
'    di autenticazione con il valore associato.',
'    Lo schema <em>Connessione Social</em> incorporato usa <code>CREDENTIAL_STATIC_ID</code>',
'    per utilizzare l''area di memorizzazione delle credenziali corrispondente invece di quella ',
'    configurata nello schema.',
'    </li><li><code>tenant_id</code>:',
'    consente di impostare l''ID tenant nella sessione (vedere <code>apex_session.set_tenant_id</code>).',
'    </li>',
'</ul>',
'</p><p>',
'Nelle applicazioni con procedura di configurazione dell''autenticazione,',
unistr('non \00E8 possibile modificare lo schema di autenticazione mediante l''URL (ad esempio, <code>f?p=100:1:1234:APEX_AUTHENTICATION=myauth</code>).'),
'</p><p>',
'La procedura di configurazione dell''autenticazione viene eseguita almeno una volta per sessione, alla prima richiesta.    ',
'Potrebbe tuttavia essere necessario che &PRODUCT_NAME. la richiami in altre occasioni.',
unistr('In casi del genere, dovr\00E0 impostare gli stessi valori in ogni chiamata.'),
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
