,p_item_plug_id=>wwv_flow_imp.id(6354406057147715.4004)
,p_use_cache_before_default=>'NO'
,p_item_default=>'END_OF_REQUEST'
,p_prompt=>'Commit stato sessione'
,p_source=>'SESSION_STATE_COMMITS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'SESSION_STATE_COMMITS'
,p_lov=>'.'||wwv_flow_imp.id(2404156723407174)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'&PRODUCT_NAME. gestisce lo stato della sessione[<a rel="noopener noreferrer" href="#fn1">1</a>] sia nelle variabili globali PL/SQL per l''accesso rapido sia nelle tabelle di database.',
'Utilizzare questo attributo per configurare quando viene scritto lo stato della sessione e ne viene eseguito il commit nel database:',
unistr('<ul><li><strong>Immediato</strong>: quando lo stato cambia durante l''elaborazione della richiesta, ad esempio perch\00E9 un processo PL/SQL ha modificato una bind variable,'),
'queste modifiche vengono scritte immediatamente e ne viene eseguito il commit. Notare che questa operazione esegue il commit della transazione principale, che potrebbe contenere modifiche alle tabelle dell''applicazione.',
'</li><li><strong>Fine richiesta</strong>: &PRODUCT_NAME. gestisce una lista delle modifiche dello stato della sessione che si sono verificate durante l''elaborazione della richiesta',
'e le applica alla fine della richiesta.',
unistr('Utilizzare questo valore per un controllo migliore delle transazioni e per garantire la continuit\00E0 dell''applicazione in caso di indisponibilit\00E0 non pianificate.'),
'</li></ul>',
'<br/>',
unistr('<div id="fn1">[1] In questo contesto, lo stato della sessione include valori di elementi e attributi della sessione stessa (ad esempio, il timeout di inattivit\00E0).'),
'Sebbene anche le raccolte facciano parte dello stato della sessione, non vengono influenzate dall''attributo <em>Commit stato sessione</em>.',
'</div>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
