,p_display_when2=>'PLSQL'
,p_display_when_type=>'EXPRESSION'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_help_text=>unistr('Specifica l''ambiente MLE in cui eseguire tutti gli snippet del codice MLE nell''applicazione. Se non viene fornito alcun valore, verr\00E0 utilizzato l''ambiente predefinito.')
