wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(107203001185706981.4004)
,p_name=>'P509_PAGE_PROTECTION_ENABLED'
,p_item_sequence=>200
,p_item_plug_id=>wwv_flow_imp.id(107273213161009008.4004)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>'Protezione stato sessione'
,p_source=>'PAGE_PROTECTION_ENABLED_Y_N'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'ENABLED_DISABLED_RETURNS_Y_OR_N'
,p_lov=>'.'||wwv_flow_imp.id(91439803955181562)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<div class="htmldbInfoBodyP">Se si seleziona <strong>Abilitato</strong>, questa funzionalit\00E0 utilizza gli attributi di pagina Protezione accesso pagina e gli attributi di elemento Protezione stato sessione insieme ai checksum che si trovano negli URL')
||' f?p=. L''abilitazione di questa funzione impedisce a utenti non autorizzati di modificare o di accedere agli URL o di modificare lo stato delle sessioni.</div>',
'',
unistr('<div class="htmldbInfoBodyP">Se si seleziona <strong>Disabilitato</strong>, il motore di &PRODUCT_NAME. non prender\00E0 in considerazione gli attributi di pagina Protezione accesso pagina n\00E9 gli attributi di elemento Protezione stato sessione durante l''')
||unistr('esecuzione dell''applicazione e non includer\00E0 i checksum nella sezione f?p= degli URL.</div>'),
'',
unistr('<div class="htmldbInfoBodyP">Se questo attributo \00E8 impostato su <strong>Abilitato</strong> e lo si cambia in <strong>Disabilitato</strong>, la protezione dello stato delle sessioni verr\00E0 disabilitata, ma non verr\00E0 apportata nessuna modifica all''impos')
||'tazione di tutti gli attributi di pagina Protezione accesso pagina e degli attributi di elemento Protezione stato sessione.</div>',
'',
unistr('<div class="htmldbInfoBodyP">Se l''attributo \00E8 impostato su <strong>Disabilitato</strong> e lo si cambia in <strong>Abilitato</strong>, la protezione dello stato delle sessioni verr\00E0 abilitata e non verr\00E0 apportata nessuna modifica agli attributi di p')
||unistr('agina Protezione accesso pagina e agli attributi di elemento Protezione stato sessione, che perci\00F2 continueranno a essere rispettati durante l''esecuzione dell''applicazione.</div>'),
'',
unistr('<div class="htmldbInfoBodyP">Un''eccezione alla regola generale relativa agli attributi di elemento Protezione stato sessione che diventano effettivi solo se la protezione dello stato delle sessioni \00E8 impostata su <strong>Abilitato</strong> si ha nel ')
||unistr('caso in cui l''attributo dell''elemento sia impostato su <strong>Protetto</strong>. In questo caso, questo stato \00E8 sempre effettivo, nel senso che gli elementi protetti non possono essere impostati dall''URL, indipendentemente dal fatto che la protezion')
||'e dello stato delle sessioni sia impostata su Abilitato o Disabilitato.</div>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
