,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p />',
unistr('Indica se la protezione per lo stato delle sessioni \00E8 abilitata o disabilitata. Se \00E8 abilitata, questa funzione utilizza gli attributi di pagina <i>Protezione accesso pagina</i> e gli attributi di elemento <i>Protezione stato sessione</i> insieme ai ')
||'checksum che si trovano negli URL "f?p=". Questa funzione impedisce a utenti non autorizzati di modificare o di accedere agli URL o di modificare lo stato delle sessioni. ',
'<p />',
unistr('Se questa funzione \00E8 disabilitata, gli attributi di pagina ed elemento relativi alla protezione per lo stato delle sessioni vengono ignorati e i checksum non vengono inseriti nei checksum all''interno degli URL "f?p=" generati.')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'based_on', 'LOV',
  'format', 'PLAIN',
  'send_on_page_submit', 'N',
  'show_line_breaks', 'N')).to_clob
);
