,p_name=>'Crea modello di elemento'
,p_template=>wwv_flow_imp.id(42025417508627628.4004)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:a-Report--stretch'
,p_new_grid_row=>false
,p_display_column=>1
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :P655_COPY_FROM_FLOW_ID, :P353_COPY_FROM_THEME ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :P655_COPY_FROM_FLOW_ID, :P353_COPY_FROM_THEME )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :P655_COPY_FROM_FLOW_ID, :P353_COPY_FROM_THEME )   as workspace_id',
'      from sys.dual',
')',
'',
'select ft.id,',
'       case',
'           when ft.security_group_id in ( 11, 12 ) then m.theme_repository',
'           else to_char( ft.flow_id )',
'       end flow_id,',
'       ft.template_name from_name,',
'       wwv_flow_lang.system_message(''F4000.P158.COPY_OF'',ft.template_name) to_name,',
'       ''N'' Sub',
'  from wwv_flow_field_templates ft,',
'       ( select wwv_flow_lang_dev.builder_message( ''SUBSCRIBED_FROM.THEME_REPOSITORY'' ) theme_repository',
'           from sys.dual ) m,',
'       central_theme ct',
'   where ( ft.flow_id, ft.theme_id, ft.security_group_id ) in',
'         (',
'          ( :P655_COPY_FROM_FLOW_ID, :P353_COPY_FROM_THEME, :WORKSPACE_ID ),',
'          ( ct.application_id, ct.theme_id, ct.workspace_id )',
'         )'))
,p_fixed_header=>'NONE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(123728124628276646.4004)
,p_query_num_rows=>500
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_show_nulls_as=>'(null)'
,p_query_no_data_found=>'<font class="fielddata">Nessun modello di elemento trovato.</font>'
