begin
wwv_flow_imp_page.create_page(
 p_id=>661.4004
,p_name=>'Modifica modello di calendario'
,p_alias=>'EDIT-CALENDAR-TEMPLATE2'
,p_step_title=>'Modifica modello di calendario'
,p_reload_on_submit=>'A'
,p_warn_on_unsaved_changes=>'N'
,p_first_item=>'AUTO_FIRST_ITEM'
,p_autocomplete_on_off=>'ON'
,p_group_id=>wwv_flow_imp.id(212879727923324936)
,p_javascript_code=>'htmldb_ch_message=''"OK_TO_GET_NEXT_PREV_PK_VALUE"'';'
,p_step_template=>wwv_flow_imp.id(689605897838965863.4004)
,p_page_template_options=>'#DEFAULT#'
,p_read_only_when_type=>'EXISTS'
,p_read_only_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1',
'  from wwv_flow_cal_templates t, ',
'       wwv_flow_themes th',
' where t.id                 = :F4000_P697_ID',
'   and t.flow_id            = th.flow_id',
'   and t.theme_id           = th.theme_id',
'   and t.security_group_id  = :WORKSPACE_ID',
'   and th.security_group_id = t.security_group_id',
'   and t.reference_id       is not null',
