,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Add components to collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'wwv_flow_export_dev.add_to_component_export (',
'    p_application_id => nvl(:FB_FLOW_ID, :P688_APPLICATION),',
'    p_selected       => wwv_flow.g_f01 );'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Impossibile aggiungere i componenti da esportare'
,p_process_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
':REQUEST = ''ADD_TO_EXPORT''',
'and :P688_MODE in (''AC'',''PD'',''BO'')',
'and wwv_flow.g_f01.count > 0'))
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>206919602341115305.4004
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8612229637147008.4004)
,p_process_sequence=>60
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Export Components'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_components wwv_flow_export_dev.t_components;',
'begin',
'    -- Load selected components into array so we don''t have to query the collection for each language.',
'    select type_name as component,',
'           id        as component_id',
'           bulk collect into l_components',
'      from wwv_multi_component_export',
'     where flow_id   = :P688_APPLICATION',
'     order by type_name, seq_id;',
'     ',
'     wwv_flow_export_dev.export_components (',
'         p_application_id         => :P688_APPLICATION,',
'         p_components             => l_components,',
'         p_format                 => case ',
'                                     when :P688_EXPORT_ZIP = ''Y'' then ''ZIP_UNIX'' ',
'                                     else ''UNIX'' ',
'                                     end,',
'         p_export_translations_yn => :P688_EXPORT_TRANSLATIONS,',
'         p_flashback_min_ago      => :P688_FLASHBACK_MIN_AGO, ',
'                                     -- always include install when NOT a zip',
'         p_with_install           => :P688_EXPORT_ZIP != ''Y'' or ',
'                                     -- export install if requested when zip',
'                                     :P688_WITH_INSTALL = ''Y'', ',
'        p_with_audit_info         => :P688_AUDIT_INFO);',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Errore durante l''esportazione dei componenti.'
,p_process_when_button_id=>wwv_flow_imp.id(8006211505904123.4004)
,p_process_success_message=>'Componente o componenti condivisi esportati.'
,p_internal_uid=>8612229637147008.4004
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(207473519018342362.4004)
,p_process_sequence=>40
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Delete single member'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    wwv_flow_collection.delete_member(',
'        p_collection_name => ''MULTI_COMPONENT_EXPORT'',',
'        p_seq             => :P688_DEL );',
'    commit;',
'',
'exception',
'    when others then null;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Impossibile rimuovere il componente'
,p_process_when=>'DELETE'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>207473519018342362.4004
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(207471519926333100.4004)
,p_process_sequence=>50
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    c pls_integer;',
'begin',
'    select count(*) into c',
'      from wwv_flow_collections',
'     where collection_name = ''MULTI_COMPONENT_EXPORT''',
'       and n001 = :P688_APPLICATION',
'       and rownum = 1;',
'',
'    if :REQUEST = ''NEW'' or c = 0 then',
'        if :REQUEST = ''NEW'' then',
'            wwv_flow.g_print_success_message :=',
'                wwv_flow_lang.system_message(''WWV_FLOW_WIZARD_API.ACTION_PROCESSED'');',
'        end if;',
'',
'        wwv_flow_collection.create_or_truncate_collection(',
'            p_collection_name => ''MULTI_COMPONENT_EXPORT''',
'        );',
'        commit;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>207471519926333100.4004
);
end;
