,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   l_comma      number;',
'   l_item_id    number;',
'   l_column_id  number;',
'begin',
'   for i in 1..wwv_flow.g_f01.count loop',
'',
'      l_comma     := instr(wwv_flow.g_f01(i),'','');',
'      l_item_id   := substr(wwv_flow.g_f01(i),1,l_comma-1);',
'      l_column_id := substr(wwv_flow.g_f01(i),l_comma+1);',
'',
'      wwv_flow_hint.update_ad_from_items(',
'         p_application_id  => :FB_FLOW_ID,',
'         p_page_id         => :P890_PAGE_ID,',
'         p_item_id         => l_item_id,',
'         p_column_id       => l_column_id,',
'         p_attr_to_include => :P890_INCLUDE_IN_UPDATE );',
'',
'   end loop;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Aggiornamento del dizionario attributi non riuscito.'
,p_process_when_button_id=>wwv_flow_imp.id(258528808540645263.4004)
,p_process_success_message=>'Dizionario attributi aggiornato.'
,p_internal_uid=>258533930282746140.4004
);
end;
