'            p_rc_id           => l_rc_id,',
'            p_attr_to_include => :P907_INCLUDE_IN_UPDATE );',
'      end if;',
'',
'   end loop;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Aggiornamento del dizionario attributi non riuscito.'
,p_process_when_button_id=>wwv_flow_imp.id(253950306918283249.4004)
,p_process_success_message=>'Dizionario attributi aggiornato.'
,p_internal_uid=>260805523043847181.4004
);
