'           wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P955_THEME )   as workspace_id',
'      from sys.dual',
')',
'',
'select 1',
'  from wwv_flow_row_templates rt,',
'       central_theme ct',
' where ( rt.flow_id, rt.theme_id, rt.security_group_id ) in',
'       (',
'        ( :FB_FLOW_ID, :P955_THEME, :WORKSPACE_ID ),',
'        ( ct.application_id, ct.theme_id, ct.workspace_id )',
'       )',
'   and rt.row_template_name = :P955_NAME'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>'Il valore #LABEL# deve essere univoco.'
