wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(80051121794611628.4004)
,p_name=>'P1405_PAGE_TEMPLATE'
,p_data_type=>'CLOB'
,p_source_data_type=>'CLOB'
,p_is_required=>true
,p_item_sequence=>70
,p_item_plug_id=>wwv_flow_imp.id(73493529825371212.4004)
,p_item_source_plug_id=>wwv_flow_imp.id(24429902451664898.4004)
,p_prompt=>'Modello di pagina:'
,p_source=>'PAGE_TEMPLATE'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_TEXTAREA'
,p_cSize=>96
,p_cMaxlength=>32767
,p_cHeight=>12
,p_display_when=>'P1405_REPORT_LAYOUT_TYPE'
,p_display_when2=>'XSL_GENERIC'
,p_display_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_field_template=>wwv_flow_imp.id(561549716994252345.4004)
,p_item_template_options=>'#DEFAULT#:a-Form-fieldContainer--stretch'
,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<div class="htmldbInfoBodyP">Il layout di report \00E8 la definizione basata su XSL-FO della formattazione della pagina. In questa sezione vengono configurati tutti gli attributi che definiscono le dimensioni della pagina, l''orientamento, i caratteri, gl')
||unistr('i stili e cos\00EC via. </div>'),
'',
'<div class="htmldbInfoBodyP">Le stringhe di sostituzione valide sono le seguenti: </div>',
'<ul class="noIndent">',
'<li>#PAGE_HEADER#</li>',
'<li>#PAGE_HEADERFONT_COLOR#</li>',
'<li>#PAGE_HEADER_FONT_FAMILY#</li>',
'<li>#PAGE_HEADER_FONT_SIZE#</li>',
'<li>#PAGE_HEADER_FONT_WEIGHT#</li>',
'<li>#PAGE_FOOTER#</li>',
'<li>#PAGE_FOOTER_FONT_COLOR#</li>',
'<li>#PAGE_FOOTER_FONT_FAMILY#</li>',
'<li>#PAGE_FOOTER_FONT_SIZE#</li>',
'<li>#PAGE_FOOTER_FONT_WEIGHT#</li>',
'<li>#PAGE_WIDTH#</li>',
'<li>#PAGE_HEIGHT#</li>',
'<li>#HEADER_BG_COLOR#</li>',
'<li>#HEADER_FONT_COLOR#</li>',
'<li>#HEADER_FONT_FAMILY#</li>',
'<li>#HEADER_FONT_SIZE#</li>',
'<li>#HEADER_FONT_WEIGHT#</li>',
'<li>#BODY_BG_COLOR#</li>',
'<li>#BODY_FONT_COLOR#</li>',
'<li>#BODY_FONT_FAMILY#</li>',
'<li>#BODY_FONT_SIZE#</li>',
'<li>#BODY_FONT_WEIGHT#</li>',
'<li>#BORDER_WIDTH#</li>',
'</ul>',
'<div class="htmldbInfoBodyP">Per rendere generico il layout di report, sono definiti modelli secondari aggiuntivi che specificano il layout per ogni singola colonna, intestazione di colonna e larghezza della colonna. In runtime, tali modelli secondar'
||'i vengono assemblati in modo dinamico e automaticamente inclusi nel layout di report principale mediante la sostituzione delle seguenti stringhe: </div>',
'<ul class="noIndent">',
'<li>#PRN_TABLE_CELLS#</li>',
'<li>#PRN_TEMPLATE_BODY_ROW#</li>',
