);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(153971260438479912.4004)
,p_plug_name=>'Informazioni'
,p_region_template_options=>'#DEFAULT#:a-Region--sideRegion:a-Region--paddedBody'
,p_component_template_options=>'#DEFAULT#'
,p_region_attributes=>'style="border-bottom-width: 0;"'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4004)
,p_plug_display_sequence=>40
,p_plug_new_grid_row=>false
,p_plug_display_column=>1
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Creare un servizio <strong>SQL abilitato per REST</strong> per eseguire il codice SQL o PL/SQL definito nei componenti di &PRODUCT_NAME. in un database Oracle remoto. </p>',
'',
'<p><strong>Requisiti:</strong> nel database remoto deve essere disponibile Oracle REST Data Services (ORDS) release 20.3 o successiva come elemento front-end e la funzione <em>SQL abilitato per REST</em> deve essere abilitata. Tutto il codice SQL e P'
||'L/SQL viene inviato all''istanza ORDS, che lo esegue nel database remoto. </p>',
'',
'<p>I riferimenti al codice SQL abilitato per REST vengono memorizzati a livello di area di lavoro, pertanto sono visibili in tutte le applicazioni.</p>',
'',
'<p>Quando si esporta un''applicazione, i riferimenti al codice SQL abilitato per REST utilizzati vengono aggiunti al file di esportazione. Se si esporta un''applicazione e la si importa in un''altra area di lavoro, &PRODUCT_NAME. controlla se l''area di '
||unistr('lavoro di destinazione contiene gi\00E0 riferimenti al codice SQL abilitato per REST con lo stesso <strong>ID statico</strong>. Se un riferimento al codice SQL abilitato per REST esiste gi\00E0, l''applicazione utilizzer\00E0 il riferimento esistente. Se invece n')
||unistr('on esiste, il riferimento verr\00E0 creato nell''area di lavoro di destinazione.</p>')))
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>'nvl(#OWNER#.wwv_flow_preferences.get_preference(''FP_PREF_SHOW_INFORMATION''),''YES'') = ''YES'''
,p_plug_display_when_cond2=>'PLSQL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
