,p_item_plug_id=>wwv_flow_imp.id(2002487147223122.4004)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Procedura di configurazione'
,p_source=>'CONFIGURATION_PROCEDURE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>59
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Immettere il nome di una procedura che configura l''URL dell''endpoint in runtime.',
unistr('Pu\00F2 trattarsi di una stored procedure o di una procedura definita nella voce <em>Codice PL/SQL</em>.'),
unistr('Il codice riportato di seguito \00E8 destinato a un''applicazione che implementa un''architettura multi-tenancy e supporta diverse variazioni'),
'dell''<em>URL endpoint</em> per i tenant.',
'Modifica il nome dominio nell''URL, a seconda del cliente (URL di esempio: ',
'https://cust-01.example.com, https://cust-02.example.com):',
'</p><pre><code>',
'procedure my_server_config(',
'    p_info   in  apex_plugin.t_remote_server_info,',
'    p_config out apex_plugin.t_remote_server_config )',
'is',
'begin',
'    if p_info.application_id = 100',
'    then',
'      p_config.base_url := ''https://#cust#.example.com'';',
'      p_config.substitutions := apex_t_varchar2();',
'      apex_string.plist_put( p_config.substitutions, ''cust'', v(''P3_CUSTOMER'') );',
'    else',
'      p_config.base_url := ''https://test.example.com'';',
'    end if;',
'end;',
'</code></pre><p>',
unistr('La procedura pu\00F2 modificare 2 attributi del parametro in/out <code>p_config</code>,'),
'entrambi facoltativi:',
'<ul>',
'    <li><code>base_url</code>:',
'    Modifica l''<em>URL endpoint</em>.',
'    </li>',
'    <li><code>substitutions</code>:',
'    Assegna coppie nome/valore usando <code>apex_t_varchar2</code>.',
'    &PRODUCT_NAME. sostituisce ogni <code>#NAME#</code> nell''<em>URL base</em> o nell''<em>URL endpoint</em>.',
'    </li>',
'</ul>',
'</p>',
''))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
