wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(582915942830077311.4004)
,p_plug_name=>'Utilizzo riferimenti SQL abilitato per REST'
,p_region_template_options=>'#DEFAULT#:a-Region--noTopBorder:a-Region--noPadding:a-Region--noBorder'
,p_component_template_options=>'#DEFAULT#'
,p_region_attributes=>'style="padding-bottom: 20px"'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4004)
,p_plug_display_sequence=>20
,p_plug_display_column=>1
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select s.id,',
'       p.flow_id                                            the_application,',
'       wwv_flow_page_api.get_url (',
'           p_page        => 4500,',
'           p_items       => ''FB_FLOW_PAGE_ID,FB_FLOW_ID'',',
'           p_values      => r.page_id||'',''||p.flow_id ) the_page,',
'       ''#''                                                  the_shared_component,',
'       r.page_id                                            page_id,',
'       p.name                                               page_name,',
'       r.plug_source_type                                   plug_source_type,',
'       r.plug_name                                          plug_name,',
'       null                                                 shared_comp_name,',
'       s.name                                               remote_server_name',
'  from wwv_flow_page_plugs r,',
'       wwv_flow_steps p,',
'       wwv_remote_servers s',
' where s.id                = r.remote_server_id',
'   and r.page_id           = p.id',
'   and r.flow_id           = p.flow_id',
'   and s.server_type       = ''REMOTE_SQL''',
'   and s.security_group_id = p.security_group_id',
'   and p.security_group_id = :flow_security_group_id',
'   and not exists ( select 1 from wwv_flow_language_map where translation_flow_id = p.flow_id )',
'union all (',
'select rs.id,',
'       p.flow_id                                            the_application,',
'       wwv_flow_page_api.get_url (',
'           p_page        => 4500,',
'           p_items       => ''FB_FLOW_PAGE_ID,FB_FLOW_ID'',',
'           p_values      => r.page_id||'',''||p.flow_id ) the_page,',
'       ''#''                                                  the_shared_component,',
'       r.page_id                                            page_id,',
'       p.name                                               page_name,',
'       r.plug_source_type                                   plug_source_type,',
'       r.plug_name || '' - '' || s.name                       plug_name,',
'       null                                                 shared_comp_name,',
'       rs.name                                              remote_server_name',
'  from wwv_flow_jet_chart_series s,',
'       wwv_flow_jet_charts c,',
'       wwv_flow_page_plugs r,',
'       wwv_flow_steps p,',
'       wwv_remote_servers rs',
' where rs.id               = s.remote_server_id',
'   and rs.server_type      = ''REMOTE_SQL''',
'   and p.flow_id           = r.flow_id',
'   and s.chart_id          = c.id',
'   and c.region_id         = r.id',
'   and r.page_id           = p.id',
'   and r.flow_id           = p.flow_id',
'   and p.security_group_id = :flow_security_group_id',
'   and not exists (select 1 from wwv_flow_language_map where translation_flow_id = p.flow_id ) )',
'union all (',
'select s.id,',
'       l.flow_id                                            the_application,',
'       ''#''                                                  the_page,',
'       wwv_flow_page_api.get_url (',
'           p_page        => 4111,',
'           p_clear_cache => 4111,',
'           p_items       => ''F4000_P4111_ID,FB_FLOW_ID'',',
'           p_values      => l.id||'',''||l.flow_id ) the_shared_component,',
'       null                                                 page_id,',
'       null                                                 page_name,',
'       wwv_flow_lang.system_message( ''SHARED DYNAMIC LOV'' ) plug_source_type,',
'       null                                                 plug_name,',
'       l.lov_name                                           shared_comp_name,',
'       s.name                                               remote_server_name',
'  from wwv_flow_lists_of_values$ l,',
'       wwv_remote_servers s',
' where s.id = l.remote_server_id',
'   and s.server_type       = ''REMOTE_SQL''',
'   and s.security_group_id = l.security_group_id',
'   and l.security_group_id = :flow_security_group_id',
'   and not exists (select 1 from wwv_flow_language_map where translation_flow_id = l.flow_id ) )',
'union all (',
'select s.id,',
'       a.flow_id                                            the_application,',
'       ''#''                                                  the_page,',
'       wwv_flow_page_api.get_url (',
'           p_page        => 7021,',
'           p_clear_cache => 7021,',
'           p_items       => ''FB_FLOW_ID,P7021_ID'',',
'           p_values      => a.flow_id||'',''||a.id ) the_shared_component,',
'       null                                                 page_id,',
'       null                                                 page_name,',
'       wwv_flow_lang.system_message( ''AUTOMATIONS'' )        plug_source_type,',
'       null                                                 plug_name,',
'       a.name                                               shared_comp_name,',
'       s.name                                               remote_server_name',
'  from wwv_flow_automations a,',
'       wwv_remote_servers s',
' where s.id = a.remote_server_id',
'   and s.server_type       = ''REMOTE_SQL''',
'   and s.security_group_id = a.security_group_id',
'   and a.security_group_id = :flow_security_group_id',
'   and not exists (select 1 from wwv_flow_language_map where translation_flow_id = a.flow_id ) )',
'union all (',
'select s.id,',
'       a.flow_id                                            the_application,',
'       ''#''                                                  the_page,',
'       wwv_flow_page_api.get_url (',
'           p_page        => 7022,',
'           p_clear_cache => 7022,',
'           p_items       => ''FB_FLOW_ID,P7022_ID'',',
'           p_values      => a.flow_id||'',''||a.id ) the_shared_component,',
'       null                                                 page_id,',
'       null                                                 page_name,',
'       wwv_flow_lang.system_message( ''AUTOMATION_ACTIONS'' ) plug_source_type,',
'       null                                                 plug_name,',
'       a.name                                               shared_comp_name,',
'       s.name                                               remote_server_name',
'  from wwv_flow_automation_actions a,',
'       wwv_remote_servers s',
' where s.id = a.remote_server_id',
'   and s.server_type       = ''REMOTE_SQL''',
