 p_id=>wwv_flow_imp.id(2545228608236501.4004)
,p_name=>'P1621_USE_DB_CREDENTIAL'
,p_item_sequence=>70
,p_item_plug_id=>wwv_flow_imp.id(308592151420746764.4004)
,p_prompt=>'Usa credenziale database'
,p_display_as=>'NATIVE_YES_NO'
,p_display_when=>'wwv_flow_db_version.c_has_utl_http_credential'
,p_display_when2=>'PLSQL'
,p_display_when_type=>'EXPRESSION'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Abilitare questa opzione per utilizzare i segreti memorizzati in una credenziale del database.',
unistr('    \00C8 possibile ottenere le credenziali disponibili dalla vista del dizionario <strong>ALL_CREDENTIALS</strong>.'),
'    Utilizzare il package <strong>DBMS_CREDENTIAL</strong> ',
'    per gestire le credenziali del database.</p>',
'<p>',
unistr('    <em>L''utilizzo di una credenziale del database modifica il funzionamento delle richieste HTTP eseguite e la modalit\00E0 di funzionamento delle credenziali Web:</em></p>'),
'<ul>',
'    <li>',
'        Se viene utilizzata una credenziale del database, tutte le richieste HTTP verranno eseguite nel ',
'        contesto dello schema di analisi dell''applicazione e non nel contesto del',
unistr('        motore APEX. Ci\00F2 significa che \00E8 necessario concedere le <em>ACL di rete PL/SQL</em>'),
'        allo schema di analisi dell''applicazione. Consultare la documentazione relativa a',
'        <strong>DBMS_NETWORK_ACL_ADMIN</strong> per ulteriori dettagli.</li>',
'    <li>',
'        Una credenziale del database viene gestita completamente dal database e &PRODUCT_NAME.',
unistr('        non dispone dell''accesso ai segreti memorizzati. Pertanto, poich\00E9 &PRODUCT_NAME. non pu\00F2 applicare'),
unistr('        l''attributo <strong>Valido per gli URL</strong>, questo attributo \00E8 disabilitato quando viene utilizzata'),
'        una credenziale del database.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
