wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3367384134004646.4004)
,p_name=>'P1621_VALID_FOR_URLS'
,p_item_sequence=>230
,p_item_plug_id=>wwv_flow_imp.id(308592151420746764.4004)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Valido per gli URL'
,p_source=>'VALID_FOR_URLS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXTAREA'
,p_cSize=>64
,p_cHeight=>5
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>&PRODUCT_NAME. controller\00E0 se l''URL per il quale viene utilizzata la credenziale in runtime corrisponde a uno degli URL inclusi nella lista. Se l''URL non corrisponde, &PRODUCT_NAME. restituir\00E0 un errore.</p>'),
'<p>Immettere ogni URL su una nuova riga. L''endpoint URL da utilizzare deve iniziare con uno degli URL forniti qui.</p>',
'<p>Esempio:</p>',
'<pre>',
'https://www.example.com/restapis/my-protected-api',
'https://www.example.com/allowed-urls',
'</pre>',
unistr('<p>Se la credenziale viene usata per richiamare un servizio REST all''indirizzo <strong>https://www.example.com/restapis/my-protected-api/restendpoint</strong> o <strong>https://www.example.com/allowed-urls/page1</strong>, \00E8 possibile usare la credenz')
||unistr('iale e l''esecuzione della chiamata riuscir\00E0.</p>'),
unistr('<p>Se la credenziale viene usata per richiamare un servizio REST all''indirizzo <strong>https://localhost/myapis/test</strong> o <strong>https://dev.example.com/myapis/test</strong>, la credenziale <em>non potr\00E0</em> essere utilizzata e &PRODUCT_NAME.')
||unistr(' restituir\00E0 un errore.</p>'),
'<p>Esempio:</p>',
'<pre>',
'ldap://ldap.mycompany.com',
'ldaps://ldap.mycompany.com:389',
'</pre>',
'<p>ldap:// e ldaps:// sono i "protocolli" utilizzati per specificare gli URL consentiti per un server LDAP.</p>',
unistr('<p>Tenere presente che per modificare questo valore \00E8 necessario immettere nuovamente il segreto client.</p>')))
,p_inline_help_text=>'Tenere presente che la modifica di questo valore richiede di immettere nuovamente il segreto client.'
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'auto_height', 'N',
  'character_counter', 'N',
  'resizable', 'Y',
  'trim_spaces', 'BOTH')).to_clob
);
