wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(154593935882686557.4004)
,p_name=>'P1621_CREDENTIALS_TYPE'
,p_item_sequence=>60
,p_item_plug_id=>wwv_flow_imp.id(308592151420746764.4004)
,p_use_cache_before_default=>'NO'
,p_item_default=>'BASIC'
,p_prompt=>'Tipo di autenticazione'
,p_source=>'AUTHENTICATION_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'CREDENTIALS_TYPE'
,p_lov=>'.'||wwv_flow_imp.id(154078822199034715)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Specificare qui il tipo di autenticazione. &PRODUCT_NAME. supporta i tipi di autenticazione riportati di seguito.</p>',
'<ul>',
'    <li><strong>Autenticazione di base</strong>: invia il nome utente e la password in formato codificato Base64 come intestazione della richiesta di <strong>autorizzazione</strong>.',
'    </li>',
'    <li><strong>Credenziali client OAuth2</strong>: &PRODUCT_NAME. scambia l''ID client e il segreto client per un <strong>token di accesso</strong> utilizzando un URL server del token. Il token di accesso viene poi usato per eseguire la richiesta eff'
||unistr('ettiva. Se il token di accesso \00E8 scaduto, &PRODUCT_NAME. ne richieder\00E0 uno nuovo in modo trasparente.</li>'),
'    <li><strong>Autenticazione nativa OCI</strong>: &PRODUCT_NAME. firma le richieste nell''API REST dell''<em>infrastruttura Oracle Cloud (OCI)</em>, come descritto nella <a rel="noopener noreferrer" href="https://docs.cloud.oracle.com/en-us/iaas/Cont'
||unistr('ent/API/Concepts/signingrequests.htm">documentazione OCI</a>. Questo tipo \00E8 disponibile solo in Oracle Database 18c e versioni successive.</li>'),
'    <li><strong>Intestazione HTTP</strong>: la credenziale viene aggiunta alla richiesta REST sotto forma di intestazione HTTP. Il nome della credenziale viene utilizzato come nome dell''intestazione HTTP, il segreto della credenziale viene usato come'
||' valore dell''intestazione HTTP. &PRODUCT_NAME. non aggiunge questi segreti al log di debug o a qualsiasi altro log.</li>',
unistr('    <li><strong>Stringa di query dell''URL</strong>: la credenziale viene aggiunta all''URL della richiesta REST sotto forma di parametro <em>stringa di query</em> (ad esempio: <strong>?name=value</strong>). Questa opzione pu\00F2 essere utile con le chiav')
||'i API. &PRODUCT_NAME. non aggiunge tali segreti al log di debug o a qualsiasi altro log. Tuttavia, i server proxy o altri di tipo intermedio possono registrare queste credenziali nei rispettivi file di log.</li>',
unistr('    <li><strong>Coppia di chiavi</strong>: una credenziale coppia di chiavi \00E8 composta da una chiave pubblica, condivisa apertamente per cifrare i dati e da una chiave privata, tenuta accuratamente segreta per decifrare i dati. Le due chiavi insieme ')
||'garantiscono uno scambio sicuro dei dati.</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
