,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Adjust DB Credential Items on Save'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
':P1621_DB_CRED_IS_INSTANCE :=',
'     case',
'          when :P1621_USE_DB_CREDENTIAL = ''Y''',
'          then case ',
'                    when wwv_flow_platform.get_preference( ''INSTANCE_DBMS_CREDENTIAL_ENABLED'' ) = ''Y''',
'                    then case when :P1621_DB_CREDENTIAL_TYPE = ''INSTANCE'' then ''Y'' else ''N'' end',
'                    else ''N''',
'               end',
'     end;',
'',
'',
':P1621_DB_CREDENTIAL_NAME := ',
'     case',
'          when :P1621_USE_DB_CREDENTIAL = ''Y''',
'          then case when :P1621_DB_CREDENTIAL_TYPE = ''INSTANCE'' ',
'                    then :P1621_INSTANCE_DB_CRED_NAME',
'                    else :P1621_SCHEMA_DB_CRED_NAME',
'               end',
'     end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'wwv_flow_db_version.c_has_utl_http_credential'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>1758194942531729.4004
);
