,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Una <strong>definizione di caricamento dati</strong> consente agli sviluppatori di aggiungere la funzionalit\00E0 <em>Caricamento dati</em> '),
'    a un''applicazione Oracle APEX.',
'</p>',
'<p>',
unistr('    Una definizione di caricamento dati \00E8 costituita dalle informazioni su dove memorizzare i dati '),
unistr('    caricati nonch\00E9 dai dettagli sul metodo di caricamento, ad esempio se '),
'    <em>aggiungere</em> dati o <em>sostituire</em> quelli esistenti. ',
unistr('    \00C8 possibile farvi riferimento nei processi della pagina <strong>Caricamento dati</strong> e '),
'    utilizzando il package PL/SQL <code>APEX_DATA_LOADING</code>.',
'</p>',
'<p>',
'    Il <strong>profilo dati</strong> contiene informazioni sulla ',
'    struttura dei dati caricati e sulle colonne aggiuntive',
'     in base all''espressione SQL, alla query SQL, alle ricerche o alle regole di trasformazione.',
'</p>',
'<p>',
'    Una volta creata la definizione di caricamento dati, la procedura guidata consente di aggiungere una ',
unistr('    pagina Caricamento dati all''applicazione. \00C8 possibile personalizzare la pagina creata '),
'    in un secondo momento per soddisfare i requisiti dell''applicazione.',
'</p>'))
,p_plug_query_headings_type=>'QUERY_COLUMNS'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
