'declare',
'    l_base_url varchar2(32000);',
'begin',
'    l_base_url := substr(:P1850_BUCKET_URL,1,instr(:P1850_BUCKET_URL,''/b/'')+2);',
'    --if the URL provided doesn''t inlcude /b/, but could be valid',
'    if instr(l_base_url,''https'') != 1 then',
'       l_base_url := :P1850_BUCKET_URL;',
'    end if;',
'',
'    return l_base_url;',
'end;'))
);
