'      from wwv_flow_collections',
'     where collection_name = ''F4000_OB_FILES''',
'       and n001 = :FB_FLOW_ID;',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>2411614510988432.4004
);
