,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'return wwv_flow_web_src_dev.validate_web_src_operations(',
'           p_security_group_id      => :FLOW_SECURITY_GROUP_ID,',
'           p_flow_id                => :FB_FLOW_ID,',
