,p_lov=>'.'||wwv_flow_imp.id(2225637019805602)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Scegliere il tipo dati del valore del parametro. Quando un valore non VARCHAR2 ',
unistr('   viene inviato all''API REST, verr\00E0 convertito in una stringa utilizzando il '),
'    <strong>formato di visualizzazione dell''output</strong>.',
'</p>',
'<p>Le opzioni includono:</p>',
'<dl>',
'    <dt>Stringa</dt>',
'    <dd>I valori Stringa contengono dati alfanumerici.</dt>',
'    <dt>Numerico</dt>',
'    <dd>I valori Numerico sono valori decimali o interi.</dd>',
'    <dt>Data</dt>',
unistr('    <dd>I valori Data contengono data e ora, ma non frazioni di secondo n\00E9 informazioni sul fuso orario.</dd>'),
'    <dt>Indicatore orario</dt>',
'    <dd>I valori Indicatore orario contengono data e ora (incluse le frazioni di secondo), ma non le informazioni sul fuso orario.</dd>',
'    <dt>Indicatore orario con fuso orario</dt>',
'    <dd>I valori Indicatore orario con fuso orario contengono data e ora (incluse le frazioni di secondo) e anche le informazioni sul fuso orario.</dd>',
'    <dt>Booleano</dt>',
'    <dd>I valori Booleano contengono <strong>true</strong> o <strong>false</strong>.</dd>',
'    <dt>Binario</dt>',
'    <dd>Il contenuto di tipo Binario contiene dati non di testo (immagini, byte raw) e viene rappresentato come oggetto Stringa in formato <em>Base64</em>.</dd>',
'</dl>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
