wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(226076489414270121.4004)
,p_name=>'P1923_PARAM_TYPE'
,p_is_required=>true
,p_item_sequence=>60
,p_item_plug_id=>wwv_flow_imp.id(2228992349790506.4004)
,p_use_cache_before_default=>'NO'
,p_item_default=>'URL_PATTERN'
,p_prompt=>'Tipo'
,p_source=>'PARAM_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'WEB_SOURCE_PARAM_TYPES'
,p_lov=>'.'||wwv_flow_imp.id(226045111811519566)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4004)
,p_item_css_classes=>'apex-button-group'
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Scegliere il tipo di questo parametro di origine REST. Sono disponibili i valori riportati di seguito.',
'</p>',
'<dl>',
'<dt>Pattern URL (IN)</dt>',
'<dd>Sostituisce i segnaposto nell''URL dell''endpoint con i valori dei parametri.</dd>',
'<dt>Stringa di query URL (IN)</dt>',
'<dd>Aggiunge il nome e il valore del parametro all''URL come stringa di query.</dd>',
'<dt>Intestazione HTTP (IN, OUT)</dt>',
'<dd>Invia il parametro come intestazione di richiesta HTTP oppure lo riceve dalle intestazioni di risposta.</dd>',
'<dt>Cookie (IN, OUT)</dt>',
'<dd>Invia il parametro sotto forma di cookie oppure lo riceve dai cookie di risposta.</dd>',
'<dt>Colonna profilo dati (OUT)</dt>',
unistr('<dd>Esamina la risposta utilizzando il profilo dati e usa il valore della colonna. Questo tipo \00E8 supportato solo nel tipo di processo <strong>Richiama API</strong>.</dd>'),
'<dt>Corpo richiesta o risposta (IN, OUT)</dt>',
unistr('<dd>Esegue le sostituzioni dei segnaposto nel corpo della richiesta utilizzando il valore del parametro. Per i parametri OUT verr\00E0 recuperata la <em>risposta completa</em>.</dd>'),
'<dt>Codice di stato (OUT)</dt>',
'<dd>Riceve il codice di stato HTTP.</dd>',
'<dt>Frase causa (OUT)</dt>',
'<dd>Riceve la frase causa HTTP.</dd>',
'</dl>',
'<p>',
'    Esempio relativo ai parametri di tipo <strong>Pattern URL</strong>',
'</p>',
'<ul>',
'    <li>Endpoint URL: <code>http://{server}:{port}/ords/:schema/emp/:deptno</code></li>',
'    <li>Parametro 1: <em>variabile pattern URL</em> "deptno" con il valore "10"</li>',
'    <li>Parametro 2: <em>variabile pattern URL</em> "schema" con il valore "scott"</li>',
'</ul>',
'<p>',
'<br>',
unistr('    <em>Non</em> aggiungere i due punti (:) al nome del parametro. &PRODUCT_NAME. creer\00E0 l''URL da richiamare seguente:<br>'),
'    <code>http://{server}:{port}/ords/<strong>scott</strong>/emp/<strong>10</strong></code>',
'</p>',
'<p>',
'    Esempio relativo ai parametri di tipo <strong>Stringa di query</strong>',
'</p>',
'<ul>',
'    <li>Endpoint URL: <code>http://{server}:{port}/ords/scott/emp</code></li>',
'    <li>Parametro 1: <em>variabile stringa di query</em> "query_filter" con il valore "KING"</li>',
'</ul>',
'<p>',
'<br>',
unistr('    &PRODUCT_NAME. creer\00E0 l''URL da richiamare seguente:<br>'),
'    <code>http://{server}:{port}/ords/scott/emp?<strong>query_filter</strong>=<strong>KING</strong></code>',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
,p_show_quick_picks=>'Y'
,p_quick_pick_label_01=>'Pattern di URL'
,p_quick_pick_value_01=>'URL_PATTERN'
,p_quick_pick_label_02=>'Stringa di query URL'
,p_quick_pick_value_02=>'QUERY_STRING'
,p_quick_pick_label_03=>'Intestazione HTTP'
,p_quick_pick_value_03=>'HEADER'
,p_quick_pick_label_04=>'Profilo dati'
,p_quick_pick_value_04=>'DATA_PROFILE'
,p_quick_pick_label_05=>'Corpo'
,p_quick_pick_value_05=>'BODY'
);
