,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Se l''impostazione \00E8 <strong>Attivo</strong>, &PRODUCT_NAME. aggiunger\00E0 solo il parametro alla richiesta, quando il valore non \00E8 vuoto. Se l''impostazione \00E8 <strong>Non attivo</strong>, il parametro verr\00E0 sempre aggiunto alla richiesta. Questa rego')
||unistr('la \00E8 valida solo per i parametri di tipo <em>Stringa di query</em>, <em>Cookie</em> o <em>Intestazione HTTP</em>. '),
'</p>',
'<p>',
'    Esempio relativo a un parametro <strong>param2</strong> di tipo Stringa di query con un valore vuoto.',
'</p>',
'<ul>',
unistr('    <li>Omettere quando il valore \00E8 vuoto e impostato su <strong>Non attivo</strong>:<br>'),
'    http://api.example.com/url/path?param1=value1&amp;param2=</li>',
unistr('    <li>Omettere quando il valore \00E8 vuoto e impostato su <strong>Attivo</strong>:<br>'),
'    http://api.example.com/url/path?param1=value1</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
