wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(2232893313790545.4004)
,p_computation_sequence=>20
,p_computation_item=>'P1923_DATA_TYPE'
,p_computation_type=>'EXPRESSION'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'case ',
'    when    :P1923_PARAM_TYPE not in ( ''HEADER'', ''COOKIE'', ''URL_PATTERN'', ''QUERY_STRING'', ''BODY'' )',
'         or :P1923_DIRECTION = ''OUT''',
'    then null',
'    else coalesce( :P1923_DATA_TYPE, ''VARCHAR2'' )',
'end'))
,p_compute_when=>'APPLY_CHANGES,CREATE,CREATE_AND_ANOTHER'
,p_compute_when_type=>'REQUEST_IN_CONDITION'
);
