wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1813920010055316.4004)
,p_name=>'P1925_SINGLE_ROW_SELECTOR'
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(225897994729244504.4004)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Selettore di riga singola'
,p_source=>'SINGLE_ROW_SELECTOR'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>50
,p_cMaxlength=>255
,p_display_when=>'P1925_DATA_PROFILE_FOR'
,p_display_when2=>'REST_SOURCE'
,p_display_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Viene usato per i servizi REST che restituiscono un array JSON o un oggetto semplice, in base alla richiesta effettiva. Immettere l''espressione selettore per selezionare una singola riga dalla risposta dell''origine datiREST. ',
'</p>',
'<p>',
'    Esempio:',
'</p>',
'<ul>',
'    <li>L''endpoint di un servizio REST restituisce un array JSON: il profilo dati restituisce una <strong>tabella</strong><br>',
'        <code>http://{server}/path/service/emp</code><br>',
'        <pre>',
'{ "header": { "generated": "2018-10-19", "version": "1.0" },',
'  "body": { "items": [',
'          { "ename": "SMITH", "sal": 200 },',
'          { "ename": "SCOTT", "sal": 100 } ] } }        ',
'        </pre>',
'    </li>',
'    <li>Quando all''URL viene aggiunto un identificativo, viene restituita solo una riga:<br>',
'        <code>http://{server}/path/service/emp/<strong>SMITH</strong></code><br>',
'        <pre>',
'{ "header": { "generated": "2018-10-19", "version": "1.0" },',
'  "body":   { "ename": "SMITH", "sal": 200 } }',
'        </pre>',
'    </li>',
'</ul>',
'<p>',
'    In questo caso, usare <strong>body</strong> come <strong>Selettore di riga singola</strong>. L''attributo <strong>Selettore di righe</strong> (sopra) deve essere impostato su <strong>body.items</strong>.',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
