,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Specificare il nome della tabella di ricerca.</p>',
'<p><strong>Esempio:</strong></p>',
'<pre>',
'ENAME  EMPNO  SAL    DNAME',
'------ ------ ------ ------------',
'  7839 KING     5000 ACCOUNTING',
'  7788 SCOTT    3000 RESEARCH',
'     : :           : :',
'</pre>',
'<ul>',
'<li>Configurare la colonna <strong>DNAME_LOADED</strong> come colonna <strong>Dati</strong> con il selettore di <strong>DNAME</strong> o <strong>4</strong> (in base al tipo di selettore).</li>',
'<li>Usare <strong>DEPTNO</strong> come nome di colonna del profilo dati e <strong>Ricerca</strong> come tipo di colonna.</li>',
'<li>Usare <strong>DEPT</strong> come <strong>Nome tabella</strong></li>',
'<li>Usare <strong>DEPTNO</strong> come <strong>Colonna restituita</strong></li>',
unistr('<li><strong>DNAME</strong> \00E8 la <strong>Colonna tabella 1</strong></li>'),
unistr('<li><strong>DNAME_LOADED</strong> \00E8 la <strong>Colonna dati 1</strong>. Tenere presente che fa riferimento alla colonna del profilo dati contenente i dati effettivamente caricati.</li>'),
'</ul>',
'<p>',
'<br>',
unistr('Di conseguenza, &PRODUCT_NAME. cercher\00E0 i valori <strong>DEPTNO</strong> dalla tabella <strong>DEPT</strong>, usando i valori <strong>DNAME</strong> caricati. Questi verranno caricati come colonna <strong>DEPTNO</strong> della tabella di destinazione')
||'.',
'</p>',
''))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'case_sensitive', 'N',
  'display_as', 'POPUP',
  'fetch_on_search', 'N',
  'initial_fetch', 'FIRST_ROWSET',
  'manual_entry', 'N',
  'match_type', 'CONTAINS',
  'min_chars', '0')).to_clob
);
