wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(4702017184940016.4004)
,p_name=>'P1926_TRANSFORM_TYPE'
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(4701992042940015.4004)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Trasformazione valori'
,p_source=>'TRANSFORM_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'DATA.LOAD.TRANSFORM_TYPE'
,p_lov=>'.'||wwv_flow_imp.id(4818478622110870)||'.'
,p_lov_display_null=>'YES'
,p_lov_null_text=>'Nessuno'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Selezionare una semplice regola di trasformazione per modificare il valore caricato. Ad esempio, se i dati di origine contengono dati di colonna in formato maiuscole/minuscole misto, l''opzione <strong>Lettere minuscole</strong> o <strong>Lettere '
||'maiuscole</strong> consente di convertire i dati nel formato maiuscole/minuscole desiderato.',
'    </p>',
'<ul>',
'    <li><strong>Tronca a sinistra</strong>, <strong>Tronca a destra</strong> e <strong>Tronca</strong>:<br> tronca i caratteri specificati in <strong>Espressione 1</strong> dal lato sinistro, dal lato destro o da entrambi i lati del valore dei dati c'
||'aricati.</li>',
'    <li><strong>Sostituisci</strong>:<br> semplice sostituzione delle ricorrenze di <strong>Espressione&nbsp;1</strong> con <strong>Espressione&nbsp;2</strong>.</li>',
'    <li><strong>Lettere maiuscole</strong>:<br> converte il valore in lettere maiuscole.</li>',
'    <li><strong>Lettere minuscole</strong>:<br> converte il valore in lettere minuscole.</li>',
unistr('    <li><strong>Null if</strong>:<br> se il valore caricato \00E8 uguale alla stringa specificata in <strong>Espressione&nbsp;1</strong>, il valore verr\00E0 caricato come NULL.</li>'),
'    <li><strong>Espressione regolare Replace</strong>:<br> applica l''espressione regolare specificata in <strong>Espressione&nbsp;1</strong> e sostituisce tutte le corrispondenze con <strong>Espressione&nbsp;2</strong>.</li>',
'    <li><strong>Espressione regolare Null if</strong>:<br> se l''espressione regolare specificata in <strong>Espressione&nbsp;1</strong> corrisponde, carica il valore di colonna come NULL.</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
