wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(6927743131334108.4004)
,p_name=>'P1926_HAS_TABLE_COLUMN'
,p_item_sequence=>70
,p_item_plug_id=>wwv_flow_imp.id(225899656946244521.4004)
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_has_table_column number;',
'begin',
'    select 1',
'      into l_has_table_column',
'      from wwv_flow_document_sources',
'     where security_group_id       = :FLOW_SECURITY_GROUP_ID',
'       and flow_id                 = :FB_FLOW_ID',
'       and data_profile_id         = :P1926_DATA_PROFILE_ID',
'       and document_source_type    = ''JSON_TABLE''',
'       and :P1925_DATA_PROFILE_FOR = ''DOC_SOURCE''',
'       and rownum                  = 1;',
'',
'    return ''Y'';',
'exception',
'    when no_data_found then',
'        return ''N'';',
'end;'))
,p_source_type=>'FUNCTION_BODY'
,p_source_language=>'PLSQL'
,p_display_as=>'NATIVE_HIDDEN'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'value_protected', 'Y')).to_clob
);
