wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(225899759263244522.4004)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_FORM_FETCH'
,p_process_name=>'Fetch row from WWV_FLOW_DATA_PROFILE_COLS'
,p_attribute_02=>'WWV_FLOW_DATA_PROFILE_COLS'
,p_attribute_03=>'P1926_DATA_PROFILE_COLUMN_ID'
,p_attribute_04=>'ID'
,p_attribute_08=>'security_group_id = :FLOW_SECURITY_GROUP_ID'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>225899759263244522.4004
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(5270088765575514.4004)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'fetch non-dml item'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for l_prof_col in (',
'    select * from (',
'        select id                                      as column_id,',
'               column_type,',
'               expression1,',
'               lag( id )  over (order by sequence asc) as prev_column_id,',
'               lead( id ) over (order by sequence asc) as next_column_id',
'          from wwv_flow_data_profile_cols',
'         where flow_id           = :FB_FLOW_ID',
'           and security_group_id = :FLOW_SECURITY_GROUP_ID',
'           and data_profile_id   = :P1926_DATA_PROFILE_ID )',
'    where column_id  = :P1926_DATA_PROFILE_COLUMN_ID )',
'loop',
'    :P1926_NEXT_COLUMN_ID := l_prof_col.next_column_id;',
'    :P1926_PREV_COLUMN_ID := l_prof_col.prev_column_id;',
'    if l_prof_col.column_type = ''SQL_EXPRESSION'' then',
'        :P1926_SQL_EXPRESSION := l_prof_col.expression1;',
'    elsif l_prof_col.column_type = ''SQL_QUERY'' then',
'        :P1926_SQL_QUERY := l_prof_col.expression1;',
'    end if;',
'end loop;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>5270088765575514.4004
);
end;
