wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(225855266184926518.4004)
,p_plug_name=>'Server remoti'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4004)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Le informazioni sui server di un''origine dati REST vengono memorizzate sotto forma di oggetto <strong>Server remoto</strong>. I server remoti possono essere condivisi tra pi\00F9 origini dati REST. La modifica delle propriet\00E0 del server remoto, ad ese')
||unistr('mpio la possibilit\00E0 di spostare un oggetto server remoto da un sistema di test a un sistema di produzione, ha effetto su tutte le origini dati REST che fanno riferimento all''oggetto.</p>'),
'<p>I server remoti vengono memorizzati a livello di area di lavoro, pertanto sono visibili in tutte le applicazioni. Quando si esporta un''applicazione, i server remoti utilizzati vengono aggiunti al file di esportazione. Quando si importa l''applicazi'
||unistr('one in un''altra area di lavoro, &PRODUCT_NAME. controlla se l''area di lavoro di destinazione contiene gi\00E0 server remoti con lo stesso <strong>ID statico</strong>. Se un server remoto esiste gi\00E0, l''applicazione lo utilizzer\00E0, altrimenti i server remot')
||'i presenti nel file di importazione verranno creati nell''area di lavoro di destinazione.</p>'))
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>'nvl(#OWNER#.wwv_flow_preferences.get_preference(''FP_PREF_SHOW_INFORMATION''),''YES'') = ''YES'''
,p_plug_display_when_cond2=>'PLSQL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(249349483233883038.4004)
,p_plug_name=>'Server remoti'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209.4004)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with data as (',
'    select s.id,',
'           s.name,',
'           s.server_type,',
'           s.base_url,',
'           s.static_id,',
'           nvl2( s.configuration_procedure, ''Y'', ''N'' ) dynamic,',
'           count(m.id)  module_references,',
'           count(ma.id) auth_references,',
'           count(f.id)  app_references',
'      from wwv_remote_servers s',
'           left outer join wwv_flow_web_src_modules m ',
'                      on (     s.security_group_id = m.security_group_id',
'                           and s.id                = m.remote_server_id )',
'           left outer join wwv_flow_web_src_modules ma ',
'                      on (     s.security_group_id = ma.security_group_id',
'                           and s.id                = ma.auth_remote_server_id )',
'           left outer join wwv_flows f ',
'                      on (     s.security_group_id = f.security_group_id',
'                           and (    s.id = f.print_remote_server_id ',
'                                 or s.id = f.file_remote_server_id ) )',
'        --',
'     where s.server_type       in ( ''WEB_SERVICE'', ''AUTHENTICATION'', ''PRINT_SERVER'', ''CLOUD_OBJECT_STORE'' )',
'       and s.security_group_id  = :FLOW_SECURITY_GROUP_ID',
'       and not exists ( select 1 ',
'                          from wwv_flow_language_map ',
'                         where translation_flow_id in ( m.flow_id, ma.flow_id, f.id ) )',
'     group by s.id, s.name, s.server_type, s.base_url, s.static_id, s.credential_id, s.configuration_procedure',
') ',
'select ',
'    id,',
'    name,',
'    server_type,',
'    base_url,',
'    static_id,',
'    dynamic,',
'    module_references + auth_references + app_references as references',
'from data',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
