wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(525232563615218535.4004)
,p_validation_name=>'URL must start with http or https'
,p_validation_sequence=>30
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'   :P1932_BASE_URL like ''https://%''',
'or :P1932_BASE_URL like ''http://%''',
'or (   :P1932_BASE_URL like ''#%#%''',
'   and :P1932_TYPE in ( ''WEB_SERVICE'', ''AUTHENTICATION'' )',
'   )'))
,p_validation2=>'PLSQL'
,p_validation_type=>'EXPRESSION'
,p_error_message=>'L''URL di base deve iniziare con http:// o https://'
,p_validation_condition=>'APPLY_CHANGES:CREATE'
,p_validation_condition_type=>'REQUEST_IN_CONDITION'
,p_associated_item=>wwv_flow_imp.id(225855813992926524.4004)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(537042329937394616.4004)
,p_validation_name=>'Cannot delete used Remote Server'
,p_validation_sequence=>40
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select s.id',
'  from wwv_remote_servers s ',
' where exists( select 1 ',
'                 from wwv_flow_web_src_modules m ',
'                where m.security_group_id = s.security_group_id',
'                  and (    m.remote_server_id      = s.id ',
'                        or m.auth_remote_server_id = s.id ) )',
'   and s.server_type       in ( ''WEB_SERVICE'', ''AUTHENTICATION'' )',
'   and s.security_group_id  = :FLOW_SECURITY_GROUP_ID',
'   and s.id                 = :P1932_ID',
'union all',
'select s.id',
'  from wwv_remote_servers s ',
' where s.security_group_id  = :FLOW_SECURITY_GROUP_ID',
'   and s.id                 = :P1932_ID',
'   and (    exists ( select 1',
'                       from wwv_flows f',
'                      where f.file_remote_server_id = s.id',
'                        and f.security_group_id     = s.security_group_id )',
'         or exists ( select 1',
'                       from wwv_flows f',
'                      where f.print_remote_server_id = s.id',
'                        and f.security_group_id      = s.security_group_id ) )'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>unistr('Il server remoto \00E8 in uso e non pu\00F2 essere eliminato.')
,p_when_button_pressed=>wwv_flow_imp.id(225856518442926531.4004)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(2003141838223129.4004)
,p_validation_name=>'Syntax Check'
,p_validation_sequence=>50
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'return wwv_flow_code_exec_dev.check_code (',
'           p_type            => wwv_flow_code_exec_dev.c_check_procedures,',
'           p_code            => :P1932_PLSQL_CODE,',
'           p_language        => wwv_flow_code_exec.c_plsql,',
'           p_parse_as_schema => wwv_flow_security.g_parse_as_schema );'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_validation_condition=>':P1932_PLSQL_CODE is not null and nvl(:P1932_CHECK_SYNTAX, ''YES'') = ''YES'''
,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'EXPRESSION'
,p_associated_item=>wwv_flow_imp.id(2000966576223107.4004)
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(2003298552223130.4004)
,p_validation_name=>'Check syntax Configuration Procedure'
,p_validation_sequence=>60
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'return wwv_flow_code_exec_dev.check_code (',
'           p_code            => ',
'                   ''declare'' || wwv_flow.LF ||',
'                   ''    l_remote_server_info   wwv_flow_plugin_api.t_remote_server_info;'' || wwv_flow.LF ||',
'                   ''    l_remote_server_config wwv_flow_plugin_api.t_remote_server_config;'' || wwv_flow.LF ||',
'                   :P1932_PLSQL_CODE || wwv_flow.LF ||',
'                   ''begin'' || wwv_flow.LF ||',
'                   :P1932_CONFIGURATION_PROCEDURE || ''( l_remote_server_info, l_remote_server_config );'' || wwv_flow.LF ||',
'                   ''end;'',',
'           p_language        => wwv_flow_code_exec.c_plsql,',
'           p_parse_as_schema => wwv_flow_security.g_parse_as_schema );'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_validation_condition=>':P1932_CONFIGURATION_PROCEDURE is not null and nvl(:P1932_CHECK_SYNTAX, ''YES'') = ''YES'''
,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'EXPRESSION'
,p_associated_item=>wwv_flow_imp.id(2000804282223106.4004)
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
