wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3850682801212121729.4004)
,p_name=>'P1941_WEB_SRC_TYPE'
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(3850682090247121721.4004)
,p_item_default=>'NATIVE_HTTP'
,p_prompt=>'Tipo di origine dati REST'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'WEB_SOURCE_MODULE_TYPES'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'         select wwv_flow_lang.system_message(''WEB_SOURCE.''|| name_with_prefix) as d,',
'               name_with_prefix as r',
'          from wwv_flow_native_plugins',
'         where plugin_type = ''WEB SOURCE TYPE''',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id           = to_number(:FB_FLOW_ID)',
'           and security_group_id = to_number(:WORKSPACE_ID)',
'           and plugin_type       = ''WEB SOURCE TYPE''',
'       )',
' order by 1'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Determina il tipo di origine dati REST.',
'<ul>',
'<li><strong>HTTP semplice</strong> indica un feed di dati HTTP semplice. &PRODUCT_NAME. suppone che tutti i dati vengano restituiti con la prima richiesta e che il server non supporti l''applicazione di filtri, l''ordinamento o altre funzioni avanzate '
||'dei servizi REST lato server. Tutti i dettagli e i parametri di richiamo devono essere configurati manualmente.</li>',
'<li><strong>Oracle REST Data Services</strong> (ORDS) indica i servizi RESTful forniti da ORDS. Questi servizi REST sono conformi allo <em>standard Oracle REST</em>, il che significa che le operazioni GET, POST, PUT o DELETE sono standardizzate. L''ap'
||unistr('plicazione di filtri e l''ordinamento lato server sono supportati. &PRODUCT_NAME. pu\00F2 sfruttare queste funzioni delegando la gestione delle espressioni order-by e filter dei report al servizio REST.</li>'),
'<li><strong>Query SQL abilitata per REST</strong> indica un''origine REST su una query SQL eseguita su un riferimento SQL abilitato per REST. &PRODUCT_NAME. supporta l''applicazione di filtri e l''impaginazione, ma nessun DML su questi endpoint.</li>',
'<li><strong>Servizio REST Oracle Cloud Applications (SaaS)</strong> indica i Web Service RESTful forniti da Oracle Cloud Applications (SaaS). Usare questo tipo di Web Service per integrare i servizi REST Oracle SaaS nell''applicazione &PRODUCT_NAME.. '
||'&PRODUCT_NAME. supporta l''impaginazione per questi servizi.</li>',
'<li><strong>Servizio REST dell''infrastruttura Oracle Cloud (OCI)</strong> indica i Web Service RESTful forniti dall''infrastruttura Oracle Cloud. Usare questo tipo di Web Service per integrare i servizi REST OCI (ad esempio quelli che accedono all''are'
||'a di memorizzazione degli oggetti) nell''applicazione &PRODUCT_NAME.. &PRODUCT_NAME. supporta l''impaginazione per questi servizi.</li>',
'<li><strong>Servizio REST OData</strong> indica un servizio REST che implementa il protocollo Open Data (OData), ovvero uno standard OASIS approvato da ISO/IEC, che definisce un set di best practice per la creazione e l''utilizzo di API RESTful. <em>&'
||'PRODUCT_NAME. attualmente supporta solo le API <em>Fetch</em> (lettura dati); le operazioni DML per OData non sono ancora supportate.</em></li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
