wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(226574766423012964.4004)
,p_name=>'P1943_AUTH_TYPE'
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(229756918559737172.4004)
,p_prompt=>'Tipo di autenticazione'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'CREDENTIALS_TYPE'
,p_lov=>'.'||wwv_flow_imp.id(154078822199034715)||'.'
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- Seleziona -'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4004)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Specificare qui il tipo di autenticazione. Attualmente, Oracle APEX supporta i tipi di autenticazione riportati di seguito.</p>',
'<ul>',
'    <li><strong>Autenticazione di base</strong>: invia il nome utente e la password in formato codificato Base64 come intestazione della richiesta di <strong>autorizzazione</strong>.',
'    </li>',
'    <li><strong>Credenziali client OAuth2</strong>: Oracle APEX scambia l''ID client e il segreto client per un <strong>token di accesso</strong> utilizzando un URL server. Il token di accesso viene in seguito usato per eseguire la richiesta effettiva'
||unistr('. Se il token di accesso \00E8 scaduto, APEX ne richieder\00E0 uno nuovo in modo trasparente.</li>'),
'    <li><strong>Autenticazione nativa OCI</strong>: Oracle APEX firma le richieste nell''API REST dell''<em>infrastruttura Oracle Cloud (OCI)</em>, come descritto nella <a rel="noopener noreferrer" href="https://docs.cloud.oracle.com/en-us/iaas/Content'
||unistr('/API/Concepts/signingrequests.htm">documentazione OCI</a>. Questo tipo \00E8 disponibile solo in Oracle Database 18c e versioni successive.</li>'),
unistr('    <li><strong>Intestazione HTTP</strong>: la credenziale viene aggiunta alla richiesta REST sotto forma di intestazione HTTP. Il nome della credenziale \00E8 il nome dell''intestazione HTTP, il segreto della credenziale \00E8 il valore dell''intestazione HTT')
||unistr('P. Oracle APEX non aggiunge questi segreti al log di debug n\00E9 a qualsiasi altro log.</li>'),
unistr('    <li><strong>Stringa di query dell''URL</strong>: la credenziale viene aggiunta all''URL della richiesta REST sotto forma di parametro <em>stringa di query</em> (ad esempio: <strong>?name=value</strong>). Questa opzione pu\00F2 essere utile con le chiav')
||unistr('i API. Oracle APEX non aggiunge tali segreti al log di debug n\00E9 a qualsiasi altro log. Tuttavia, i server proxy o altri di tipo intermedio registreranno queste credenziali nei rispettivi file di log.</li>'),
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
