wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(236247462853284209.4004)
,p_name=>'P1944_ROW_SELECTOR'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(236247361887284208.4004)
,p_prompt=>'Selettore di righe (non specificare per rilevamento automatico)'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>75
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561549638722251517.4004)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Il <strong>selettore di righe</strong> indica l''espressione di percorso JSON o XML che raggiunge l''attributo JSON o il tag XML contenente l''array di righe. Quando non viene fornito alcun valore, &PRODUCT_NAME. tenter\00E0 di individuare automaticament')
||'e il selettore di righe. ',
'</p>',
'<p>Esempi XML:</p>',
'<ul>',
'<li>/rss/channel/item</li>',
'<li>/root/tag/array</li>',
'</ul>',
'<p>',
'    ',
'</p>',
'<p>Esempi JSON:</p>',
'<ul>',
'<li>.</li>',
'<li>items</li>',
'<li>result.items</li>',
'<li>items[0].results</li>',
'</ul>',
'<p>',
'    ',
'</p><p>',
unistr('    Non \00E8 possibile utilizzare l''espressione "[*]" in un selettore di righe JSON. Ad esempio, la sintassi, <span style="text-decoration: line-through";>items[*].employees</span> \00E8 vietata.'),
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
