wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3802161062901510.4004)
,p_plug_name=>'Sincronizzazione REST'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--noBorder'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4004)
,p_plug_display_sequence=>40
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('<strong>Sincronizzazione REST</strong> consente di conservare automaticamente il contenuto di una tabella locale con i dati di un servizio REST. La sincronizzazione pu\00F2 essere attivata manualmente o periodicamente, utilizzando un job dello scheduler.'),
'</p>',
'<p>',
unistr('APEX consente di creare la tabella locale in base alle colonne visibili nel <strong>Profilo dati</strong> dell''origine dati REST. Poich\00E9 la tabella \00E8 un <em>oggetto visibile</em> nello schema di database, gli sviluppatori <em>possono</em> aggiungere ')
||unistr('indici, modificare le propriet\00E0 fisiche o perfino aggiungere altre colonne alla tabella. '),
'</p>',
'<p>',
unistr('Se la tabella <em>non</em> \00E8 sincronizzata con il Profilo dati, la sincronizzazione REST continuer\00E0 a funzionare per le colonne presenti <em>sia</em> nella tabella che nel Profilo dati (le altre colonne verranno ignorate). APEX genera tuttavia istruz')
||'ioni DDL SQL per sincronizzare nuovamente le colonne della tabella con il Profilo dati. Le istruzioni generate possono essere aggiunte all''applicazione come oggetti di supporto.',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3802859702901517.4004)
,p_plug_name=>'Sincronizzazione non configurata'
,p_region_template_options=>'#DEFAULT#:a-Alert--info:a-Alert--horizontal'
,p_plug_template=>wwv_flow_imp.id(770240542605907344.4004)
