,p_process_name=>'get, validate and store document'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_document   blob;',
'begin',
'    if :P1970_UPLOAD is not null then',
'        select blob_content ',
'          into l_document',
'          from wwv_flow_temp_files',
'         where name = :P1970_UPLOAD;',
'',
'    elsif :P1970_ENDPOINT_URL is not null then',
'',
'        l_document := wwv_flow_webservices_api.make_rest_request_b(',
'                          p_url                  => :P1970_ENDPOINT_URL,',
'                          p_http_method          => ''GET'',',
'                          p_proxy_override       => :P1970_PROXY_SERVER,',
'                          p_credential_static_id => :P1970_CREDENTIAL_ID,',
'                          p_token_url            => :P1970_TOKEN_SERVER_URL );',
'',
'    end if;',
'',
'    wwv_flow_web_src_openapi.store_and_validate_openapi( l_document, :P1970_COLLECTION_NAME );',
'',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>1614530959343708.4004
);
