,p_branch_point=>'BEFORE_HEADER'
,p_branch_type=>'REDIRECT_URL'
,p_branch_sequence=>10
,p_branch_condition_type=>'ITEM_IS_NOT_NULL'
,p_branch_condition=>'P2116_HALT_Y'
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(77661585350399601.4004)
,p_name=>'P2116_HALT_Y'
,p_item_sequence=>110
,p_display_as=>'NATIVE_HIDDEN'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'value_protected', 'Y')).to_clob
,p_item_comment=>wwv_flow_string.join(wwv_flow_t_varchar2(
'If Y, don''t retry installing the supporting objects.',
'added for',
'Bug 20137505 - IMPORTING APPLICATION WITH INVALID SUPPORT OBJECT CONDITION RESULTS IN LOOP'))
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(212278801026676927.4004)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Install'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    for c1 in ( select id, owner from ',
'                    ( select id ',
'                        from wwv_flow_install ',
'                       where flow_id           = :FB_FLOW_ID',
'                         and security_group_id = :WORKSPACE_ID ), ',
'                    ( select owner ',
'                        from wwv_flows',
'                       where id                = :FB_FLOW_ID',
'                         and security_group_id = :WORKSPACE_ID ) )',
'    loop',
'      wwv_flow_install_wizard.install (',
'          p_flow_id     => :FB_FLOW_ID,',
'          p_install_id  => c1.id,',
'          p_schema      => c1.owner',
'       );',
'    end loop;',
'',
'exception',
'    when others then',
'        rollback;',
'        -- flag 2116 to not retry installation of supporting objects',
'        htmldb_util.set_session_state(''P2116_HALT_Y'',''Y'');',
'        raise;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Impossibile installare l''applicazione.'
,p_internal_uid=>212278801026676927.4004
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(212279305527678271.4004)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process Build Options'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'update wwv_flow_patches ',
'   set patch_status = ''EXCLUDE'' ',
' where id in (select build_opt_id ',
'                from wwv_flow_install_build_opt ',
'               where flow_id = :FB_FLOW_ID ',
'                 and security_group_id = :flow_security_group_id) ',
'   and instr('':''||:P2107_BUILD_OPTIONS||'':'', '':''||ID||'':'') = 0',
'   and security_group_id = :flow_security_group_id;',
'',
'update wwv_flow_patches ',
'   set patch_status = ''INCLUDE'' ',
' where instr('':''||:P2107_BUILD_OPTIONS||'':'', '':''||ID||'':'') > 0',
'   and flow_id = :FB_FLOW_ID',
'   and security_group_id = :flow_security_group_id;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>212279305527678271.4004
);
end;
