,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set Data Source Items'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- reset previous values, if any',
':P2501_TAB_OWNER := null;',
':P2501_TAB_NAME := null;',
':P2501_QUERY_TYPE := null;',
':P2501_SQL_SOURCE := null;',
'',
'if :P2501_LOCATION = wwv_flow_exec_api.c_location_local_db then',
'    :P2501_TAB_OWNER        := :P2501_TABLE_OWNER;',
'    :P2501_TAB_NAME         := :P2501_TABLE_NAME;',
'    :P2501_QUERY_TYPE       := :P2501_SOURCE_TYPE;',
'    :P2501_SQL_SOURCE       := :P2501_SQL;',
'elsif :P2501_LOCATION = wwv_flow_exec_api.c_location_remote_db then',
'    :P2501_TAB_OWNER        := :P2501_REMOTE_TABLE_OWNER;',
'    :P2501_TAB_NAME         := :P2501_REMOTE_TABLE_NAME;',
'    :P2501_QUERY_TYPE       := :P2501_REMOTE_SOURCE_TYPE;',
'    :P2501_SQL_SOURCE       := :P2501_REMOTE_SQL;',
'end if;          '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'P2501_SHOW_DATA_SOURCE'
,p_process_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_process_when2=>'Y'
,p_internal_uid=>29406364145885111.4004
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(4403399320104819.4004)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load Columns to Collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_extended_describe boolean;',
'begin',
'    l_extended_describe := :P2500_PAGE_TYPE in (''FORM'',''MD'') ',
'                           or (:P2500_PAGE_TYPE in (''INTERACTIVE'',''CLASSIC'',''GRID'') and :P2501_INCLUDE_FORM = ''Y'')',
'                           or (:P2500_PAGE_TYPE = ''GRID'' and :P2501_EDITABLE = ''Y'');',
'    -- output',
'    -- c001 => column_name_esc',
'    -- c002 => column_name',
'    -- c003 => data_type',
'    -- c004 => is_primary_key (Y/N) -- Only available when p_extended_describe is TRUE                           ',
'    wwv_flow_wizard_api.create_column_collection (',
'        p_collection_name        => ''WIZ_COLUMNS_LIST'',',
'        p_location               => :P2501_LOCATION,',
'        p_query_type             => :P2501_QUERY_TYPE,',
'        p_owner                  => :P2501_TAB_OWNER,',
'        p_table_name             => :P2501_TAB_NAME,',
'        p_sql_query              => :P2501_SQL_SOURCE,',
'        p_web_src_module_id      => :P2501_WEB_SRC_MODULE_ID,',
'        p_document_source_id     => :P2501_DOCUMENT_SOURCE_ID,',
'        p_array_column_id        => :P2501_ARRAY_COLUMN_ID,    ',
'        p_remote_server_id       => :P2501_REMOTE_SERVER_ID,',
'        p_extended_describe      => l_extended_describe );',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
':P2501_SHOW_DATA_SOURCE = ''Y''',
'-- we show data source to calendar, but calendar uses plug-in framework',
'-- so loading columns data into this collection is not required',
' and :P2500_PAGE_TYPE not in (''CALENDAR'')'))
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>4403399320104819.4004
);
