wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1636433641313202.4004)
,p_name=>'P3112_PQL_MATCH_CLAUSE'
,p_item_sequence=>130
,p_item_plug_id=>wwv_flow_imp.id(66471911938671229.4004)
,p_prompt=>'Clausola Match'
,p_display_as=>'NATIVE_TEXTAREA'
,p_cSize=>60
,p_cHeight=>2
