,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Immettere il pattern di percorso da trovare nel grafico delle propriet\00E0. Per trovare tutti gli assi nel grafico, usare quanto segue: <strong>(a) - [e] -> (b)</strong>. Usare inoltre i <em>vincoli di etichetta</em> per limitare i tipi di vertice o ')
||'di asse di interesse.</p>',
'<p><strong>Esempi</strong></p>',
'<dl>',
'<dt>Trovare tutte le persone che hanno acquistato automobili.</dt><dd><pre>(p is person) - [t is buys] -> (c is car)</pre></dd>',
'<dt>Trovare tutti i dipendenti che lavorano nei reparti.</dt><dd><pre>(e is employees) - [is works_at] -> (d is departments)</pre></dd>',
'<dt>Trovare tutti i dipendenti che lavorano nei reparti e che hanno acquistato automobili.</dt><dd><pre>(e is employees) - [is works_at] -> (d is departments), (e is employees) - [t is buys] -> (c is car)</pre></dd>',
'</dl>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'auto_height', 'N',
  'character_counter', 'N',
  'resizable', 'Y',
  'trim_spaces', 'BOTH')).to_clob
);
