wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1760805302180991.4004)
,p_name=>'P3120_SEARCH_PREFIX'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(1757925019180889.4004)
,p_item_source_plug_id=>wwv_flow_imp.id(1757925019180889.4004)
,p_prompt=>'Prefisso query di ricerca'
,p_source=>'SEARCH_PREFIX'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>60
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Immettere un prefisso che deve essere utilizzato dagli utenti finali nelle query di ricerca. Un termine di ricerca con prefisso verr\00E0 utilizzato solo per'),
unistr('    le configurazioni di ricerca con lo stesso prefisso. Se in una query di ricerca si utilizza un prefisso che non \00E8 definito in '),
unistr('    <em>nessuna</em> configurazione di ricerca, tale prefisso verr\00E0 ignorato e verr\00E0 utilizzato il termine completo per la ricerca.'),
'</p>',
'<p>Esempi:</p>',
'<p> Esistono due configurazioni di ricerca: <strong>Employees</strong> con il prefisso <strong>emp</strong> ',
'    e <strong>Jobs</strong> con il prefisso <strong>job</strong>.',
'</p>',
'<dl>',
'    <dt>emp:king president</dt>',
unistr('    <dd>La parola chiave <strong>king</strong> verr\00E0 cercata solo nella configurazione di ricerca'),
'        <strong>Employees</strong>, mentre <strong>president</strong> in entrambe le configurazioni.</dd>',
'    <dt>emp:king job:president</dt>',
unistr('    <dd>La parola chiave <strong>king</strong> verr\00E0 cercata nella configurazione di ricerca '),
unistr('        <strong>Employees</strong>, mentre <strong>president</strong> verr\00E0 cercato solo in <strong>Jobs</strong>.</dd>'),
'    <dt>emp:king depts:"new york"</dt>',
unistr('    <dd>La parola chiave <strong>king</strong> verr\00E0 cercata solo nella configurazione di ricerca '),
unistr('        <strong>Employees</strong>. <strong>depts:"new york"</strong> verr\00E0 cercata in entrambe le configurazioni,'),
unistr('        perch\00E9 il prefisso <strong>depts</strong> non \00E8 stato definito in nessuna configurazione.</dd>'),
'</dl>',
''))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
