,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
'  <li>',
'    <strong>Standard:</strong>',
unistr('    Definire un''origine dati ricercabile, che pu\00F2 essere una tabella, una query SQL o un''origine dati REST. '),
'    La ricerca viene eseguita mediante una query SQL che utilizza espressioni LIKE. ',
'  </li>',
'  <li>',
'    <strong>Oracle Vector Search:</strong>',
'    Effettuare ricerche usando Oracle Vector Search (richiede Oracle Database 23ai o versioni successive).<br/>',
unistr('    Richiede un provider vettoriale che verr\00E0 usato per ottenere l''incorporamento di una frase di ricerca.'),
'  </li>',
'  <li>',
'    <strong>Oracle Text:</strong>',
unistr('    Definire una tabella o una query SQL ricercabile, per la quale \00E8 stato gi\00E0 creato un indice Oracle Text. La ricerca'),
unistr('    viene eseguita utilizzando la funzione Oracle Text, che fornisce funzionalit\00E0 per le ricerche linguistiche'),
'    e non esatte.',
'  </li>',
'  <li>',
'    <strong>Ricerca globale Oracle:</strong>',
'    La ricerca viene eseguita utilizzando un indice di ricerca globale Oracle (richiede Oracle Database 23ai o versione successiva).<br/>',
'    <em>L''indice deve trovarsi nello schema di analisi dell''applicazione.</em>',
'  </li>',
'  <li>',
'    <strong>Lista:</strong>',
'    La ricerca viene eseguita in una <em>lista</em> selezionata da Componenti condivisi.',
'  </li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'based_on', 'LOV',
  'format', 'PLAIN',
  'send_on_page_submit', 'Y',
  'show_line_breaks', 'Y')).to_clob
);
