 p_id=>wwv_flow_imp.id(1776874750181057.4004)
,p_name=>'P3120_DEFAULT_ROW_HTML_EXPR'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>170
,p_item_plug_id=>wwv_flow_imp.id(6700676601775302.4004)
,p_item_source_plug_id=>wwv_flow_imp.id(1757925019180889.4004)
,p_prompt=>'Modello di riga dei risultati predefinito'
,p_source=>'DEFAULT_ROW_HTML_EXPR'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>60
,p_cMaxlength=>4000
,p_cHeight=>5
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'Immettere l''espressione HTML per visualizzare una riga dei risultati della ricerca. Utilizzare la sintassi <code>&COLUMN.</code> per mostrare i valori della colonna in HTML. Supporta le direttive del modello. Inoltre, sono disponibili le seguenti sos'
||'tituzioni:',
'</p>',
'<dl>',
'<dt>ICON_TYPE</dt>',
unistr('<dd>Rappresenta il tipo di icona, che pu\00F2 essere <strong>CLASS</strong>, <strong>URL</strong> o <strong>INITIALS</strong>.</dd>'),
'<dt>ICON_VALUE</dt>',
'<dd>Il valore effettivo dell''icona, a seconda del valore di <strong>ICON_TYPE</strong></dd>',
'<dt>RESULT_CSS_CLASSES</dt>',
'<dd>Le classi CSS applicate a ciascun risultato, in base all''attributo <strong>Classi CSS risultato</strong>.</dd>',
'<dt>APEX$ORATEXT_SCORE</dt>',
'<dd>La colonna che rappresenta il punteggio di Oracle Text per i tipi di ricerca Oracle Text.</dd>',
'<dt>APEX$VECTOR_DISTANCE</dt>',
'<dd>La colonna che rappresenta la distanza vettoriale per i tipi di ricerca Oracle Vector Search.</dd>',
'</dl>',
'<p>Esempio:</p>',
'<pre>',
'&lt;div class="a-ResultsItem &amp;RESULT_CSS_CLASSES!ATTR."&gt;',
'  {if ?ICON_VALUE/}',
'    {case ICON_TYPE/}',
'      {when INITIALS/}',
'        &lt;div class="a-ResultItem-initials u-color-var"&gt;&amp;ICON_VALUE.&lt;/div&gt;',
'      {when URL/}',
'        &lt;div class="a-ResultItem-image"&gt;&lt;img src="&amp;ICON_VALUE!ATTR." alt="&amp;ENAME!ATTR." role="presentation" /&gt;&lt;/div&gt;',
'      {when CLASS/}',
'        &lt;div class="a-ResultItem-icon u-color-var"&gt;&lt;span class="fa &amp;ICON_VALUE!ATTR." aria-hidden="true"&gt;&lt;/span&gt;&lt;/div&gt;',
'    {endcase/}',
'  {endif/}',
'  &lt;div class="a-ResultsItem-content"&gt;',
'    &lt;div class="a-ResultsItem-header"&gt;',
'      &lt;span class="a-ResultsItem-title"&gt;&lt;a href="f?p=&amp;APP_ID.:&amp;20:&amp;SESSION.::::P20_EMPNO:&amp;EMPNO."&gt;&amp;ENAME.&lt;/a&gt;&lt;/span&gt;',
'      &lt;span class="a-ResultsItem-badge"&gt;&amp;SAL.&lt;/span&gt;',
'    &lt;/div&gt;',
'    &lt;div class="a-ResultsItem-description"&gt;&amp;RESUMEE.&lt;/div&gt;',
'    &lt;div class="a-ResultsItem-attributes"&gt;',
'      {if ?COMM/}&lt;span class="a-ResultsItem-attribute"&gt;&amp;COMM.&lt;/span&gt;{endif/}',
'      {if ?JOB/}&lt;span class="a-ResultsItem-attribute"&gt;&amp;JOB.&lt;/span&gt;{endif/}',
'    &lt;/div&gt;',
'    &lt;div class="a-ResultsItem-misc"&gt;&amp;HIREDATE.&lt;/div&gt;',
'  &lt;/div&gt;',
'&lt;/div&gt;',
'</pre>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
