 p_id=>wwv_flow_imp.id(2419821387518826.4004)
,p_process_sequence=>20
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Consolidate Item Values'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    procedure clear_web_source is',
'    begin',
'        :P3120_EXTERNAL_FILTER_EXPR := null;',
'        :P3120_WEB_SRC_FUNCTION     := null;',
'        :P3120_POST_PROC_TYPE       := null;',
'        :P3120_WEB_SRC_MODULE_ID    := null;',
'    end clear_web_source;',
'',
'    procedure clear_unused_query_params is',
'    begin',
'        if     :P3120_QUERY_TYPE  = ''TABLE''',
'            or :P3120_SEARCH_TYPE = ''TEXT_DBMS_SEARCH''',
'        then',
'            :P3120_QUERY_SQL          := null;',
'            :P3120_QUERY_FUNC_LANG    := null;',
'            :P3120_OPTIMIZER_HINT     := null;',
'            :P3120_PQL_COLUMNS_CLAUSE := null;',
'            :P3120_PQL_MATCH_CLAUSE   := null;',
'',
'        elsif :P3120_QUERY_TYPE = ''GRAPH'' then',
'            :P3120_QUERY_SQL          := null;',
'            :P3120_QUERY_FUNC_LANG    := null;',
'            :P3120_OPTIMIZER_HINT     := null;',
'        else',
'            :P3120_QUERY_TABLE        := null;',
'            :P3120_QUERY_OWNER        := null;',
'            :P3120_QUERY_WHERE        := null;',
'            :P3120_PQL_COLUMNS_CLAUSE := null;',
'            :P3120_PQL_MATCH_CLAUSE   := null;',
'',
'            if :P3120_QUERY_TYPE = ''SQL'' then :P3120_QUERY_FUNC_LANG := null; end if;',
'        end if;',
'',
'    end clear_unused_query_params;',
'',
'    procedure clear_remote_source is',
'    begin',
'        :P3120_REMOTE_SERVER_ID    := null;',
'    end clear_remote_source;',
'begin',
'    if :P3120_SEARCH_TYPE in ( ''SIMPLE'', ''TEXT_MANUAL'', ''TEXT_DBMS_SEARCH'', ''VECTOR'' ) then',
'',
'        if :P3120_SEARCH_TYPE = ''TEXT_MANUAL'' then',
'             :P3120_LOCATION            := ''LOCAL'';',
'             :P3120_ORATEXT_SOURCE_TYPE := coalesce( :P3120_ORATEXT_SOURCE_TYPE, ''TABLE'' );',
'             :P3120_QUERY_TYPE          := :P3120_ORATEXT_SOURCE_TYPE;',
'             :P3120_QUERY_ORDER_BY      := :P3120_ORATEXT_ORDER_BY;',
'',
'             if :P3120_ORATEXT_SOURCE_TYPE = ''TABLE'' then',
'                 :P3120_QUERY_OWNER    := :P3120_ORATEXT_OWNER;',
'                 :P3120_QUERY_TABLE    := :P3120_ORATEXT_TABLE;',
'                 :P3120_QUERY_WHERE    := :P3120_ORATEXT_WHERE;',
'             elsif :P3120_ORATEXT_SOURCE_TYPE = ''SQL'' then',
'                  :P3120_QUERY_SQL     := :P3120_ORATEXT_SQL;',
'             end if;',
'',
'             clear_unused_query_params;',
'             clear_remote_source;',
'             clear_web_source;',
'        elsif :P3120_SEARCH_TYPE = ''TEXT_DBMS_SEARCH'' then',
'             :P3120_LOCATION            := ''LOCAL'';',
'             :P3120_QUERY_TYPE          := null;',
'             :P3120_QUERY_OWNER         := :P3120_SEARCH_SOURCE_OWNER;',
'             :P3120_QUERY_TABLE         := :P3120_SEARCH_SOURCE_NAME;',
'             :P3120_QUERY_ORDER_BY      := :P3120_SEARCH_ORDER_BY;',
'',
'             clear_unused_query_params;',
'             clear_remote_source;',
'             clear_web_source;',
'        elsif :P3120_SEARCH_TYPE = ''VECTOR'' then',
'             :P3120_LOCATION             := ''LOCAL'';',
'             :P3120_VECTOR_SOURCE_TYPE   := coalesce( :P3120_VECTOR_SOURCE_TYPE, ''TABLE'' );',
'             :P3120_QUERY_TYPE           := :P3120_VECTOR_SOURCE_TYPE;',
'             :P3120_ORATEXT_INDEX_COLUMN := :P3120_VECTOR_COLUMN;',
'',
'             if :P3120_VECTOR_SOURCE_TYPE = ''TABLE'' then',
'                 :P3120_QUERY_OWNER    := :P3120_VECTOR_OWNER;',
'                 :P3120_QUERY_TABLE    := :P3120_VECTOR_TABLE;',
'                 :P3120_QUERY_WHERE    := :P3120_VECTOR_WHERE;',
'             elsif :P3120_VECTOR_SOURCE_TYPE = ''SQL'' then',
'                  :P3120_QUERY_SQL     := :P3120_VECTOR_SQL;',
'             end if;',
'',
'             clear_unused_query_params;',
'             clear_remote_source;',
'             clear_web_source; ',
'        else',
'            if :P3120_LOCATION = ''LOCAL'' then',
'    ',
'                :P3120_QUERY_TYPE      := coalesce( :P3120_QUERY_TYPE, ''TABLE'' );',
'                :P3120_QUERY_SQL       := case :P3120_QUERY_TYPE',
'                                              when ''SQL''                     then :P3120_QUERY_SQL',
'                                              when ''FUNC_BODY_RETURNING_SQL'' then :P3120_QUERY_FUNC_BODY end;',
'                :P3120_QUERY_FUNC_LANG := case when :P3120_QUERY_TYPE = ''FUNC_BODY_RETURNING_SQL'' then :P3120_QUERY_FUNC_LANG end;',
'',
'                if :P3120_QUERY_TYPE = ''GRAPH'' then',
'                    :P3120_QUERY_TABLE     := :P3120_GRAPH_NAME;',
'                    :P3120_QUERY_WHERE     := :P3120_PQL_WHERE_CLAUSE;',
'                end if;',
'',
'                clear_unused_query_params;',
'                clear_remote_source;',
'                clear_web_source;',
'',
'            elsif :P3120_LOCATION = ''REMOTE'' then',
'    ',
'                :P3120_REMOTE_SOURCE_TYPE := coalesce( :P3120_REMOTE_SOURCE_TYPE, ''TABLE'' );',
'                --',
'                :P3120_QUERY_TYPE          := :P3120_REMOTE_SOURCE_TYPE;',
'                :P3120_QUERY_ORDER_BY      := :P3120_REMOTE_ORDER_BY;',
'                ',
'                if :P3120_REMOTE_SOURCE_TYPE = ''TABLE'' then',
'                    :P3120_QUERY_OWNER     := :P3120_REMOTE_TABLE_OWNER;',
'                    :P3120_QUERY_TABLE     := :P3120_REMOTE_TABLE_NAME;',
'                    :P3120_QUERY_WHERE     := :P3120_REMOTE_WHERE;',
'                else',
'                    :P3120_QUERY_SQL       := case :P3120_REMOTE_SOURCE_TYPE',
'                                                  when ''SQL''                     then :P3120_REMOTE_SQL',
'                                                  when ''FUNC_BODY_RETURNING_SQL'' then :P3120_REMOTE_FUNC_BODY end;',
'                    :P3120_QUERY_FUNC_LANG := case when :P3120_REMOTE_SOURCE_TYPE = ''FUNC_BODY_RETURNING_SQL'' then :P3120_REMOTE_FUNC_BODY_LANG end;',
'                end if;',
'',
'                clear_unused_query_params;',
'                clear_web_source;',
'            elsif :P3120_LOCATION = ''WEB_SOURCE'' then',
'    ',
'                if :P3120_OLD_WEB_SRC_MODULE_ID = :P3120_WEB_SRC_MODULE_ID then',
'                    if :P3120_POST_PROC_TYPE = ''WHERE_ORDER_BY_CLAUSE'' then',
'                        :P3120_QUERY_WHERE     := :P3120_POST_PROC_WHERE;',
'                        :P3120_QUERY_ORDER_BY  := :P3120_POST_PROC_ORDER_BY;',
'                        :P3120_QUERY_FUNC_LANG := null;',
'                    elsif :P3120_POST_PROC_TYPE = ''SQL'' then',
'                        :P3120_QUERY_SQL       := :P3120_POST_PROC_SQL;',
'                        :P3120_QUERY_FUNC_LANG := null;',
'                    elsif :P3120_POST_PROC_TYPE = ''FUNC_BODY_RETURNING_SQL'' then',
'                        :P3120_QUERY_SQL       := :P3120_POST_PROC_FUNC_BODY;',
'                        :P3120_QUERY_FUNC_LANG := :P3120_POST_PROC_FUNC_LANG;',
'                    end if;',
'                else',
'                     :P3120_POST_PROC_TYPE  := null;',
'                     :P3120_QUERY_FUNC_LANG := null;',
'                end if;',
'                ',
'                :P3120_POST_PROC_TYPE := nullif ( :P3120_POST_PROC_TYPE, ''NONE'' );',
'                clear_remote_source;',
'',
'            elsif :P3120_LOCATION = ''JSON_COLLECTION'' then',
'    ',
'                :P3120_DOCUMENT_SOURCE_ID   := :P3120_JSON_SOURCE_ID;',
'                :P3120_WEB_SRC_ARRAY_COL_ID := :P3120_JSON_SRC_ARRAY_COL_ID;',
'                ',
'                if :P3120_JSON_POST_TYPE = ''WHERE_ORDER_BY_CLAUSE'' then',
'                    :P3120_QUERY_WHERE     := :P3120_JSON_POST_WHERE;',
'                    :P3120_QUERY_ORDER_BY  := :P3120_JSON_POST_ORDER_BY;',
'                    :P3120_QUERY_FUNC_LANG := null;',
'                elsif :P3120_JSON_POST_TYPE = ''SQL'' then',
'                    :P3120_QUERY_SQL       := :P3120_JSON_POST_SQL;',
'                    :P3120_QUERY_FUNC_LANG := null;',
'                elsif :P3120_JSON_POST_TYPE = ''FUNC_BODY_RETURNING_SQL'' then',
'                    :P3120_QUERY_SQL       := :P3120_JSON_POST_FUNC_BODY;',
'                    :P3120_QUERY_FUNC_LANG := :P3120_JSON_POST_FUNC_LANG;',
'                end if;',
'                ',
'                :P3120_POST_PROC_TYPE := nullif ( :P3120_JSON_POST_TYPE, ''NONE'' );',
'                clear_remote_source;',
'                ',
'                ',
'            elsif :P3120_LOCATION = ''DUALITY_VIEW'' then',
'    ',
'                :P3120_DOCUMENT_SOURCE_ID   := :P3120_DUALITY_VIEW_ID;',
'                :P3120_WEB_SRC_ARRAY_COL_ID := :P3120_DV_ARRAY_COL_ID;',
'                ',
'                if :P3120_DV_POST_TYPE = ''WHERE_ORDER_BY_CLAUSE'' then',
'                    :P3120_QUERY_WHERE     := :P3120_DV_POST_WHERE;',
'                    :P3120_QUERY_ORDER_BY  := :P3120_DV_POST_ORDER_BY;',
'                    :P3120_QUERY_FUNC_LANG := null;',
'                elsif :P3120_DV_POST_TYPE = ''SQL'' then',
'                    :P3120_QUERY_SQL       := :P3120_DV_POST_SQL;',
'                    :P3120_QUERY_FUNC_LANG := null;',
'                elsif :P3120_DV_POST_TYPE = ''FUNC_BODY_RETURNING_SQL'' then',
'                    :P3120_QUERY_SQL       := :P3120_DV_POST_FUNC_BODY;',
'                    :P3120_QUERY_FUNC_LANG := :P3120_DV_POST_FUNC_LANG;',
'                end if;',
'                ',
'                :P3120_POST_PROC_TYPE := nullif ( :P3120_DV_POST_TYPE, ''NONE'' );',
'                clear_remote_source;                ',
'               ',
'            end if;',
'        end if;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(1799745296181261.4004)
,p_internal_uid=>2419821387518826.4004
);
end;
