wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2317449986492645.4004)
,p_name=>'P3505_SQL'
,p_data_type=>'CLOB'
,p_item_sequence=>30
,p_item_plug_id=>wwv_flow_imp.id(2316239026492633.4004)
,p_prompt=>'Query SQL'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cMaxlength=>32767
,p_cHeight=>14
,p_field_template=>wwv_flow_imp.id(561549716994252345.4004)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Specificare la query SQL che genera l''output CSV come contesto per il servizio AI. Nella query \00E8 possibile utilizzare le seguenti bind variable speciali per accedere e valutare il prompt dell''utente:'),
'<dl>',
'    <dt><code>APEX$AI_LAST_USER_PROMPT</code></dt>',
unistr('    <dd>Recupera il prompt pi\00F9 recente immesso dall''utente.</dd>'),
'    <dt><code>APEX$AI_ALL_USER_PROMPTS</code></dt>',
'    <dd>Recupera tutti i prompt dell''utente concatenati in una singola stringa.</dd>',
'</dl>',
'</p>',
unistr('<p>Nota: il numero di righe incluse nell''output sar\00E0 limitato al numero massimo specificato dall''attributo <em>Numero massimo di token</em>, con un limite assoluto di 10.000 righe.</p>'),
'',
'<p>Esempio:</p>',
'<pre>',
'select e.empno as "Employee No",',
'       e.ename as "Employee Name",',
'       e.job   as "Job",',
'       e.sal   as "Salary",',
'       d.dname as "Department"',
'  from emp e',
'  left join dept d on d.deptno = e.deptno',
' order by e.ename',
'fetch first 100 rows only',
'</pre>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'SQL',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
