wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1378952136513217.4004)
,p_name=>'P4001_ORACLE_TEXT_FUNCTION'
,p_item_sequence=>150
,p_item_plug_id=>wwv_flow_imp.id(198116031744061165.4004)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Nome funzione personalizzata'
,p_source=>'ORACLE_TEXT_FUNCTION'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>64
,p_cMaxlength=>500
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Specificare il nome della funzione PL/SQL personalizzata che converte l''input dell''utente finale in una query Oracle Text. ',
'    La funzione acquisisce l''input dell''utente finale come VARCHAR2 e restituisce la query Oracle Text come risultato.</p>',
'<p>',
'    In questo esempio viene utilizzata la tecnica <em>Query Relaxation di Oracle Text</em> (rilassamento query): viene prima eseguita la query esatta,',
unistr('    quindi vengono eseguiti livelli incrementali di <em>ricerca non esatta</em> finch\00E9 non viene restituito il numero di righe'),
unistr('    richiesto. Questa procedura \00E8 completamente trasparente per l''utente finale.'),
'</p>',
'<pre>',
'create or replace function convert_end_user_search (',
'    p_search in varchar2 )',
'    return varchar2 ',
'is',
'    c_xml constant varchar2(32767) := ',
'        ''&lt;query&gt;&lt;textquery>&lt;progression&gt;''          ||',
'          ''&lt;seq&gt;       #SEARCH#            &lt;/seq&gt;'' ||',
'          ''&lt;seq&gt; FUZZY(#SEARCH#,80, 100,W) &lt;/seq&gt;'' ||',
'          ''&lt;seq&gt; FUZZY(#SEARCH#,50,1000,W) &lt;/seq&gt;'' ||',
'          ''&lt;seq&gt; FUZZY(#SEARCH#,20,3000,W) &lt;/seq&gt;'' ||',
'        ''&lt;/progression>&lt;/textquery>&lt;/query&gt;'';',
'',
'    l_search varchar2(32767) := p_search;',
'begin',
'    --',
'    -- rimozione dei caratteri speciali; ',
'    -- questi caratteri non sono rilevanti per la ricerca full-text',
'    --',
'    l_search := regexp_replace(',
'        srcstr  => l_search, ',
'        pattern => ''[&lt;&gt;{}/()*%&!$?.:,;\+#]'' );',
'',
'    return replace( ',
'        srcstr  => c_xml, ',
'        oldsub  => ''#SEARCH#'', ',
'        newsub  => ''{'' || l_search || ''}'' );',
'end;',
'</pre>',
'<p>',
'    Per ulteriori informazioni sulla sintassi di query di Oracle Text e sulla funzione di rilassamento',
'    query, consultare la <a rel="noopener noreferrer" target="_blank" href="https://docs.oracle.com/en/database/oracle/oracle-database/23/ccapp/index.html">Guida per gli sviluppatori di applicazioni Oracle Text</a>.</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
