wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(4603513404.4004)
,p_name=>'F4000_P4008_SCHEME_TYPE'
,p_is_required=>true
,p_item_sequence=>60
,p_item_plug_id=>wwv_flow_imp.id(178678919656730458.4004)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Tipo di schema'
,p_source=>'SCHEME_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'AUTHORIZATION TYPE'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'        select wwv_flow_lang.system_message(''AUTHORIZATION_NAME.''|| name_with_prefix) as d,',
'               name_with_prefix      as r',
'          from wwv_flow_native_plugins',
'         where plugin_type = ''AUTHORIZATION TYPE''',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id           = to_number(:FB_FLOW_ID)',
'           and security_group_id = to_number(:WORKSPACE_ID)',
'           and plugin_type       = ''AUTHORIZATION TYPE''',
'       )',
' order by 1'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- Seleziona un tipo di schema -'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4004)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Selezionare la modalit\00E0 di applicazione di questo schema di autorizzazione. Sono supportati i seguenti tipi built-in:</p>'),
'<ul>',
unistr('<li><strong>Query SQL - Esiste:</strong> uno schema di autorizzazione viene accettato se questo tipo di query restituisce almeno una riga; se invece non viene restituita nessuna riga, lo schema non verr\00E0 accettato.</li>'),
unistr('<li><strong>Query SQL - Non esiste:</strong> uno schema di autorizzazione viene accettato se questo tipo di query non restituisce righe; se invece vengono restituite una o pi\00F9 righe, lo schema non verr\00E0 accettato.</li>'),
unistr('<li><strong>Funzione PL/SQL che restituisce un risultato booleano:</strong> un corpo funzione PL/SQL che restituisce un valore true o false. Nel primo caso, lo schema di autorizzazione viene accettato, mentre non lo sar\00E0 se la funzione restituisce un')
||' valore false.</li>',
unistr('<li><strong>Il valore dell''elemento in Espressione 1 \00E8 NULL:</strong> il valore dell''elemento denominato nell''espressione 1 \00E8 NULL.</li>'),
unistr('<li><strong>Il valore dell''elemento in Espressione 1 \00E8 NOT NULL:</strong> il valore dell''elemento denominato nell''espressione 1 \00E8 NOT NULL.</li>'),
unistr('<li><strong>Il valore della preferenza in Espressione 1 \00E8 uguale a Espressione 2:</strong> il valore della preferenza denominata nell''espressione 1 \00E8 uguale a quello nell''espressione 2.</li>'),
unistr('<li><strong>Il valore della preferenza in Espressione 1 non \00E8 uguale a Espressione 2:</strong> il valore della preferenza denominata nell''espressione 1 non \00E8 uguale a quello nell''espressione 2.</li>'),
unistr('<li><strong>Il valore dell''elemento in Espressione 1 \00E8 uguale a Espressione 2:</strong> il valore dell''elemento denominato nell''espressione 1 \00E8 uguale a quello nell''espressione 2.</li>'),
unistr('<li><strong>Il valore dell''elemento in Espressione 1 non \00E8 uguale a Espressione 2:</strong> il valore dell''elemento denominato nell''espressione 1 non \00E8 uguale a quello nell''espressione 2.</li>'),
unistr('<li><strong>In ruolo o gruppo:</strong> Verifica i ruoli e/o i gruppi separati da virgole specificati rispetto ai ruoli e/o ai gruppi dell''utente per i quali l''origine \00E8 configurata con l''attributo di sicurezza dell''applicazione <strong>Origine per g')
||'li schemi di ruoli o gruppi</strong>.',
unistr('<p>Se l''origine \00E8 impostata su <em>Assegnazioni ruoli utenti di controllo dell''accesso</em>, il processo di autorizzazione prender\00E0 in considerazione solo i ruoli ACL concessi all''utente.</p>'),
unistr('<p>Altrimenti, verificher\00E0 se i gruppi sono abilitati come gruppi dinamici per la sessione (vedere APEX_AUTHORIZATION.ENABLE_DYNAMIC_GROUPS). Se l''applicazione utilizza uno schema di autenticazione configurato con RAS (Real Security Application), que')
||unistr('sto controllo includer\00E0 i ruoli sessione RAS. Se viene utilizzata l''autenticazione degli account Oracle APEX, questo controllo include anche i gruppi dell''area di lavoro concessi all''utente. Se viene utilizzata l''autenticazione del database, questo c')
||'ontrollo include anche i ruoli di database concessi all''utente.</p>',
'<p>Lo schema di autorizzazione viene accettato se all''utente viene concesso uno qualsiasi dei ruoli e/o gruppi designati.</p>',
'</li>',
unistr('<li><strong>Non \00E8 nel gruppo:</strong> il gruppo non \00E8 abilitato o non \00E8 concesso all''utente. Per i dettagli, vedere <strong>\00C8 nel gruppo</strong>.</li>'),
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
