'       list_id,',
'       flow_id,',
'       list_item_display_sequence,',
'       list_item_link_text,',
'       list_item_link_target,',
'       wwv_flow_builder.get_formatted_target( list_item_link_target ) as formatted_target,',
'       list_item_current_type,',
'       list_item_current_for_pages,',
'       list_item_icon,',
'       list_text_01,',
'       list_text_02,',
'       list_text_03,',
'       list_text_04,',
