wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(4627541309.4004)
,p_plug_name=>'Informazioni'
,p_region_template_options=>'#DEFAULT#:a-Region--sideRegion:a-Region--paddedBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4004)
,p_plug_display_sequence=>40
,p_plug_new_grid_row=>false
,p_plug_display_column=>1
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>L''autorizzazione per applicazioni, pagine e la maggior parte degli altri componenti viene gestita con gli schemi di autorizzazione.</p>',
'<p>Uno schema di autorizzazione va associato a un''applicazione, una pagina o un altro componente nella pagina degli attributi del componente.</p>',
unistr('<p>Gli schemi di autorizzazione eseguono verifiche il cui risultato \00E8 di tipo superato/respinto. Alcuni tipi comuni di schemi di autorizzazione comprendono le query SQL con le condizioni Esiste e Non esiste e la funzione PL/SQL che restituisce un ris')
||'ultato booleano.</p>',
'<p>I risultati di completamento o di errore degli schemi di autorizzazione vengono inseriti nella cache per sessione o per vista di pagina, al fine di migliorare le prestazioni.</p>',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">Ulteriori informazioni...</a></p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
