,p_plug_display_column=>1
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>A una lista di valori possono fare riferimento elementi di pagina nonch\00E9 campi di report. Le liste di valori definiscono i valori visualizzati e limitano la possibilit\00E0 di selezione dell''utente. Le liste di valori possono essere statiche, ovvero b')
||'asate sui valori immessi, oppure dinamiche, ovvero basate su origini dati diverse di database locale, SQL abilitato per REST oppure origine dati REST.</p>',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">Ulteriori informazioni...</a></p>'))
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>'nvl(#OWNER#.wwv_flow_preferences.get_preference(''FP_PREF_SHOW_INFORMATION''),''YES'') = ''YES'''
,p_plug_display_when_cond2=>'PLSQL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1548308438182178.4004)
,p_plug_name=>'Liste di valori'
,p_region_template_options=>'#DEFAULT#:a-IRR-region--noOuterBorders:a-IRR-region--responsiveIconView'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209.4004)
,p_plug_display_sequence=>30
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with messages as (',
'    select ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UP_TO_DATE'') from sys.dual ) up_to_date,',
'           ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_NEEDS_REFRESH'') from sys.dual ) needs_refresh,',
'           ( select wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UNKNOWN'') from sys.dual ) unknown_status,',
'           ( select wwv_flow_lang_dev.builder_message(''SUBSCRIBED_FROM.NONEXISTING_MASTER'') from sys.dual ) no_master',
'      from sys.dual )',
'select ''icon-sc-lov'' icon_class,',
'       wwv_flow_utilities.prepare_url(',
'           p_url => ''f?p=4000:4111:''||:app_session||''::NO:4111:F4000_P4111_ID:''||l.ID',
'       ) as edit_link,',
'       replace(replace(l.lov_name,''_'','' ''),''.'','' '') icon_title,',
'       l.ID,',
'       l.flow_id, ',
'       l.lov_name,',
'       case l.location',
'           when ''LOCAL'' then ',
'               case when l.source_type <> ''LEGACY_SQL'' then ',
'                   system_message."LOCAL" ',
'               else ',
'                   system_message."LEGACY_SQL" ',
'               end',
'           when ''REMOTE''          then system_message."REST_ENABLED_SQL"',
'           when ''WEB_SOURCE''      then system_message."WEB_SOURCE"',
'           when ''DUALITY_VIEW''    then system_message."DUALITY_VIEW"',
'           when ''JSON_COLLECTION'' then system_message."JSON_SOURCE"',
'           when ''STATIC''          then system_message."STATIC"',
'       end lov_type,',
'       nvl(l.last_updated_on,l.created_on) LAST_UPDATED_ON,',
'       l.last_updated_by,',
'       decode(substr(l.lov_query,1,1),''.'','''',',
'         decode(substr(upper(l.lov_query),1,6),''STATIC'','''',substr(l.lov_query,1,3500)))',
'       LOV_QUERY,',
'       case when substr(l.lov_query,1,1) = ''.'' then',
'           (select count(*)',
'              from   wwv_flow_list_of_values_data',
'             where  lov_id = l.id and security_group_id = :flow_security_group_id)',
'       end entry_count,',
'       --',
'       case when l.reference_id is not null then',
'           coalesce ( to_char( master.flow_id ),',
'                       messages.no_master )',
'       end as subscribed_from,',
'       ( select case when count(*) > 0 then count(*) end',
'           from wwv_flow_lists_of_values$ sub',
'          where sub.reference_id      = l.id',
'            and sub.security_group_id = :WORKSPACE_ID ) as subscribers,',
'       case when l.reference_id is not null then',
'           case',
'               when master.version_scn = l.version_scn then',
'                   messages.up_to_date',
'               when master.version_scn != l.version_scn then',
'                   messages.needs_refresh',
'               else',
'                   messages.unknown_status',
'           end',
'       end subscription_status,',
'       --',
'       null as actions',
'from   WWV_FLOW_LISTS_OF_VALUES$ l,',
'       WWV_FLOW_LISTS_OF_VALUES$ master,',
'       messages,',
'(select ',
'wwv_flow_lang.system_message(''F4000.STATIC'')                 "STATIC",',
'wwv_flow_lang.system_message(''F4000.LOCAL'')                  "LOCAL",',
'wwv_flow_lang.system_message(''F4000.LEGACY_SQL'')             "LEGACY_SQL",',
'wwv_flow_lang.system_message(''F4000.REST_ENABLED_SQL'')       "REST_ENABLED_SQL",',
'wwv_flow_lang.system_message(''F4000.WEB_SOURCE'')             "WEB_SOURCE",',
'wwv_flow_lang.system_message(''COMPONENT_TYPE.DUALITY_VIEW'')  "DUALITY_VIEW",',
'wwv_flow_lang.system_message(''COMPONENT_TYPE.JSON_SOURCE'')   "JSON_SOURCE"',
'from dual) system_message',
'where l.flow_id                = :FB_FLOW_ID',
'  and l.security_group_id      = :WORKSPACE_ID',
'  and l.reference_id           = master.id (+)',
'  and l.security_group_id      = master.security_group_id (+)'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
