wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(17314311266994460.4004)
,p_name=>'P4303_PROTECTION_LEVEL'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(17312310527965891.4004)
,p_item_source_plug_id=>wwv_flow_imp.id(454431825.4004)
,p_item_default=>'I'
,p_prompt=>'Protezione stato sessione'
,p_source=>'PROTECTION_LEVEL'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'ITEM PROTECTION LEVEL D'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for c1 in (select nvl(PAGE_PROTECTION_ENABLED_Y_N,''N'') p from wwv_flows where id = :FB_FLOW_ID) loop',
'    if c1.p = ''Y'' then',
'       return  ''select wwv_flow_lang.system_message(''''UNRESTRICTED'''') d, ''''N'''' r',
'                  from sys.dual union all',
'                select wwv_flow_lang.system_message(''''CHECKSUM_REQUIRED_APPLICATION'''') d, ''''B'''' r',
'                  from sys.dual union all',
'                select wwv_flow_lang.system_message(''''CHECKSUM_REQUIRED_USER'''') d, ''''P'''' r',
'                  from sys.dual union all               ',
'                select wwv_flow_lang.system_message(''''CHECKSUM_REQUIRED_SESSION'''') d, ''''S'''' r',
'                  from sys.dual union all               ',
'                select wwv_flow_lang.system_message(''''RESTRICTED_NO_SET_FROM_BROWSER'''') d, ''''I'''' r',
'                  from sys.dual'';',
'    else',
'       return  ''select wwv_flow_lang.system_message(''''UNRESTRICTED'''') d, ''''N'''' r',
'                  from sys.dual union all ',
'                select wwv_flow_lang.system_message(''''RESTRICTED_NO_SET_FROM_BROWSER'''') d, ''''I'''' r',
'                  from sys.dual'';',
'    end if;',
'end loop;'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Selezionare la protezione dello stato della sessione per questo elemento:',
'<ul>',
unistr('<li><strong>Non limitato</strong> - L''elemento pu\00F2 essere impostato passando il nome o il valore dell''elemento in un URL o in un form. Non \00E8 richiesto nessun checksum nell''URL.</li><br />       '),
unistr('<li><strong>Limitato: non pu\00F2 essere impostato dal browser</strong> - L''elemento non pu\00F2 essere modificato mediante l''URL o l''istruzione POSTDATA. Utilizzare questa opzione se si desidera limitare il modo in cui il valore di un elemento pu\00F2 essere im')
||unistr('postato sui processi interni, sui calcoli e cos\00EC via. Questo attributo, valido solo per gli elementi che non possono essere utilizzati come elementi di voci di dati, viene sempre rispettato, anche se l''opzione Protezione stato sessione \00E8 disabilitata')
||unistr('. Questo attributo pu\00F2 essere utilizzato per elementi di applicazione o di pagina che hanno uno qualsiasi dei seguenti tipi di visualizzazione:'),
'<br />',
'<ul>',
'<li>Solo visualizzazione (non salva lo stato)</li>   ',
'<li>Campo di testo (disabilitato, non salva lo stato)</li>                          ',
'<li>Arresta e avvia layout griglia (visualizza solo l''etichetta)</li>',
'</li></ul>',
unistr('<li><strong>Checksum obbligatorio: a livello di applicazione</strong> - L''elemento pu\00F2 essere impostato passando il nome o il valore dell''elemento in un URL se viene fornito anche un checksum specifico per l''area di lavoro e l''applicazione. Utilizzar')
||'e questa opzione per consentire l''impostazione dell''elemento solo da parte di URL che hanno checksum generati da un qualsiasi utente che esegue la stessa applicazione nella medesima area di lavoro ma in una sessione diversa.</li>',
unistr('<li><strong>Checksum obbligatorio: a livello di utente</strong> - L''elemento pu\00F2 essere impostato passando il nome o il valore dell''elemento in un URL se viene fornito anche un checksum specifico per l''area di lavoro, l''applicazione e l''utente. Utili')
||'zzare questa opzione per consentire l''impostazione dell''elemento solo da parte di URL che hanno checksum generati dal medesimo utente denominato che esegue la stessa applicazione nell''area di lavoro corrente ma in una sessione diversa.</li>      ',
unistr('<li><strong>Checksum obbligatorio: a livello di sessione</strong> - L''elemento pu\00F2 essere impostato passando il nome o il valore dell''elemento in un URL se viene fornito anche un checksum specifico per la sessione corrente. Utilizzare questa opzione ')
||'per consentire l''impostazione dell''elemento solo da parte di URL che hanno checksum generati nella sessione corrente.</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
