'                       and id                = :F4000_P4308_ID ) )',
'loop',
'    wwv_flow_dml.process(',
'    p_action      => wwv_flow.g_request,',
'    p_table_owner => ''#OWNER#'',',
'    p_table_name  => ''WWV_FLOW_ICON_BAR'',',
'    p_rowid       => v(''F4000_P4308_ID''),',
'    p_alt_rowid   => ''ID'');',
'    exit;',
'end loop;',
'commit;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Errore durante l''elaborazione della riga.'
,p_process_success_message=>'Azione elaborata.'
