,p_plug_display_sequence=>220
,p_plug_display_point=>'REGION_POSITION_05'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
unistr('    <li>Se il componente del modello viene utilizzato in un''area e visualizzato come modello parziale, &PRODUCT_NAME. visualizzer\00E0 solo gli slot all''interno del modello parziale. Pertanto, non potr\00E0 essere aggiornato in modo dinamico n\00E9 sottoposto a ')
||'caricamento lento.</li>',
unistr('    <li>Se il componente del modello viene utilizzato in un''area e visualizzato come report, &PRODUCT_NAME. visualizzer\00E0 solo gli slot all''interno del modello di contenitore del report, associato al modello del corpo del report.</li>'),
unistr('    <li>Non \00E8 possibile visualizzare gli slot nelle righe del report o nelle colonne del report interattivo poich\00E9 il contenuto degli slot non \00E8 progettato per essere ripetuto nella visualizzazione della pagina.</li>'),
unistr('    <li>\00C8 possible verificare se il contenuto dello slot esiste, in modo da consentire a Oracle di visualizzare markup aggiuntivo solo se lo slot viene utilizzato. Esempio:'),
'        <pre><code>',
'            &lt;div class="outer-div"&gt;',
'            {if SLOT_A/}',
'            &lt;div class="inner-div"&gt;#SLOT_A#&lt;/div&gt;',
'            {endif/}',
'            &lt;/div&gt;',
'        </code></pre>',
'    </li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
