wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(20527901230873212.4004)
,p_name=>'P4410_SUBSTITUTE_ATTRIBUTES'
,p_item_sequence=>340
,p_item_plug_id=>wwv_flow_imp.id(48467930491898431.4004)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>'Sostituisci valori attributo'
,p_source=>'SUBSTITUTE_ATTRIBUTES'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_YES_NO'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>I valori dell''attributo personalizzato specificati dallo sviluppatore possono contenere elementi cui viene fatto riferimento mediante una sintassi di sostituzione, ad esempio <code>&amp;P1_DNAME.</code>',
'</p>',
unistr('<p>Se Sostituisci valori attributo \00E8 impostato su <strong>Attivo</strong>, &PRODUCT_NAME. sostituisce automaticamente tali riferimenti con il relativo valore effettivo prima di richiamare il plugin.'),
'</p>',
unistr('<p>Se Sostituisci valori attributo \00E8 impostato su <strong>Non attivo</strong>, i valori vengono riportati invariati negli attributi del tipo di record <code>attribute_01 - attribute_25</code> di <code>p_plugin, p_item, p_region, ...</code> ed \00E8 respo')
||unistr('nsabilit\00E0 dello sviluppatore del plugin sostituire tali riferimenti di sintassi di sostituzione con una chiamata a <code>apex_plugin_util.replace_substitutions</code> oppure effettuare sostituzioni simili.'),
'</p>',
unistr('<p>Un caso in cui utilizzare l''impostazione <strong>Non attivo</strong> \00E8 quando l''attributo di plugin personalizzato viene utilizzato come modello e la sintassi di sostituzione viene impiegata per fare riferimento agli elementi e alle colonne di pag')
||unistr('ina dell''istruzione SQL eseguita dal plugin. Poich\00E9 i valori di colonna dell''istruzione SQL non sono disponibili quando il plugin viene richiamato, la sostituzione deve essere effettuata dal plugin stesso.'),
'</p>',
'<p>Esempio per sostituire manualmente i valori di colonna per ogni riga:</p>',
'<pre>',
'/* Read data */',
'l_column_value_list := apex_plugin_util.get_data2 (',
'                           p_sql_statement => p_region.source,',
'                           p_region        => p_region );',
'/* Emit rows */',
'for l_row_num in 1 .. l_column_value_list( 1 ).value_list.count loop',
'    begin',
'        -- Assegnare i valori di colonna della riga corrente',
'        -- nello stato sessione',
'        apex_plugin_util.set_component_values (',
'            p_column_value_list => l_column_value_list,',
'            p_row_num           => l_row_num );',
'',
'        ...',
'',
'        -- Attributo di collegamento: sostituire le variabili di sostituzione',
'        -- (compresi i valori di colonna della riga corrente)',
'        l_link := apex_plugin_util.replace_substitutions(',
'                      p_value => p_region.attribute_01 );',
'        ...',
'',
'        apex_plugin_util.clear_component_values;',
'    exception when others then',
'        apex_plugin_util.clear_component_values;',
'        raise;',
'    end;',
'end loop;',
'</pre>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
