wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(439396713209952288.4004)
,p_name=>'P4410_REGION_ATTRIBUTES'
,p_item_sequence=>260
,p_item_plug_id=>wwv_flow_imp.id(439386704233826730.4004)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Attributi:'
,p_source=>'P4410_STANDARD_ATTRIBUTES'
,p_source_type=>'ITEM'
,p_display_as=>'NATIVE_CHECKBOX'
,p_named_lov=>'PLUGIN.REGION_ATTRIBUTES'
,p_lov=>'.'||wwv_flow_imp.id(439394121736945367)||'.'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'Per i plugin di tipo area, selezionare quanto segue per abilitare le opzioni come descritto di seguito.',
'</p>',
'<p>',
'<ul>',
unistr('<li>L''origine area \00E8 un''istruzione SQL: l''origine dell''area \00E8 un''istruzione SQL. Quando questo attributo \00E8 selezionato, \00E8 possibile specificare il numero minimo e il numero massimo di colonne che la query pu\00F2 restituire vengono visualizzati esempi di')
||' codice SQL per assistere l''utente.</li>',
unistr('<li>L''origine area \00E8 in testo non codificato: l''origine dell''area \00E8 testo non codificato.</li>'),
unistr('<li>Origine area obbligatoria: se l''origine dell''area \00E8 un''istruzione SQL, questo attributo fa del valore un valore obbligatorio.</li>'),
unistr('<li>Con attributo "Elementi pagina da sottomettere": se l''origine dell''area \00E8 un''istruzione SQL, questo attributo consente di specificare gli elementi di pagina da impostare nello stato della sessione durante l''esecuzione di una chiamata Ajax per l''a')
||'rea interessata.</li>',
'<li>Con attributo "Numero di righe recuperate": l''area contiene i campi Numero di righe recuperate nella sezione Avanzate quando viene modificata.</li>',
'<li>Con attributo "Messaggio Nessun dato trovato": l''area contiene il campo Messaggio Nessun dato trovato nella sezione Avanzate quando viene modificata.</li>',
'<li>Con attributo "Caratteri speciali di escape": l''area contiene il campo Caratteri speciali di escape nella sezione Sicurezza quando viene modificata.</li>',
'<li>Con "Colonne aree": l''area consente di specificare altri attributi personalizzati per ogni colonna dell''istruzione SQL dell''origine area.</li>',
'<li>Con attributo colonna "Intestazione": le colonne dell''area hanno il campo Intestazione nella sezione Intestazione quando la colonna viene modificata.</li>',
'<li>Con attributo colonna "Allineamento intestazione": le colonne dell''area hanno il campo Allineamento nella sezione Intestazione quando la colonna viene modificata.</li>',
'<li>Con attributo colonna "Allineamento": le colonne dell''area hanno il campo Allineamento colonna nella sezione Layout quando la colonna viene modificata.</li>',
'<li>Con attributo colonna "Classi CSS": le colonne dell''area hanno il campo Classi CSS nella sezione Aspetto quando la colonna viene modificata.</li>',
'<li>Con attributo colonna "Attributi personalizzati": le colonne dell''area hanno il campo Attributi personalizzati nella sezione Avanzate quando la colonna viene modificata.</li>',
'<li>Con attributo colonna "Caratteri speciali di escape": le colonne dell''area hanno il campo Caratteri speciali di escape nella sezione Sicurezza quando la colonna viene modificata.</li>',
unistr('<li>Con attributo "Codice JavaScript di inizializzazione": il campo Codice JavaScript di inizializzazione \00E8 disponibile per l''azione.</li>'),
unistr('<li>Supporta Ricerca con facet/Filtri intelligenti: l''area pu\00F2 essere connessa a un''area Ricerca con facet o Filtri intelligenti. La selezione dell''opzione "L''origine area \00E8 un''istruzione SQL" \00E8 obbligatoria.</li>'),
'</ul>',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'number_of_columns', '1')).to_clob
