unistr('  <li>Riferimento file standard che carica il file ridotto main.min.css da #PLUGIN_FILES#minified/ per le visualizzazioni di pagina normali e il file main.css da #PLUGIN_FILES# in modalit\00E0 di debug.'),
'      <pre>#PLUGIN_FILES##MIN_DIRECTORY#main#MIN#.css</pre>',
'  </li>',
'  <li>Query supporto condizionale',
'      <pre>[media="solo schermo e (max-device-width: 480px)"]#PLUGIN_FILES#smartphone.css</pre>',
'  </li>',
'</ul>',
'</p>'))
