wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1587735358919175023.4004)
,p_name=>'P4410_META_DATA_FUNCTION'
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(27935931959010930.4004)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Nome procedura metadati'
,p_source=>'META_DATA_FUNCTION'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>64
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Immettere il nome della procedura PL/SQL da chiamare per ottenere i metadati dinamici relativi al plugin. Il nome pu\00F2 fare riferimento a una procedura del blocco di codice PL/SQL anonimo, una procedura package o una procedura standalone nel databa')
||'se. Ad esempio:',
'<pre>',
'meta_data_slider',
'</pre></p>',
'',
unistr('<p>Quando si fa riferimento a una procedura package o standalone PL/SQL del database, \00E8 possibile usare la stringa di sostituzione <code>#OWNER#</code> per fare riferimento allo schema di analisi dell''applicazione corrente. Ad esempio:'),
'<pre>',
'#OWNER#.meta_data_slider',
'</pre></p>',
'',
'<p>Le procedure dei metadati del plugin per il tipo di elemento devono implementare l''interfaccia seguente:',
'',
'<pre>',
'procedure &lt;nome della procedura&gt; (',
'    p_item   in            apex_plugin.t_item,',
'    p_plugin in            apex_plugin.t_plugin,',
'    p_param  in            apex_plugin.t_item_meta_data_param,',
'    p_result in out nocopy apex_plugin.t_item_meta_data_result )',
'</pre>',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'NONE')).to_clob
);
