'    and instr( nvl( :P4410_TEMPLATE_COMP_ATTRIBUTES, ''x'' ), ''ROW_SELECTION'' ) = 0',
'  then',
'    case when :P4410_TEMPLATE_COMP_ATTRIBUTES is not null then '':'' end || ''ROW_SELECTION''',
'end'))
,p_compute_when=>'P4410_PLUGIN_TYPE'
