,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'const componentType = apex.item( "P4410_TMPL_COMPONENT_TYPES" ).getValue();',
'const isRegionOnly = componentType.includes( "REGION_ONLY" ); ',
'const standardAttributes$ = $( "#P4410_TEMPLATE_COMP_ATTRIBUTES" );',
'// options to disable in region-only mode',
'const elements$ = standardAttributes$.find( "input[value=ROW_SELECTION], input[value=REGION_TEMPLATE]" );',
'',
'elements$.each( function() { ',
'    $( this ).prop( {',
'      disabled: isRegionOnly,',
'      checked: isRegionOnly ? false : $( this ).prop( "checked" )',
'    } );',
'} );',
''))
);
