,p_computation_point=>'BEFORE_HEADER'
,p_computation_type=>'QUERY'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select p.plugin_type',
'  from wwv_flow_plugins p',
' where p.security_group_id in ( :WORKSPACE_ID, 11, 12 )',
'   and ( (      :P4415_PLUGIN_ID is not null ',
'            and p.id = :P4415_PLUGIN_ID )',
'        or (    :P4415_ID is not null ',
'            and exists ( select 1',
'                       from wwv_flow_plugin_attributes a',
'                      where a.security_group_id = p.security_group_id',
'                        and a.plugin_id         = p.id',
'                        and a.id                = :P4415_ID ) ) )'))
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(13739400846552942.4004)
,p_validation_name=>'P4415_ATTRIBUTE_SEQUENCE max attribute check'
,p_validation_sequence=>210
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_plugin_type       wwv_flow_plugins.plugin_type%type;',
'    l_max_attribute_seq number;',
'begin',
'    select plugin_type',
'      into l_plugin_type',
'      from wwv_flow_plugins',
'     where id                = :P4415_PLUGIN_ID',
'       and flow_id           = :P4415_FLOW_ID',
'       and security_group_id = :WORKSPACE_ID;',
'',
'    l_max_attribute_seq := wwv_flow_plugin_dev.get_max_custom_attributes (',
'                               p_plugin_type     => l_plugin_type,',
'                               p_attribute_scope => :P4415_ATTRIBUTE_SCOPE );',
'',
'    if to_number(:P4415_ATTRIBUTE_SEQUENCE) not between 1 and l_max_attribute_seq then',
'        return wwv_flow_lang.system_message(''APEX.NUMBER_FIELD.VALUE_NOT_BETWEEN_MIN_MAX'', 1, l_max_attribute_seq);',
'    end if;',
'',
'    return null;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_validation_condition_type=>'IS_NOT_READ_ONLY'
,p_associated_item=>wwv_flow_imp.id(48408925689213174.4004)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
