,p_process_sequence=>60
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Derive P4446_IS_NATIVE_PLUGIN'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    select ''Y'' is_native_plugin',
'      into :P4446_IS_NATIVE_PLUGIN',
'      from wwv_flow_plugin_settings s,',
'           wwv_flow_native_plugins p',
'     where s.flow_id           = :FB_FLOW_ID',
'       and s.security_group_id = :WORKSPACE_ID',
'       and p.plugin_type       = s.plugin_type',
'       and p.name_with_prefix  = s.plugin',
'       and s.id                = :P4446_ID;',
'exception',
'    when no_data_found then',
'        :P4446_IS_NATIVE_PLUGIN := ''N'';',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>3629771551310643.4004
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2522748213409114.4004)
,p_process_sequence=>70
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Derive P4446_PLUGIN_ID'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'--',
'-- no need to handle no_data_found exception',
'-- row should exist for Plug-in Components and',
'-- same server side condition used for this process',
'--',
'select id',
'  into :P4446_PLUGIN_ID',
'  from wwv_flow_plugins',
' where plugin_type       = :P4446_PLUGIN_TYPE',
'   and ''PLUGIN_'' || name = :P4446_PLUGIN',
'   and flow_id           = :FB_FLOW_ID',
'   and security_group_id = :WORKSPACE_ID;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P4446_IS_NATIVE_PLUGIN'
,p_process_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_process_when2=>'N'
,p_internal_uid=>2522748213409114.4004
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(43412037816937304.4004)
,p_process_sequence=>80
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Init Subscription Info Text'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    select f.id||'' - ''||f.name,',
'           wwv_flow_page_api.get_url(',
'                p_application => 4000,',
'                p_page        => 4446,',
'                p_clear_cache => ''4446'',',
'                p_items       => ''FB_FLOW_ID,P4446_ID'',',
'                p_values      => ps.flow_id||'',''||ps.id)',
'      into :P4446_MASTER_APP,',
'           :P4446_MASTER_APP_EDIT_LINK',
'      from wwv_flow_plugin_settings ps,',
'           wwv_flows f      ',
'     where f.id                  = ps.flow_id',
'       and f.security_group_id   = ps.security_group_id',
'       and ps.security_group_id  = :WORKSPACE_ID',
'       and ps.id                 = :P4446_REFERENCE_ID;',
'exception',
'    when no_data_found then',
'        :P4446_MASTER_APP           := null;',
'        :P4446_MASTER_APP_EDIT_LINK := null;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>':P4446_IS_NATIVE_PLUGIN = ''N'' and :P4446_REFERENCE_ID is not null'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>43412037816937304.4004
);
end;
