,p_name=>'P4450_ACTION'
,p_item_sequence=>135
,p_item_plug_id=>wwv_flow_imp.id(30497027132469156.4004)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Azione'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_name varchar2( 32767 ) := :P4450_NAME;',
'begin',
'',
'    if :P4450_NEW_THEME_ID is not null then',
'        l_name := wwv_flow_template_directive.get_name (',
'                     p_name                 => l_name,',
'                     p_theme_id             => :P4450_NEW_THEME_ID,',
'                     p_for_using_component  => false );',
'    end if;',
'',
'    -- does the plugin already exist?',
'    for c1 in (',
'        select 1 dummy',
'          from wwv_flow_plugins',
'         where flow_id           = to_number(:P4450_NEW_FLOW_ID)',
'           and security_group_id = to_number(:WORKSPACE_ID)',
'           and plugin_type       = :P4450_PLUGIN_TYPE',
'           and name              = l_name',
'           and (   :P4450_NEW_THEME_ID is null',
'                or theme_id = to_number(:P4450_NEW_THEME_ID) ) )',
'    loop',
'        return wwv_flow_lang.system_message(''F4000.P4450.ACTION_REPLACE'', :P4450_NEW_FLOW_ID);',
'    end loop;',
'',
'    -- doesn''t exist yet',
'    return wwv_flow_lang.system_message(''F4000.P4450.ACTION_CREATE'', :P4450_NEW_FLOW_ID);',
'exception',
'    when others then',
'        raise_application_error(-20001, :P4450_NEW_THEME_ID );',
'end;'))
,p_source_type=>'FUNCTION_BODY'
,p_source_language=>'PLSQL'
,p_display_as=>'NATIVE_DISPLAY_ONLY'
,p_tag_css_classes=>'fielddatabold'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>'Azione eseguita quando si fa clic sul pulsante "Installa plugin".'
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'based_on', 'VALUE',
  'format', 'PLAIN',
  'send_on_page_submit', 'Y',
