'<div class="htmldbInfoBodyP">I modelli di area determinano l''aspetto della parte della pagina denominata area. Utilizzare le stringhe di sostituzione per indicare l''esistenza e la posizione di un componente all''interno dell''area.</div>',
unistr('<div class="htmldbInfoBodyP">#BODY# \00E8 l''unica stringa di sostituzione obbligatoria. Identifica in che punto deve essere posizionata l''origine dell''area. Tutte le altre stringhe di sostituzione sono facoltative.</div>'),
'<div class="htmldbInfoBodyP">Di seguito sono riportate le stringhe di sostituzione valide:',
'<ul class="noIndent">',
'<li>#TITLE#</li>',
'<li>#PAGE_TITLE#</li>',
'<li>#EXPAND#</li>',
'<li>#CHANGE#</li>',
'<li>#BODY#</li>',
'<li>#SUB_REGION_HEADERS#</li>',
'<li>#SUB_REGIONS#</li>',
'<li>#FORM_OPEN#</li> ',
'<li>#FORM_CLOSE#</li>',
'<li>#REGION_ID#</li>',
'<li>#REGION_STATIC_ID#</li>',
'<li>#REGION_CSS_CLASSES#</li>',
'<li>#REGION_ATTRIBUTES#</li>',
'<li>#REGION_HEADER#</li>',
'<li>#REGION_FOOTER#</li>',
'<li>#REGION_IMAGE#</li>',
'<li>#REGION_IMAGE_URL#</li>',
'<li>#REGION_IMAGE_ALT_TEXT#</li>',
'<li>#REGION_IMAGE_ATTRIBUTES#</li>',
'<li>#REGION_LANDMARK_ATTRIBUTES#</li>',
'</ul>',
'</div>',
unistr('<div class="htmldbInfoBodyP">\00C8 inoltre possibile utilizzare le stringhe di sostituzione seguenti per specificare gli slot dei pulsanti all''interno di questa area:</div>'),
'<ul class="noIndent">',
'<li>#EDIT#</li>',
'<li>#CLOSE#</li>',
'<li>#CREATE#</li>',
'<li>#CREATE2#</li>',
'<li>#EXPAND#</li>',
'<li>#HELP#</li>',
'<li>#DELETE#</li>',
'<li>#COPY#</li>',
'<li>#NEXT#</li>',
'<li>#PREVIOUS#</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
