,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select o.template_types,',
'       o.id,',
'       o.display_name,',
'       o.name,',
'       o.display_sequence,',
'       o.css_classes,',
'       o.flow_id,',
'       o.theme_id,',
'       o.help_text,',
'       o.group_id,',
'       o.list_template_id,',
'       ( select g.display_sequence from wwv_flow_template_opt_groups g where g.id = o.group_id and g.security_group_id = o.security_group_id ) group_display_sequence,',
'       ( select g.display_name     from wwv_flow_template_opt_groups g where g.id = o.group_id and g.security_group_id = o.security_group_id ) group_display_name',
'  from wwv_flow_template_options o',
' where o.template_types    = ''LIST''',
'   and o.list_template_id  = :F4000_P4655_ID',
'   and o.security_group_id in ( :WORKSPACE_ID, 11, 12 )'))
