,p_name=>'P4900_ORIGINAL_IDS'
,p_item_sequence=>150
,p_item_plug_id=>wwv_flow_imp.id(486282025733641382.4004)
,p_item_default=>'N'
,p_prompt=>'ID originali'
,p_display_as=>'NATIVE_YES_NO'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Specificare se il file di esportazione deve contenere gli ID dei componenti dell''applicazione dalla data odierna o dall''ultima importazione di questa applicazione. Le opzioni disponibili includono:',
'<p />',
'<ul>',
'<li><strong>Attivo</strong> include gli ID dall''ultima importazione.</li>',
'<li><strong>Non attivo</strong> include gli ID correnti dei componenti.</li>',
'</ul>',
'<p />',
'<p />',
unistr('L''utilizzo degli ID originali pu\00F2 risultare vantaggioso per vari scopi, tra cui:'),
'<p />',
'<ul>',
unistr('<li><strong>Formato leggibile:</strong> consente di semplificare i confronti tra le diverse versioni dei componenti e delle pagine dell''applicazione, nonch\00E9 di ridurre al minimo le modifiche ai file di esportazione con controllo delle versioni.</li>'),
'<li><strong>Sottoscrizioni componenti condivisi:</strong> garantiscono che i componenti sottoscritti rimangano collegati a un''applicazione di origine quando viene sostituita con una versione aggiornata.</li>',
'</ul>',
'<p />'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
