,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="htmldbInfoBodyP">Specificare un''ora espressa in minuti a cui fare riferimento per l''esportazione. Questa opzione consente di andare a ritroso nel tempo a livello di applicazione, ad esempio per recuperare un oggetto eliminato.</div>',
'',
unistr('<div class="htmldbInfoBodyP">Questa utility utilizza il package <code>dbms_flashback</code>. L''indicatore orario del mapping SCN (System Change Number) viene aggiornato approssimativamente ogni 5 minuti. Sar\00E0 pertanto necessario attendere questo inte')
||unistr('rvallo di tempo per ottenere la versione desiderata. Il periodo di tempo durante il quale le informazioni di undo sono conservate \00E8 controllato dal parametro di avvio <code>undo_retention</code> (impostazione predefinita: 3 ore), ma interessa solo le')
||' dimensioni della tablespace di undo.</div>',
unistr('<div class="htmldbInfoBodyP">Anche se due database possono avere lo stesso parametro <code>undo_retention</code>, sar\00E0 possibile andare pi\00F9 a ritroso nel tempo nel database contenente il numero minore di transazioni in quanto non occupa l''intera tabl')
||unistr('espace di undo, situazione che forzerebbe l''archiviazione dei dati pi\00F9 vecchi.</div>')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'NONE')).to_clob
);
