,p_protection_level=>'C'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3185079872144510.4004)
,p_plug_name=>'Informazioni sulle copie di lavoro'
,p_region_css_classes=>'padding-left-md padding-right-md'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--noBorder:a-Region--hideHeader'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4004)
,p_plug_display_sequence=>10
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h3>Suggerimenti</h3>',
'<ul>',
'    <li>Gli sviluppatori possono utilizzare copie di lavoro distinte. Per evitare sovrascritture o errori durante l''unione:',
'        <ul>',
'            <li>Bloccare una pagina nell''applicazione principale prima di modificarla in una copia di lavoro.</li>',
'            <li>Riservare gli intervalli di pagina per le nuove pagine che verranno create da ogni sviluppatore.</li>',
'            <li>Accettare i nomi dei componenti condivisi che verranno aggiunti da ogni sviluppatore.</li>',
'        </ul>',
'    </li>',
'    <li>Esportare una copia di lavoro in base alle esigenze utilizzando gli <em>ID originali</em> per mantenere il collegamento corrispondente con l''applicazione principale.</li>',
'    <li><em>Scollegare</em> una copia di lavoro dall''applicazione principale utilizzando il task <em>Copia applicazione</em>.</li>',
'    <li>Eliminare eventuali copie di lavoro <em>prima</em> di eliminare un''applicazione.</li>',
'</ul>',
'<h3>Tipi di componenti non supportati</h3>',
'<p>Questi tipi di componenti non sono ancora supportati per l''unione <em>automatica</em>:',
unistr('   traduzioni, temi, modelli di temi, oggetti di supporto, propriet\00E0 applicazione, schede (precedenti) e'),
unistr('   componenti a livello di area di lavoro, ad esempio gruppi di applicazioni, credenziali o server remoti. \00C8 possibile unire la copia di lavoro,'),
'   quindi applicare manualmente le aggiunte o le modifiche apportate a questi tipi di componenti.',
'</p>',
'<h3>Limitazioni</h3>',
'<p>Le copie di lavoro presentano le limitazioni riportate di seguito.</p>',
'<ul>',
unistr('    <li>Non \00E8 possibile creare una copia di lavoro di una copia di lavoro.</li>'),
'    <li>Le pagine o i componenti condivisi della copia di lavoro eliminata devono essere eliminati <em>manualmente</em> nell''applicazione principale.</li>',
'    <li>I componenti elencati come <em>mancanti</em> potrebbero essere stati rimossi nella copia di lavoro o potrebbero esistere solo nell''applicazione principale.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
