,p_process_name=>'Initialize Hidden Items'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'',
'    select to_char( last_updated_on, ''YYYY.MM.DD HH24:MI:SS'' ), ',
'           last_updated_by, ',
'           decode( ',
'               last_updated_on, ',
'               null, ''u-hidden'' )',
'      into :P5335_LEFT_UPDATED_ON, ',
'           :P5335_LEFT_UPDATED_BY, ',
'           :P5335_LEFT_UPDATED_DISP_CLS',
'      from wwv_flow_steps',
'     where flow_id            = :FB_FLOW_ID',
'       and id                 = :P5335_EXPORT_PAGE_ID',
'       and security_group_id  = :WORKSPACE_ID;',
'',
'    select to_char( last_updated_on, ''YYYY.MM.DD HH24:MI:SS'' ), ',
'           last_updated_by, ',
'           decode( ',
'               last_updated_on, ',
'               null, ''u-hidden'' )',
'      into :P5335_RIGHT_UPDATED_ON, ',
'           :P5335_RIGHT_UPDATED_BY, ',
'           :P5335_RIGHT_UPDATED_DISP_CLS',
'      from wwv_flow_steps',
'     where flow_id            = :P5335_RIGHT_ID',
'       and id                 = :P5335_EXPORT_PAGE_ID',
'       and security_group_id  = :WORKSPACE_ID;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select null',
'  from wwv_flow_steps ',
' where id                = :P5335_EXPORT_PAGE_ID ',
'   and flow_id           = :P5335_RIGHT_ID',
'   and security_group_id = :WORKSPACE_ID'))
,p_process_when_type=>'EXISTS'
,p_internal_uid=>2022120273029213.4004
);
end;
