,p_plug_display_sequence=>40
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select s.id,',
'       s.component_type,',
'       ( select c.name',
'           from wwv_flow_appl_export_comps c',
'          where c.workspace_id   = :WORKSPACE_ID',
'            and c.application_id = :FB_FLOW_ID',
'            and c.type_name      = s.component_type',
