'select s.component_type,',
'       ( select name',
'           from wwv_flow_appl_export_comps c',
'          where c.workspace_id   = :WORKSPACE_ID',
'            and c.application_id = :P6202_COPY_FROM_APP_ID',
'            and c.type_name      = s.component_type',
'            and c.id             = s.from_component_id ) component,',
'       s.matching_status,',
'       wwv_flow_lang.message(''COMP_GRP.MATCHING_STATUS.''||s.matching_status) matching_status_display,',
'       case s.matching_status',
'           when ''FOUND'' then ''danger''',
'           when ''NEEDS_REFRESH'' then ''warning''',
'           when ''NOT_FOUND'' then ''success''',
'           when ''UP_TO_DATE'' then ''info''',
'       end badge_state',
'  from wwv_flow_component_group_dev.compare (',
'           p_from_component_group_id => :P6202_ID,',
'           p_from_app_id             => :P6202_COPY_FROM_APP_ID,',
'           p_to_app_id               => :FB_FLOW_ID ) s',
' order by ',
'       case s.matching_status',
'           when ''FOUND'' then 1',
'           when ''NEEDS_REFRESH'' then 2',
'           when ''NOT_FOUND'' then 3',
'           when ''UP_TO_DATE'' then 4',
'       end,',
'       s.component_type'))
