||'1_JSPOST_ORDERBY,#P7021_JSPOST_QUERY,#P7021_JSPOST_FUNC_BODY_LANG,#P7021_JSPOST_FUNC_BODY,#P7021_DUALITY_VIEW_ID,#P7021_DVSRC_ARRAYCOL_ID,#P7021_DVPOST,#P7021_DVPOST_WHERE,#P7021_DVPOST_ORDERBY,#P7021_DVPOST_QUERY,#P7021_DVPOST_FUNC_BODY_LANG,#P7021_'
||'DVPOST_FUNC_BODY" },',
'        {',
'            success: function( pData ) {',
'                var lItems = apex.jQuery( ".is-column");',
'',
'                //-----------------------------------------------------------------------------------------',
'                function refreshItem( pItem$, pSetValue ) {',
'                    var lValue           = apex.item( pItem$.attr( "name" ) ).getValue(),',
'                        lValueStillValid = false,',
'                        lNullOption$     = pItem$.find( ''option[value=""]''),',
'                        lOption$;',
'',
'                    pItem$.empty();',
'                    if ( lNullOption$.length > 0 ) {',
'                        pItem$.append( lNullOption$ );',
'                    }',
'                    ',
'                    for ( let o = 0; o < pData.length; o++ ) {',
'                        if (    pData[ o ].t === "NUMBER" ',
'                                || pData[ o ].t === "VARCHAR2" ',
'                                || pData[ o ].t === "DATE" ',
'                                || pData[ o ].t === "TIMESTAMP"  )',
'                        {',
'                            lOption$ = apex.jQuery("<option></option>").attr("value", pData[ o ].r ).text( pData[ o ].d );',
'                            if ( pData[ o ].r === lValue ) {',
'                                lValueStillValid = true;',
'                            }',
'                            pItem$.append( lOption$ );',
'                        }',
'                    }',
'',
'                    if ( pSetValue ) {',
'                        if ( lValueStillValid ) {',
'                            apex.item( pItem$.attr( "name" ) ).setValue( lValue );',
'                        } else {',
'                            apex.item( pItem$.attr( "name" ) ).setValue( "" );',
'                        }',
'                    }',
'                }',
'',
'                if ( pData.length > 0 ) {',
'                    for (let i=0; i<lItems.length;i++) {',
'                        refreshItem( apex.jQuery (lItems[ i ] ), true );',
'                    }',
'                }',
'            }',
'        }',
'    );',
'}',
'',
''))
