,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(1410170163910728.4004)
,p_item_source_plug_id=>wwv_flow_imp.id(1410170163910728.4004)
,p_item_default=>'NATIVE_PLSQL'
,p_prompt=>'Tipo'
,p_source=>'ACTION_TYPE'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'         select wwv_flow_lang.system_message(''PROCESS.''|| name_with_prefix) as d,',
'               name_with_prefix as r',
'          from wwv_flow_native_plugins',
'         where plugin_type               = ''PROCESS TYPE''',
'           and supported_component_types like ''%APEX_APPL_AUTOMATION_ACTIONS%''',
'           and ( ( select wwv_flow_f4000_util.is_cloud',
'                     from sys.dual ) = ''Y''',
'                  or name != ''GEOCODING'' )',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id                   = to_number(:FB_FLOW_ID)',
'           and security_group_id         = to_number(:WORKSPACE_ID)',
'           and plugin_type               = ''PROCESS TYPE''',
'           and supported_component_types like ''%APEX_APPL_AUTOMATION_ACTIONS%''',
'       )',
' order by 1'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4004)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_help_text=>'Selezionare il tipo di azione.'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1409543908910722.4004)
,p_name=>'P7022_REMOTE_PLSQL_CODE'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(90116067165448609.4004)
,p_prompt=>'Codice PL/SQL (eseguito nel servizio SQL abilitato per REST)'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>80
,p_cMaxlength=>32767
,p_cHeight=>10
,p_field_template=>wwv_flow_imp.id(561549638722251517.4004)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Fornire il codice PL/SQL da eseguire. I valori di colonna recuperati dalla query di automazione sono disponibili come bind variable, in base al nome di colonna, ad esempio <strong>:EMPNO</strong>, <strong>:ENAME</strong> e cos\00EC via. Inoltre, APEX')
||' fornisce le bind variable generiche seguenti:',
'</p>',
'<ul>',
unistr('    <li><strong>APEX$AUTOMATION_ROW_PK</strong>: se \00E8 stata definita una colonna chiave primaria, questa bind variable contiene il valore di chiave primaria.</li>'),
'    <li><strong>APEX$AUTOMATION_ROW_NUM</strong>: per le automazioni basate su una query, questa bind variable contiene il numero di riga corrente.</li>',
'    <li><strong>APEX$AUTOMATION_ERROR_ROWS</strong>: per le automazioni basate su una query, questa bind variable contiene il numero di righe in cui le azioni hanno restituito errori.</li>',
'    <li><strong>APEX$AUTOMATION_LASTRUN_ISO</strong>: contiene l''indicatore orario dell''esecuzione di automazione <em>precedente</em> nel formato <strong>YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM</strong>.</li>        ',
'</ul>',
'<p style="padding-top: 10px">',
'    Tenere presente che il package <strong>APEX_AUTOMATION</strong> potrebbe non essere disponibile nel servizio SQL abilitato per REST. Per aggiungere messaggi al log di esecuzione (<strong>LOG_WARN</strong>, <strong>LOG_INFO</strong>, <strong>LOG_E'
||'RROR</strong>), creare un''<em>altra</em> azione da eseguire nel <em>database locale.</em>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'PLSQL',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_05', 'P7022_REMOTE_SERVER_ID',
  'attribute_07', 'N')).to_clob
);
