,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Fornire il codice PL/SQL da eseguire. I valori di colonna recuperati dalla query di automazione sono disponibili come bind variable, in base al nome di colonna, ad esempio <strong>:EMPNO</strong>, <strong>:ENAME</strong> e cos\00EC via. Inoltre, &PRO')
||'DUCT_NAME. fornisce le bind variable generiche seguenti:',
'</p>',
'<ul>',
unistr('    <li><strong>APEX$AUTOMATION_ROW_PK</strong>: se \00E8 stata definita una colonna chiave primaria, questa bind variable contiene il valore di chiave primaria.</li>'),
'    <li><strong>APEX$AUTOMATION_ROW_NUM</strong>: per le automazioni basate su una query, questa bind variable contiene il numero di riga corrente.</li>',
'    <li><strong>APEX$AUTOMATION_ERROR_ROWS</strong>: per le automazioni basate su una query, questa bind variable contiene il numero di righe in cui almeno una delle azioni ha restituito errori.</li>',
'    <li><strong>APEX$AUTOMATION_LASTRUN_ISO</strong>: contiene l''indicatore orario dell''esecuzione di automazione <em>precedente</em> nel formato <strong>YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM</strong>.</li>        ',
'</ul>',
'<p>',
'    ',
'</p>',
'<p>',
'    Per scrivere messaggi nel log di esecuzione, usare le procedure <strong>LOG_INFO</strong>, <strong>LOG_WARN</strong> o <strong>LOG_ERROR</strong> nel package <strong>APEX_AUTOMATION</strong>.',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'PLSQL',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
