wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(2787302350432735.4004)
,p_plug_name=>'Informazioni: origini JSON'
,p_title=>'Informazioni'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--sideRegion:a-Region--noBorder'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4004)
,p_plug_display_sequence=>30
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Le <strong>origini JSON</strong> in &PRODUCT_NAME. sono costituite da informazioni sul proprietario e dal nome',
unistr('    di una tabella di database, che pu\00F2 essere una <em>tabella di raccolte JSON</em> o una tabella semplice con colonne contenenti'),
'    dati JSON. Le <em>tabelle di raccolte JSON</em> sono disponibili in Oracle Database 23ai o versioni successive. Inoltre,',
'    viene mantenuto un <strong>profilo dati</strong>, che mappa',
'    gli attributi JSON alle <em>colonne</em> che devono essere utilizzate dai componenti di &PRODUCT_NAME..',
'</p>',
'<p> ',
unistr('   \00C8 possibile definire un''origine JSON che utilizza il database locale e un servizio SQL abilitato'),
'    per REST. Una volta selezionate la tabella e la colonna da utilizzare, &PRODUCT_NAME. determina il profilo dati',
'    dai dati effettivi o dal file di <em>schema JSON</em> caricato.',
'</p>',
'<p>',
unistr('    Una volta creata, l''origine JSON sar\00E0 disponibile nei componenti di pagina, come <em>report</em>, <em>grafici</em>,'),
unistr('    <em>form</em> o altri, nonch\00E9 nei componenti condivisi, come <em>liste di valori</em>, <em>automazioni</em>'),
'    o altri. Il package PL/SQL APEX_EXEC consente l''accesso programmatico.',
'</p>',
'<p><a target="_blank" href="&SYSTEM_HELP_URL.">Ulteriori informazioni...</a></p>'))
,p_plug_display_condition_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_plug_display_when_condition=>'P7100_SOURCE_TYPE'
,p_plug_display_when_cond2=>'JSON_TABLE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
