 p_id=>wwv_flow_imp.id(2228476311748438.4004)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Distribute Items'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    case :P7110_LOCATION',
'        when ''LOCAL'' then  ',
'            :P7110_LOCAL_OWNER        := :P7110_OBJECT_OWNER;',
'            :P7110_LOCAL_WHERE_CLAUSE := :P7110_WHERE_CLAUSE;',
'            case :P7110_DOCUMENT_SOURCE_TYPE',
'                when ''DUALITY_VIEW''    then :P7110_LOCAL_DUALITY_VIEW    := :P7110_OBJECT_NAME;',
'                when ''JSON_TABLE''      then :P7110_LOCAL_JSON_TABLE      := :P7110_OBJECT_NAME;',
'                when ''JSON_COLLECTION'' then :P7110_LOCAL_JSON_COLLECTION := :P7110_OBJECT_NAME;',
'            end case;',
'               ',
'        when ''REMOTE'' then ',
'            :P7110_REMOTE_OWNER        := :P7110_OBJECT_OWNER;',
'            :P7110_REMOTE_WHERE_CLAUSE := :P7110_WHERE_CLAUSE;',
'            case :P7110_DOCUMENT_SOURCE_TYPE',
'                when ''DUALITY_VIEW''    then :P7110_REMOTE_DUALITY_VIEW    := :P7110_OBJECT_NAME;',
'                when ''JSON_TABLE''      then :P7110_REMOTE_JSON_TABLE      := :P7110_OBJECT_NAME;',
'                when ''JSON_COLLECTION'' then :P7110_REMOTE_JSON_COLLECTION := :P7110_OBJECT_NAME;',
'            end case;',
'    end case;',
'',
'    :P7110_PUBLISH_COMPONENT_TYPE := case when :P7110_DOCUMENT_SOURCE_TYPE = ''DUALITY_VIEW''',
'                                         then wwv_flow_shared_component_api.c_duality_view',
'                                         else wwv_flow_shared_component_api.c_json_source',
'                                     end;',
'    :P7110_SUBSCR_MSG_PREFIX      := case when :P7110_DOCUMENT_SOURCE_TYPE = ''DUALITY_VIEW''',
'                                         then ''SUBSCRIBE_DUALITY_VIEW''',
'                                         else ''SUBSCRIBE_JSON_SRC''',
'                                     end;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>2228476311748438.4004
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2228348792748437.4004)
,p_process_sequence=>20
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Consolidate items'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    :P7110_OBJECT_OWNER := case :P7110_LOCATION',
'                               when ''LOCAL''  then :P7110_LOCAL_OWNER',
'                               when ''REMOTE'' then :P7110_REMOTE_OWNER',
'                           end;',
'    :P7110_OBJECT_NAME  := case :P7110_LOCATION',
'                               when ''LOCAL'' then',
'                                   case when :P7100_SOURCE_TYPE = ''DUALITY_VIEW'' ',
'                                        then :P7110_LOCAL_DUALITY_VIEW',
'                                        when :P7110_DOCUMENT_SOURCE_TYPE = ''JSON_TABLE''',
'                                        then :P7110_LOCAL_JSON_TABLE',
'                                        when :P7110_DOCUMENT_SOURCE_TYPE = ''JSON_COLLECTION''',
'                                        then :P7110_LOCAL_JSON_COLLECTION',
'                                   end',
'                               when ''REMOTE'' then',
'                                   case when :P7100_SOURCE_TYPE = ''DUALITY_VIEW'' ',
'                                        then :P7110_REMOTE_DUALITY_VIEW',
'                                        when :P7110_DOCUMENT_SOURCE_TYPE = ''JSON_TABLE''',
'                                        then :P7110_REMOTE_JSON_TABLE',
'                                        when :P7110_DOCUMENT_SOURCE_TYPE = ''JSON_COLLECTION''',
'                                        then :P7110_REMOTE_JSON_COLLECTION',
'                                   end',
'                           end;',
'    :P7110_WHERE_CLAUSE := case :P7110_LOCATION',
'                               when ''LOCAL''  then :P7110_LOCAL_WHERE_CLAUSE',
'                               when ''REMOTE'' then :P7110_REMOTE_WHERE_CLAUSE',
'                           end;',
'end;',
'',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(2228822041748442.4004)
,p_internal_uid=>2228348792748437.4004
);
end;
