wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1289319416451864298.4004)
,p_name=>'P8101_ERROR_CHECKS'
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(1289319229814864296.4004)
,p_item_default=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_result varchar2(2000);',
'begin',
'    for l_check in (',
'        select code',
'          from wwv_flow_advisor_checks',
'         where is_default = ''Y'' )',
'    loop',
'        l_result := case when l_result is not null then l_result||'':'' end||',
'                    l_check.code;',
'    end loop;',
'    --',
'    return l_result;',
'end;'))
,p_item_default_type=>'FUNCTION_BODY'
,p_item_default_language=>'PLSQL'
,p_prompt=>'Errori:'
,p_source=>'ADVISOR_CHECKS'
,p_source_type=>'PREFERENCE'
,p_display_as=>'NATIVE_CHECKBOX'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select wwv_flow_escape.html(description) as d,',
'       code as r',
'  from ( select nvl(chk.description, wwv_flow_lang.system_message(''ADVISOR.CHECK.DESC_''||chk.code)) as description,',
'                chk.code,',
'                chk.order_seq',
'           from wwv_flow_advisor_categories cat,',
'                wwv_flow_advisor_checks chk',
'          where cat.code        = ''ERROR''',
'            and chk.category_id = cat.id',
'            and chk.code       <> ''VERIFY_CLOB_PROPERTY''',
'            and chk.is_custom   = ''N''',
'            and (  chk.flow_id is null',
'                or chk.flow_id = :FB_FLOW_ID )',
'       )',
' order by order_seq'))
,p_label_alignment=>'ABOVE'
,p_field_template=>wwv_flow_imp.id(561549638722251517.4004)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_output=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<dl>',
'    <dt>Riferimenti con sintassi di sostituzione</dt>',
'    <dd>L''elemento o la colonna di form tabulare a cui si fa riferimento con ''&amp;P999_NAME.'' esiste?</dd>',
'    <dt>Riferimenti con sintassi di colonna</dt>',
'    <dd>La colonna di report a cui si fa riferimento con #NAME# esiste?</dd>',
'    <dt>Riferimenti con sintassi di bind variable</dt>',
'    <dd>L''elemento o la colonna a cui si fa riferimento con '':P999_NAME'' esiste?</dd>',
'    <dt>Riferimenti dichiarativi di elementi di applicazione, elementi di pagina, colonne o filtri di report interattivi</dt>',
'    <dd>Gli elementi e gli alias di colonna specificati esistono?</dd>',
'    <dt>Il numero di pagina a cui si fa riferimento esiste</dt>',
'    <dd>Il numero di pagina a cui si fa riferimento esiste?</dd>',
unistr('    <dt>\00C8 codice SQL o PL/SQL valido</dt>'),
unistr('    <dd>Verifica la validit\00E0 dell''istruzione SQL o del codice PL/SQL.</dd>'),
