unistr('Indica se la protezione per lo stato delle sessioni \00E8 abilitata o disabilitata. Se \00E8 abilitata, questa funzione utilizza gli attributi di pagina <i>Protezione accesso pagina</i> e gli attributi di elemento <i>Protezione stato sessione</i> insieme ai ')
||'checksum che si trovano negli URL "f?p=". Questa funzione impedisce a utenti non autorizzati di modificare o di accedere agli URL o di modificare lo stato delle sessioni. ',
'<p />',
unistr('Se questa funzione \00E8 disabilitata, gli attributi di pagina ed elemento relativi alla protezione per lo stato delle sessioni vengono ignorati e i checksum non vengono inseriti nei checksum all''interno degli URL "f?p=" generati.')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'based_on', 'LOV',
  'format', 'PLAIN',
  'send_on_page_submit', 'N',
  'show_line_breaks', 'N')).to_clob
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(110698229152438343.4004)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'set session state security Standard'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for c1 in (select 1 from wwv_flows where id = :FB_FLOW_ID ',
'  and nvl(page_protection_enabled_y_n,''N'') = ''Y'' ) loop',
'    update wwv_flows set page_protection_enabled_y_n = ''N'' ',
'          where id = :FB_FLOW_ID ',
'          and security_group_id = wwv_flow_security.g_security_group_id;',
'end loop;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Errore durante la disabilitazione della protezione stato sessione dell''applicazione.'
,p_process_when_button_id=>wwv_flow_imp.id(109524628805275296.4004)
,p_process_success_message=>'Protezione stato sessione applicazione disabilitata.'
,p_internal_uid=>110698229152438343.4004
);
end;
