wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3201962690436619.4004)
,p_plug_name=>'Definizioni task'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4004)
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Le <strong>definizioni task</strong> definiscono le propriet\00E0 di un task umano e'),
'    vengono utilizzate per creare istanze del task e quindi eseguire l''azione appropriata,',
unistr('    ad esempio l''approvazione o il rifiuto di tali istanze. \00C8 anche possibile'),
'    prendere in carico, rilasciare, delegare e annullare i task.',
'<p>',
'<p>',
'    I <strong>partecipanti della definizione task</strong> definiscono i partecipanti di',
'    un task umano che possono eseguire azioni sul task. I partecipanti possono essere di tipo',
'    <strong>Proprietario potenziale</strong> o <strong>Amministratore aziendale',
'    </strong>.',
'<p>',
'<p>',
'    I <strong>parametri di definizione task</strong> definiscono i parametri',
'    di un task umano. Di solito, sono gli attributi di un sistema di record per',
unistr('    il quale \00E8 stato definito il task e costituiscono il payload del task.'),
'<p>',
'</p>',
'    Le <strong>azioni di definizione task</strong> vengono attivate una sola volta per un evento eseguito nel task.',
'    Gli eventi possono essere:',
'</p>',
'<ul>',
'    <li><strong>Prendi in carico</strong></li>',
'    <li><strong>Completa</strong></li>',
'    <li><strong>Delega</strong></li>',
'    <li><strong>Aggiorna commento</strong></li>',
unistr('    <li><strong>Aggiorna priorit\00E0</strong></li>'),
'    <li><strong>Aggiorna parametro</strong></li>',
'    <li><strong>Rilascia</strong></li>',
'    <li><strong>Annulla</strong></li>',
'    <li><strong>Crea</strong></li>',
'    <li><strong>Richiedi informazioni</strong></li>',
'    <li><strong>Sottometti informazioni</strong></li>',
'    <li><strong>Prima della scadenza</strong></li>',
'    <li><strong>Scadenza</strong></li>',
'</ul>',
'<p>',
'    <a target="_blank" href="&SYSTEM_HELP_URL.">Ulteriori informazioni...</a>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
