wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(130920038509152702.4004)
,p_validation_name=>'Validate Expire Actions'
,p_validation_sequence=>150
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_expire_events_exist varchar2(1);',
'    ',
'begin',
'    select 1 into l_expire_events_exist',
'      from sys.dual',
'     where exists (select td.id',
'      from wwv_flow_task_def_actions ta,wwv_flow_task_defs td',
'     where ta.task_def_id = :P9502_ID',
'       and td.id = :P9502_ID',
'       and ta.on_event in (''EXPIRE'',''BEFORE_EXPIRE'')',
'       and (:P9502_DUE_ON_TYPE is null or :P9502_EXPIRATION_POLICY =''NONE'')',
'       and ta.security_group_id = :WORKSPACE_ID);',
'',
'     return false;',
'exception   ',
'    when no_data_found then ',
'     return true;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'La definizione del task deve definire il <strong>Tipo di data scadenza</strong> e il <strong>Criterio di scadenza</strong> per l''utilizzo di azioni per gli eventi <strong>Prima della scadenza</strong> e <strong>Scadenza</strong>.'
,p_when_button_pressed=>wwv_flow_imp.id(2933021960391287.4004)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
