,p_process_name=>'Set Due On Result'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
':P9502_DUE_ON_RESULT :=',
'    case  :P9502_DUE_ON_TYPE',
'        when ''INTERVAL''             then :P9502_DUE_ON_INTERVAL',
'        when ''SCHEDULER_EXPRESSION'' then :P9502_DUE_ON_SCHEDULER_VAL',
'        when ''SQL_QUERY''            then :P9502_DUE_ON_QUERY',
'        when ''FUNCTION_BODY''        then :P9502_DUE_ON_FUNCTION_BODY',
'        when ''EXPRESSION''           then :P9502_DUE_ON_EXPRESSION',
'        else  null',
'    end;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>4400695478135802.4004
);
