,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set Due On Language'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
':P9502_DUE_ON_LANG :=',
'    case  :P9502_DUE_ON_TYPE ',
'        when ''SQL_QUERY'' then ''SQL''',
'        when ''FUNCTION_BODY'' then ''PLSQL''',
'        when ''EXPRESSION'' then ''PLSQL''',
'        else  null',
'    end;',
'end;'))
,p_process_clob_language=>'PLSQL'
