wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(31864742114684957.4004)
,p_plug_name=>' Esempi'
,p_parent_plug_id=>wwv_flow_imp.id(3379050589607834.4004)
,p_region_template_options=>'#DEFAULT#:is-collapsed:a-Region--noBorder'
,p_plug_template=>wwv_flow_imp.id(689970285456172024.4004)
,p_plug_display_sequence=>30
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Esempio 1: inviare un messaggio di posta elettronica. In questo caso si presume l''esistenza di un modello di posta elettronica denominato <strong>ORDER</strong>, con i segnaposto usati nel ',
'    parametro ',
'    <strong>p_placeholders</strong>.',
'</p>',
'<pre>',
'begin',
'    apex_mail.send (',
'        p_template_static_id => ''ORDER'',',
'        p_placeholders       => ''{ "ORDER_NUMBER": '' || :ORDER_NUMBER ||',
'                                  ''"ORDER_DATE":"''   || to_char( :ORDER_DATE, ''YYYY-MM-DD'' ) || ''", ''',
'                                  ''"ORDER_TOTAL":''   || :ORDER_TOTAL || ',
'                                ''}'',',
'        p_to                 => ''some_user@somewhere.com'' );',
'end;',
'</pre>',
'<p>',
unistr('    Esempio 2: inserire una riga in un''altra tabella. Se il valore :SAL \00E8 NULL, nel log della cronologia dei task viene scritto un messaggio.'),
'</p>',
'<pre>',
'begin',
'    insert into other_table( empno, ename, sal )',
'                     values( :EMPNO, :ENAME, :SAL );',
'    if :SAL is null then',
'        apex_approval.add_to_history( ''EMPNO '' || :APEX$TASK_PK ||''  has a NULL Salary'');',
'    end if;',
'end;',
'</pre>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
