wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1974380900697179.4004)
,p_name=>'P9506_LOCAL_CODE'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(92085503084145721.4004)
,p_prompt=>'Codice'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>80
,p_cMaxlength=>32767
,p_cHeight=>10
,p_field_template=>wwv_flow_imp.id(561549638722251517.4004)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Fornire il codice PL/SQL da eseguire. I valori di colonna recuperati dalla query di azione definizione task sono disponibili come bind variable, in base al nome di colonna, ad esempio <strong>:EMPNO</strong>, <strong>:ENAME</strong> e cos\00EC via. I')
||'noltre, APEX fornisce le bind variable generiche seguenti:',
'</p>',
'<ul>',
unistr('    <li><strong>APEX$TASK_PK</strong>: se \00E8 stata definita una colonna chiave primaria, questa bind variable contiene il valore di chiave primaria.</li>'),
'    <li><strong>APEX$TASK_ID</strong>: questa bind variable contiene l''ID del task per il quale viene definita l''azione.</li>',
'    <li><strong>APEX$TASK_SUBJECT</strong>: questa bind variable contiene l''oggetto del task per il quale viene definita l''azione.</li>',
'    <li><strong>APEX$TASK_STATE</strong>: questa bind variable contiene lo stato corrente del task per il quale viene definita l''azione.</li>',
'    <li><strong>APEX$TASK_OUTCOME</strong>: questa bind variable contiene il risultato del task per il quale viene definita l''azione. Tale variabile viene popolata solo per i task che hanno stato <strong>Completato</strong>.</li>',
'    <li><strong>APEX$TASK_CREATED_ON</strong>: contiene l''indicatore orario della creazione del task, in formato <strong>YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM</strong>.</li>        ',
'    <li><strong>APEX$TASK_INITIATOR</strong>: contiene l''utente che ha avviato il task. Tal valore utilizza come impostazione predefinita l''utente che ha eseguito il login se non specificato in modo esplicito come parte del tipo di processo pagina <s'
||'trong>Task umano - Creazione</strong>.</li>        ',
'    <li><strong>APEX$TASK_DUE_ON</strong>: contiene l''indicatore orario che indica la scadenza del task specifico in formato <strong>YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM</strong>.</li>        ',
unistr('    <li><strong>APEX$TASK_OWNER</strong>: contiene l''utente al quale il task \00E8 attualmente assegnato.</li>'),
'    <li> I parametri relativi alla definizione del task sono disponibili anche come bind variable.</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'PLSQL',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
