,p_cSize=>65
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4004)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Se si specifica un codice lingua, il processo cercher\00E0 il modello da una traduzione dell''applicazione per questa lingua. Se non esiste una traduzione, il processo utilizza la lingua primaria dell''applicazione. \00C8 supportata la sintassi di sostituzi')
